registrarDetalhes({"PT-001":{"cognitivo":{"motivo":"Cobrar o uso do relativo 'cujo', que exige relação de posse entre antecedente e consequente.","palavraCritica":"cujos"},"comentario":{"resolucao":"ERRADO. 'Os quais' retoma 'os índices de criminalidade' como sujeito de 'dependem'. 'Cujo' expressa posse e deve anteceder substantivo ('cujos índices'), o que tornaria o período agramatical: 'a redução dos índices..., cujos dependem...' não tem estrutura possível.","fundamento":"Gramática normativa — emprego dos pronomes relativos.","macete":"CUJO = 'de quem/de que' + coisa possuída, sem artigo depois.","erroComum":"Aceitar 'cujo' como sinônimo culto de 'o qual'.","comoBancaPensa":"Reescritura é o formato nº 1 de Português no CEBRASPE: julgue sempre SINTAXE + SENTIDO."}},"PT-002":{"cognitivo":{"motivo":"Diferença entre conectivo adversativo coordenativo e conjunção concessiva subordinativa.","palavraCritica":"Conquanto (= embora)"},"comentario":{"resolucao":"ERRADO. 'No entanto' é conectivo adversativo que liga períodos independentes. 'Conquanto' é conjunção subordinativa concessiva (equivale a 'embora') e exigiria reestruturação do período (verbo no subjuntivo e oração principal), o que não ocorre na simples substituição.","fundamento":"Gramática normativa — coordenação e subordinação.","macete":"Troca segura: no entanto ↔ porém ↔ contudo ↔ entretanto ↔ todavia.","erroComum":"Aceitar troca entre conectivo de grupo diferente por proximidade de sentido.","comoBancaPensa":"É a segunda cobrança favorita em Português: substituição de conectivo com mudança de classe gramatical."}},"PT-003":{"cognitivo":{"motivo":"Combinar classificação correta (aposto) com consequência falsa (supressão possível).","palavraCritica":"manteria a correção"},"comentario":{"resolucao":"ERRADO. O trecho é, de fato, aposto explicativo referido a 'A segurança pública' — mas exatamente por isso as vírgulas duplas são obrigatórias na intercalação. A supressão fundiria aposto e sujeito sem sinalização, comprometendo a correção gramatical.","fundamento":"Gramática normativa — pontuação do aposto (estrutura análoga à do art. 144, caput, da CF).","macete":"Explicação intercalada = 'entre parênteses' = vírgulas obrigatórias dos dois lados.","erroComum":"Validar o item pela metade verdadeira.","comoBancaPensa":"Verdade + falso emendado: o acerto parcial compra a confiança do candidato."}},"PT-004":{"cognitivo":{"motivo":"Cobrar a justificativa da crase (regência + artigo), formato típico da banca.","palavraCritica":"termo regente"},"comentario":{"resolucao":"CERTO. 'Acesso' rege a preposição 'a' e 'informação' admite o artigo 'a' → crase. 'Essencial' rege 'a' e 'consolidação' admite 'a' → crase. A justificativa sintática (preposição + artigo) é a mesma nos dois casos.","fundamento":"Gramática normativa — regência e crase.","macete":"Troque pelo masculino: apareceu 'AO', crase confirmada.","erroComum":"Buscar diferenças de regência inexistentes por desconfiança excessiva.","comoBancaPensa":"Também cobra itens CERTOS de crase — julgue pela regra, não pelo medo."}},"PT-005":{"cognitivo":{"motivo":"Cobrar a impessoalidade do verbo 'fazer' indicando tempo decorrido.","palavraCritica":"Fazem (deveria ser 'Faz')"},"comentario":{"resolucao":"ERRADO. O verbo 'fazer' indicando tempo decorrido é impessoal (sem sujeito) e permanece invariável na 3ª pessoa do singular: 'Faz cinco anos'. 'Cinco anos' é objeto, não sujeito. A verbalização no plural viola a norma-padrão.","fundamento":"Gramática normativa — verbos impessoais (fazer/haver de tempo).","macete":"Troque 'fazer' por 'haver': 'Há cinco anos' (nunca 'Hão cinco anos'). Se cabe 'há', fica singular.","erroComum":"Flexionar 'fazer'/'haver' de tempo como se 'anos' fosse sujeito.","comoBancaPensa":"Verbo impessoal com expressão de tempo no plural é isca clássica de concordância."}},"PT-006":{"cognitivo":{"motivo":"Cobrar a regra da crase facultativa/vedada em 'a distância' × 'à distância de'.","palavraCritica":"a distância × à distância de"},"comentario":{"resolucao":"CERTO. Segundo a norma-padrão, não se emprega crase em 'a distância' quando a expressão não está determinada por adjunto especificador. A crase seria obrigatória em 'à distância de cinquenta metros'. Portanto, a ausência de acento está correta.","fundamento":"Gramática normativa — crase em locuções adverbiais.","macete":"'Ficar a distância' = sem crase; 'ficar à distância de X' = com crase.","erroComum":"Acentuar por reflexo, só porque 'distância' é feminino.","comoBancaPensa":"Crase em expressões 'a distância', 'a olho nu', 'a bordo' é campo minado da banca."}},"PT-007":{"cognitivo":{"motivo":"Cobrar as palavras atrativas que exigem próclise.","palavraCritica":"nunca / se viu"},"comentario":{"resolucao":"CERTO. Advérbios de negação como 'nunca' são palavras atrativas que impõem a próclise: 'Nunca se viu'. A ênclise ('viu-se') seria incorreta nesse contexto.","fundamento":"Gramática normativa — colocação pronominal (fatores de próclise).","macete":"Tem palavra 'negativa/atrativa' antes do verbo? Pronome cola ANTES (próclise).","erroComum":"Usar ênclise após negação, advérbio ou pronome relativo.","comoBancaPensa":"Colocação pronominal é cobrada por meio de reescrita — atenção ao gatilho atrativo."}},"PT-008":{"cognitivo":{"motivo":"Cobrar a dupla regência do verbo 'assistir' conforme o sentido.","palavraCritica":"assistir a (presenciar) × assistir (ajudar)"},"comentario":{"resolucao":"ERRADO. No sentido de presenciar/ver, 'assistir' é transitivo indireto e exige a preposição 'a': 'assistiram AO laudo'. Como transitivo direto, 'assistir' significa prestar assistência ('assistir o doente'). A frase inverteu a regência.","fundamento":"Gramática normativa — regência do verbo 'assistir'.","macete":"Ver = assistir A. Ajudar = assistir (sem preposição). Cabe também 'assistir a' no sentido de caber direito (assiste-lhe o direito).","erroComum":"Usar 'assistir' (presenciar) sem a preposição 'a'.","comoBancaPensa":"Verbos de dupla regência (assistir, visar, aspirar, proceder) são pratos cheios para C/E."}},"PT-009":{"cognitivo":{"motivo":"Cobrar a conversão ativa→passiva analítica, tema recorrente de reescritura.","palavraCritica":"objeto vira sujeito; sujeito vira agente da passiva"},"comentario":{"resolucao":"CERTO. Na voz passiva analítica, o objeto direto ('o inquérito') torna-se sujeito, o verbo assume a forma 'ser + particípio' no mesmo tempo ('foi instaurado') e o sujeito original vira agente da passiva ('pela autoridade policial'). O sentido é preservado.","fundamento":"Gramática normativa — vozes verbais.","macete":"Quem sofre a ação vira sujeito; quem pratica vira 'agente da passiva' (introduzido por 'por').","erroComum":"Mudar o tempo verbal ou trocar o agente na conversão.","comoBancaPensa":"Conversão de voz é reescritura clássica: julgue tempo verbal + agente."}},"PT-010":{"cognitivo":{"motivo":"Cobrar a vedação da vírgula entre sujeito e verbo.","palavraCritica":"vírgula separando sujeito e verbo (proibida)"},"comentario":{"resolucao":"ERRADO. A norma-padrão veda a vírgula única entre o sujeito ('Os agentes responsáveis pela investigação') e o verbo ('apresentaram'). A pontuação só seria admissível para isolar um termo intercalado, delimitado por um PAR de vírgulas.","fundamento":"Gramática normativa — pontuação (sujeito × predicado).","macete":"Uma vírgula sozinha entre sujeito e verbo = erro. Só vale par de vírgulas isolando intercalado.","erroComum":"Isolar o sujeito com uma única vírgula.","comoBancaPensa":"Reescritura de pontuação testa a proibição sujeito-verbo."}},"PT-011":{"cognitivo":{"motivo":"Cobrar a noção de paralelismo sintático.","palavraCritica":"coordenar termos de mesma função/estrutura"},"comentario":{"resolucao":"CERTO. Há quebra de paralelismo ao coordenar um substantivo ('cautela') com uma oração ('que os agentes agissem com discrição'). A correção iguala as estruturas: dois substantivos coordenados ('cautela e discrição') ou duas orações.","fundamento":"Gramática normativa — paralelismo sintático.","macete":"Coordenou coisas diferentes (nome + oração)? Quebrou o paralelismo. Iguale a estrutura.","erroComum":"Não identificar a assimetria entre nome e oração coordenados.","comoBancaPensa":"Paralelismo é cobrado por meio de reescritura equivalente."}},"PT-012":{"cognitivo":{"motivo":"Cobrar a regência do verbo 'preferir'.","palavraCritica":"preferir A (não 'do que')"},"comentario":{"resolucao":"ERRADO. Na norma-padrão, 'preferir' rege a preposição 'a': prefere-se uma coisa A outra. A construção com 'do que' ('prefiro atuar em campo do que...') é condenada. O correto: 'prefiro atuar em campo a trabalhar no gabinete'.","fundamento":"Gramática normativa — regência do verbo 'preferir'.","macete":"Preferir + 'a'. Sem 'mais', sem 'do que', sem 'antes'.","erroComum":"Usar 'do que' após 'preferir'.","comoBancaPensa":"Regência de 'preferir' é cobrada validando a forma coloquial."}},"PT-013":{"cognitivo":{"motivo":"Distinguir conector causal (uma vez que) de concessivo (ainda que).","palavraCritica":"causa (uma vez que) × concessão (ainda que)"},"comentario":{"resolucao":"ERRADO. 'Uma vez que' introduz relação de CAUSA (equivale a 'porque'); 'ainda que' expressa CONCESSÃO (equivale a 'embora'). A substituição inverteria a relação lógica entre as orações, alterando o sentido do período.","fundamento":"Gramática normativa — conjunções causais e concessivas.","macete":"Uma vez que = porque. Ainda que = embora. São valores opostos.","erroComum":"Trocar conectivos de valores lógicos diferentes por soarem parecidos.","comoBancaPensa":"Substituição de conectivo que altera a relação de sentido — formato nº 1 de Português."}},"PT-014":{"cognitivo":{"motivo":"Cobrar a referência do pronome oblíquo átono.","palavraCritica":"'o' = relatório"},"comentario":{"resolucao":"CERTO. O pronome oblíquo átono 'o', em 'encaminhou-o', retoma 'o relatório' (objeto direto), estabelecendo a coesão: a autoridade recebeu o relatório e o encaminhou ao MP.","fundamento":"Gramática normativa — pronomes oblíquos e coesão referencial.","macete":"'o/a' retoma coisa (objeto). 'lhe' retoma pessoa (objeto indireto).","erroComum":"Atribuir o pronome ao sujeito em vez do objeto.","comoBancaPensa":"Referência pronominal é cobrança recorrente de coesão."}},"PT-015":{"cognitivo":{"motivo":"Cobrar a concordância com sujeito composto anteposto ao verbo.","palavraCritica":"sujeito composto → verbo no plural"},"comentario":{"resolucao":"ERRADO. O sujeito é composto ('O delegado e o escrivão') e antecede o verbo; logo, a concordância exige o plural: 'analisaram'. O emprego no singular ('analisou') viola a norma-padrão.","fundamento":"Gramática normativa — concordância verbal (sujeito composto).","macete":"Sujeito composto antes do verbo = plural. 'A e B analisaram'.","erroComum":"Concordar o verbo com apenas um dos núcleos.","comoBancaPensa":"Sujeito composto anteposto com verbo no singular é isca clássica."}},"PT-016":{"cognitivo":{"motivo":"Cobrar equivalência entre conectivos de mesmo valor semântico (causal).","palavraCritica":"porquanto = porque (causal)"},"comentario":{"resolucao":"CERTO. “Uma vez que” e “porquanto” são conjunções de valor CAUSAL (equivalem a “porque”). A substituição mantém a correção gramatical e a relação de causa entre a necessidade de qualificação dos quadros e a compreensão técnica dos meios digitais.","fundamento":"Gramática normativa — conjunções subordinativas causais.","macete":"Causais: porque, porquanto, uma vez que, já que, visto que — intercambiáveis.","erroComum":"Achar que 'porquanto' tem valor conclusivo.","comoBancaPensa":"Alterna trocas válidas e inválidas de conectivo para testar o valor lógico."}},"PT-017":{"cognitivo":{"motivo":"Distinguir conectivo adversativo de conclusivo.","palavraCritica":"contudo (oposição) × portanto (conclusão)"},"comentario":{"resolucao":"ERRADO. “Contudo” é conectivo ADVERSATIVO: introduz a ressalva de que a técnica não substitui o raciocínio investigativo, contrapondo-se ao parágrafo anterior. “Portanto” é CONCLUSIVO e transformaria a ressalva em consequência, alterando a coerência argumentativa.","fundamento":"Gramática normativa — coordenação (adversativas e conclusivas).","macete":"Contudo = oposição. Portanto = conclusão. Não se trocam.","erroComum":"Substituir conectivos de valores lógicos distintos.","comoBancaPensa":"Troca de conectivo que altera a articulação do argumento — formato nº 1 de Português."}},"PT-018":{"cognitivo":{"motivo":"Cobrar a crase resultante de regência verbal + artigo feminino.","palavraCritica":"preposição 'a' (regência) + artigo 'a' (observância)"},"comentario":{"resolucao":"CERTO. O verbo “submeter-se” rege a preposição “a” (submeter-se A algo), e “observância” é substantivo feminino que admite o artigo “a”. Da fusão resulta a crase: “submete-se à observância do devido processo legal”. O teste do masculino confirma (“submete-se ao cumprimento”).","fundamento":"Gramática normativa — regência verbal e crase.","macete":"Trocou por masculino e virou 'ao'? Então no feminino é 'à'.","erroComum":"Não identificar a preposição exigida pela regência do verbo.","comoBancaPensa":"Reescritura que cria a condição de crase testa regência + artigo simultaneamente."}},"PT-019":{"cognitivo":{"motivo":"Distinguir 'tampouco' (= também não) de 'tão pouco' (intensidade/quantidade).","palavraCritica":"tampouco = também não"},"comentario":{"resolucao":"ERRADO. No contexto, “tampouco” significa “também não” (o domínio das ferramentas não dispensa a análise crítica, nem tampouco a observância das garantias). Já “tão pouco” exprime pequena quantidade/intensidade. As formas não são intercambiáveis: a alteração comprometeria o sentido.","fundamento":"Gramática normativa — semântica e ortografia.","macete":"Cabe 'também não'? Escreve junto: tampouco.","erroComum":"Tratar as formas homófonas como equivalentes.","comoBancaPensa":"Explora pares homófonos de sentidos distintos (tampouco/tão pouco, senão/se não)."}},"PT-020":{"cognitivo":{"motivo":"Cobrar a regra de pontuação da conjunção intercalada/deslocada.","palavraCritica":"contudo intercalado entre vírgulas"},"comentario":{"resolucao":"CERTO. Quando a conjunção adversativa é deslocada de sua posição inicial e intercalada no período, ela deve ser isolada por vírgulas — exatamente o caso de “Não se trata, contudo, de substituir”. A pontuação sinaliza o deslocamento.","fundamento":"Gramática normativa — pontuação de conjunções deslocadas.","macete":"Conjunção no meio da oração = entre vírgulas.","erroComum":"Classificar as vírgulas como isoladoras de aposto.","comoBancaPensa":"Pede a JUSTIFICATIVA da vírgula, não apenas se ela está correta."}},"PT-021":{"cognitivo":{"motivo":"Cobrar o valor semântico do conectivo 'ou seja'.","palavraCritica":"ou seja"},"comentario":{"resolucao":"CERTO. A expressão 'ou seja' tem valor explicativo: retoma 'cadeia de custódia' e a define ('o conjunto de procedimentos que garante a rastreabilidade...'), função típica desse conectivo.","fundamento":"Gramática — classe dos conectivos explicativos.","macete":"Conectivo explicativo = reformula/define o termo anterior.","erroComum":"Atribuir valor adversativo ou condicional ao conectivo.","comoBancaPensa":"Item de fixação sobre o valor semântico de conectivos textuais."}},"PT-022":{"cognitivo":{"motivo":"Cobrar a classificação de orações subordinadas adverbiais.","palavraCritica":"Quando"},"comentario":{"resolucao":"CERTO. 'Quando essa cadeia é rompida' é oração subordinada adverbial temporal, pois situa no tempo a circunstância em que ocorre o fato descrito na oração principal ('abre-se margem para que a defesa questione...').","fundamento":"Gramática — orações subordinadas adverbiais (classificação).","macete":"Quando = sempre temporal, nunca condicional.","erroComum":"Classificar 'quando' como conjunção condicional.","comoBancaPensa":"Item clássico de classificação de orações."}},"PT-023":{"cognitivo":{"motivo":"Cobrar a regência correta do verbo 'questionar'.","palavraCritica":"transitivo indireto"},"comentario":{"resolucao":"ERRADO. O verbo 'questionar', no trecho, é transitivo DIRETO ('questionar algo'), e não indireto — o complemento 'a idoneidade da prova' completa o verbo sem preposição exigida por ele.","fundamento":"Gramática — regência verbal (transitividade).","macete":"Questionar algo = VTD. Não confundir com verbos que exigem preposição (ex.: 'duvidar DE algo').","erroComum":"Classificar 'questionar' como VTI por analogia com verbos similares que exigem preposição.","comoBancaPensa":"Testa se o candidato verifica a real regência antes de aceitar a classificação proposta."}},"PT-024":{"cognitivo":{"motivo":"Cobrar a justificativa correta do uso da crase.","palavraCritica":"à disciplina"},"comentario":{"resolucao":"CERTO. A crase em 'à disciplina' resulta da regência de 'sujeitar-se a' (que exige a preposição 'a') combinada com o artigo feminino que acompanha 'disciplina', configurando corretamente a fusão preposição+artigo.","fundamento":"Gramática — regras de crase (fusão de preposição e artigo).","macete":"Verbo/nome que rege 'a' + palavra feminina determinada por artigo = crase.","erroComum":"Negar a crase por não perceber a regência do verbo pronominal.","comoBancaPensa":"Testa o raciocínio completo de justificativa da crase, não apenas o reconhecimento do acento."}},"PT-025":{"cognitivo":{"motivo":"Cobrar a identificação correta do sujeito gramatical.","palavraCritica":"sujeito composto"},"comentario":{"resolucao":"ERRADO. O sujeito de 'substitui' é apenas 'nenhuma inovação' (sujeito simples, singular) — 'tecnologia' integra outra oração do mesmo período ('Ainda que a tecnologia tenha avançado...'), não compondo o sujeito da oração em análise. A concordância no singular está correta.","fundamento":"Gramática — concordância verbal (identificação do sujeito).","macete":"Delimite a oração antes de identificar o sujeito — não misture orações do mesmo período.","erroComum":"Somar elementos de orações diferentes para 'criar' um sujeito composto inexistente.","comoBancaPensa":"Testa se o candidato delimita corretamente os limites oracionais antes de analisar a concordância."}},"PT-026":{"cognitivo":{"motivo":"Cobrar a distinção entre informação acessória (exemplificativa) e essencial.","palavraCritica":"informação essencial ... comprometeria"},"comentario":{"resolucao":"ERRADO. O trecho isolado pelos travessões é um aposto explicativo de natureza exemplificativa ('a exemplo de'), portanto acessório: sua supressão não compromete a estrutura sintática do período ('Ainda que a tecnologia tenha avançado significativamente nas últimas décadas, nenhuma inovação substitui...' permanece completo e correto).","fundamento":"Gramática — pontuação (travessão e aposto explicativo).","macete":"Exemplo entre travessões/vírgulas = acessório, suprimível sem quebrar a sintaxe.","erroComum":"Considerar todo aposto como 'essencial' apenas por conter informação relevante.","comoBancaPensa":"Restringe indevidamente o caráter acessório do aposto exemplificativo."}},"PT-027":{"cognitivo":{"motivo":"Cobrar o valor semântico do advérbio/conectivo 'afinal'.","palavraCritica":"Afinal"},"comentario":{"resolucao":"CERTO. 'Afinal', no período final, introduz a justificativa da afirmação anterior (a insubstituibilidade da disciplina metodológica), com valor semântico conclusivo/explicativo, equivalente a 'pois' ou 'com efeito'.","fundamento":"Gramática — valores semânticos de conectivos e advérbios.","macete":"'Afinal' explicativo = justifica; não confundir com o sentido temporal de 'por fim'.","erroComum":"Atribuir a 'afinal' valor adversativo ou puramente temporal.","comoBancaPensa":"Item de fixação sobre polissemia de conectivos comuns."}},"PT-028":{"cognitivo":{"motivo":"Cobrar a regência nominal correta do substantivo 'idoneidade'.","palavraCritica":"desvio de regência"},"comentario":{"resolucao":"ERRADO. O substantivo 'idoneidade' rege-se corretamente pela preposição 'de' ('idoneidade de algo'), como empregado no texto ('idoneidade da prova' = idoneidade + de + a prova). Não existe, na norma-padrão, exigência de regência pela preposição 'a' para esse substantivo — a afirmação cria uma exigência inexistente.","fundamento":"Gramática — regência nominal.","macete":"Idoneidade DE (algo/alguém) — regência consagrada, sem variação.","erroComum":"Aceitar uma regra de regência fabricada sem verificar o uso padrão real.","comoBancaPensa":"Cria uma exigência gramatical que não existe, testando se o candidato a aceita sem questionar."}},"PT-029":{"cognitivo":{"motivo":"Cobrar o valor circunstancial correto de orações reduzidas de gerúndio.","palavraCritica":"concessiva"},"comentario":{"resolucao":"ERRADO. A oração reduzida de gerúndio expressa circunstância de MODO (indica como os peritos cumprem a disciplina metodológica), e não concessão — não há, no trecho, qualquer ideia de contraste ou oposição que justificasse a equivalência com 'embora registrem'.","fundamento":"Gramática — orações reduzidas (valores circunstanciais do gerúndio).","macete":"Gerúndio descrevendo 'como' a ação principal se realiza = modo.","erroComum":"Atribuir valor concessivo a qualquer oração reduzida de gerúndio, independentemente do contexto.","comoBancaPensa":"Testa a real compreensão do valor circunstancial, não apenas o reconhecimento da forma verbal."}},"PT-030":{"cognitivo":{"motivo":"Cobrar a função das vírgulas na construção de apostos explicativos.","palavraCritica":"aposto explicativo"},"comentario":{"resolucao":"CERTO. As vírgulas isolam corretamente um aposto explicativo, introduzido pela expressão 'ou seja', que retoma e define o termo 'cadeia de custódia' mencionado anteriormente.","fundamento":"Gramática — pontuação (vírgula em aposto explicativo).","macete":"Vírgula antes e depois de 'ou seja' = sinal de aposto explicativo.","erroComum":"Não identificar a estrutura apositiva isolada por vírgulas.","comoBancaPensa":"Item de fixação sobre a função sintática da pontuação."}},"PT-031":{"cognitivo":{"motivo":"Cobrar a distinção entre voz passiva sintética e indeterminação do sujeito.","palavraCritica":"sujeito indeterminado"},"comentario":{"resolucao":"ERRADO. Trata-se de voz passiva sintética (pronome apassivador 'se'), e não de indeterminação do sujeito: o verbo 'abrir' é transitivo direto ('abrir margem'), e 'margem' funciona como sujeito paciente, concordando corretamente no singular com 'abre-se'.","fundamento":"Gramática — funções do 'se' (voz passiva sintética × indeterminação do sujeito).","macete":"Se o substantivo após o 'se' concorda em número com o verbo, é voz passiva sintética — não indeterminação.","erroComum":"Classificar toda construção com 'se' e verbo intransitivo aparente como indeterminação do sujeito.","comoBancaPensa":"Testa a distinção fina entre as duas funções mais confundidas do 'se' na sintaxe portuguesa."}},"PT-032":{"cognitivo":{"motivo":"Cobrar a identificação da tipologia textual predominante.","palavraCritica":"dissertativo-argumentativa"},"comentario":{"resolucao":"CERTO. O texto é predominantemente dissertativo-argumentativo: expõe informações técnicas sobre a cadeia de custódia e defende, com justificativas explícitas ('Por essa razão', 'Afinal'), a tese de que nenhuma tecnologia substitui a disciplina metodológica na cena do crime.","fundamento":"Teoria da comunicação — tipologia textual (dissertação argumentativa).","macete":"Presença de tese + justificativas + conectivos argumentativos = dissertativo-argumentativo.","erroComum":"Classificar o texto como meramente expositivo/descritivo, ignorando a defesa de tese.","comoBancaPensa":"Item de fixação sobre reconhecimento de tipologia textual predominante."}},"PT-033":{"cognitivo":{"motivo":"Fixar o pareamento entre os dois sentidos.","palavraCritica":"denotativo ... conotativo"},"comentario":{"resolucao":"CERTO. O sentido denotativo é o literal, dicionarizado e objetivo; o conotativo é o figurado, construído por associações subjetivas e dependente do contexto.","fundamento":"Semântica — denotação e conotação.","macete":"Denota = dicionário.","erroComum":"Inverter os conceitos.","comoBancaPensa":"Par correto entre termos foneticamente próximos."}},"PT-034":{"cognitivo":{"motivo":"Fixar a distinção entre os dois mecanismos textuais.","palavraCritica":"formal ... lógica de sentido"},"comentario":{"resolucao":"CERTO. A coesão opera na superfície textual, pelos mecanismos de referência, substituição, elipse e conexão; a coerência situa-se no plano do sentido, garantindo unidade lógica ao texto. São independentes: há textos coesos porém incoerentes.","fundamento":"Linguística textual — coesão e coerência.","macete":"Coesão = forma; coerência = sentido.","erroComum":"Tratar como sinônimos.","comoBancaPensa":"Par correto entre conceitos que o candidato costuma fundir."}},"PT-035":{"cognitivo":{"motivo":"Cobrar a distinção entre frase e oração, que sustenta toda a análise sintática posterior.","palavraCritica":"pode constituir-se sem verbo algum"},"comentario":{"resolucao":"CERTO. Frase é todo enunciado com sentido completo, com ou sem verbo — as frases nominais são o caso típico (\"Silêncio!\", \"Que sufoco!\"). Oração é a unidade construída em torno de um verbo ou locução verbal, tenha ou não sentido completo. Período é a frase formada por uma ou mais orações, encerrado por pontuação forte.","fundamento":"Nomenclatura Gramatical Brasileira — frase, oração e período.","macete":"Frase pode não ter verbo. Oração tem que ter. Período é frase com oração.","erroComum":"Usar frase e oração como sinônimos.","comoBancaPensa":"Item 'limpo' de conceituação, que abre o bloco de sintaxe."}},"PT-036":{"cognitivo":{"motivo":"Cobrar os mesmos conceitos com os rótulos permutados.","palavraCritica":"oração ... sem verbo"},"comentario":{"resolucao":"ERRADO. As definições estão trocadas. Quem prescinde de verbo é a FRASE; quem se organiza obrigatoriamente em torno de um verbo é a ORAÇÃO. \"Fogo!\" é frase e não é oração; \"que o delegado assinasse o auto\" é oração e, isolada, não tem sentido completo.","fundamento":"Nomenclatura Gramatical Brasileira — frase e oração.","macete":"Sentido completo → frase. Verbo → oração. São critérios diferentes.","erroComum":"Trocar o critério de cada conceito.","comoBancaPensa":"Permuta duas definições que o candidato reconhece isoladamente, mas não sabe atribuir."}},"PT-037":{"cognitivo":{"motivo":"Contraexemplo: dois conceitos vizinhos aplicados corretamente a exemplos distintos.","palavraCritica":"oração absoluta"},"comentario":{"resolucao":"CERTO. O período simples tem uma só oração, chamada absoluta justamente por não se subordinar nem se coordenar a nenhuma outra. O período composto tem duas ou mais — no segundo exemplo, \"lavrou\" e \"chegou\", esta última introduzida pela locução conjuntiva temporal \"assim que\". A contagem de orações segue a contagem de verbos ou locuções verbais.","fundamento":"Nomenclatura Gramatical Brasileira — período simples e composto; oração absoluta.","macete":"Um verbo, um período simples. Dois ou mais, composto.","erroComum":"Desconhecer o termo 'oração absoluta' e supor que seja erro.","comoBancaPensa":"Apresenta corretamente um par de conceitos que costuma inverter, para separar quem sabe de quem responde por padrão."}},"PT-038":{"cognitivo":{"motivo":"Cobrar que a locução verbal conta como uma única oração.","palavraCritica":"quatro orações"},"comentario":{"resolucao":"ERRADO. São duas orações, não quatro. \"Tinha analisado\" e \"havia concluído\" são locuções verbais: cada uma reúne verbo auxiliar e principal em torno de um só núcleo verbal. A regra correta é contar verbos e locuções verbais — e a locução, por mais formas que reúna, vale por uma.","fundamento":"Nomenclatura Gramatical Brasileira — locução verbal e contagem de orações.","macete":"Locução verbal é um só núcleo. Auxiliar + principal = uma oração.","erroComum":"Contar auxiliar e principal como orações distintas.","comoBancaPensa":"Multiplica a contagem apoiando-se numa regra formulada de modo quase correto ('cada forma verbal')."}},"PT-039":{"cognitivo":{"motivo":"Cobrar que a classificação do sujeito depende do número de núcleos, e não da extensão do termo.","palavraCritica":"por possuir núcleo único"},"comentario":{"resolucao":"CERTO. O que define sujeito simples ou composto é a quantidade de NÚCLEOS, não de palavras. No segundo exemplo, \"Os agentes experientes\" tem um único núcleo — \"agentes\" —, acompanhado de dois adjuntos adnominais; segue simples, por mais longo que seja. No primeiro, há dois núcleos: \"agentes\" e \"delegado\".","fundamento":"Nomenclatura Gramatical Brasileira — sujeito simples e composto.","macete":"Conte núcleos, não palavras. Sujeito longo pode ser simples.","erroComum":"Classificar como composto todo sujeito com muitas palavras.","comoBancaPensa":"Contrapõe dois exemplos para checar se o candidato aplica o critério certo."}},"PT-040":{"cognitivo":{"motivo":"Cobrar a diferença entre sujeito ausente e sujeito impossível de identificar.","palavraCritica":"indeterminado ... não figura expresso"},"comentario":{"resolucao":"ERRADO. O sujeito de \"recolheram\" é perfeitamente identificável no próprio período: são \"os peritos\". Trata-se, portanto, de sujeito OCULTO (elíptico ou desinencial), e não indeterminado. Indeterminado é aquele que existe, mas não se pode identificar nem pelo contexto nem pela desinência — como em \"Recolheram os vestígios\", isolado.","fundamento":"Nomenclatura Gramatical Brasileira — sujeito oculto e sujeito indeterminado.","macete":"Dá para dizer quem é pelo contexto? Oculto. Não dá de jeito nenhum? Indeterminado.","erroComum":"Tomar 'verbo na 3ª pessoa do plural' como sinal automático de indeterminação.","comoBancaPensa":"Isola a segunda oração do contexto que a determina, esperando que o candidato faça o mesmo."}},"PT-041":{"cognitivo":{"motivo":"Contraexemplo: o par indeterminado/oculto aplicado corretamente a dois contextos.","palavraCritica":"enunciado isoladamente"},"comentario":{"resolucao":"CERTO. A classificação depende do contexto, e o item o explicita. Sem referência anterior, \"Arrombaram\" na 3ª pessoa do plural deixa o agente irrecuperável: sujeito indeterminado. Com a referência dada — \"A guarnição\" —, o sujeito de \"arrombou\" é recuperável: oculto. O mesmo verbo muda de classificação conforme o entorno.","fundamento":"Nomenclatura Gramatical Brasileira — sujeito indeterminado e sujeito oculto.","macete":"Verbo na 3ª do plural sem dono no contexto: indeterminado. Com dono citado antes: oculto.","erroComum":"Marcar ERRADO por desconfiar de item que compara duas classificações.","comoBancaPensa":"Apresenta corretamente um par que costuma inverter, punindo quem responde pelo formato do enunciado."}},"PT-042":{"cognitivo":{"motivo":"Cobrar o SE com verbo transitivo indireto, que não admite flexão no plural.","palavraCritica":"ainda que ... esteja no plural"},"comentario":{"resolucao":"CERTO. \"Necessitar\" é transitivo indireto e \"de peritos criminais\" é objeto indireto — não sujeito. Como o SE aqui indetermina o sujeito, o verbo fica invariavelmente na 3ª pessoa do singular. Escrever \"Necessitam-se de peritos\" é erro clássico, por atrair o verbo a um termo que não é sujeito.","fundamento":"Gramática normativa — pronome indeterminador do sujeito com verbos transitivos indiretos.","macete":"Sobrou preposição depois do SE? Verbo no singular, sempre.","erroComum":"Flexionar o verbo pelo objeto indireto.","comoBancaPensa":"Item correto que exige identificar a transitividade antes de decidir a concordância."}},"PT-043":{"cognitivo":{"motivo":"Cobrar a distinção entre partícula apassivadora e índice de indeterminação, decidida pela transitividade.","palavraCritica":"voz passiva sintética ... sujeito paciente"},"comentario":{"resolucao":"ERRADO. A voz passiva sintética só se forma com verbo transitivo DIRETO. \"Precisar\", no sentido de necessitar, é transitivo indireto — e a presença da preposição \"de\" o denuncia. Logo, o SE é índice de indeterminação do sujeito, \"de novos escrivães\" é objeto indireto e o verbo fica no singular.","fundamento":"Gramática normativa — partícula apassivadora (VTD) x índice de indeterminação do sujeito (VTI).","macete":"Tem preposição? Indetermina e fica singular. Não tem? Apassiva e concorda.","erroComum":"Ver o 'se' e presumir voz passiva sintética.","comoBancaPensa":"Aplica a análise correta de uma estrutura à estrutura vizinha, que exige análise oposta."}},"PT-044":{"cognitivo":{"motivo":"Cobrar a voz passiva sintética com verbo transitivo direto e a concordância dela decorrente.","palavraCritica":"exerce a função de sujeito"},"comentario":{"resolucao":"CERTO. \"Apreender\" é transitivo direto; o SE apassiva, e a oração equivale a \"Dezenas de aparelhos celulares foram apreendidas na operação\". Como o termo é sujeito, o verbo concorda com ele. O teste é sempre esse: se a frase admite conversão para a passiva analítica, o SE é apassivador.","fundamento":"Gramática normativa — voz passiva sintética ou pronominal.","macete":"Converta para 'foi/foram + particípio'. Deu certo? É apassivadora e concorda.","erroComum":"Deixar o verbo no singular por não reconhecer o sujeito posposto.","comoBancaPensa":"Item correto que cobra a cadeia inteira: transitividade, função do SE e concordância."}},"PT-045":{"cognitivo":{"motivo":"Cobrar a concordância na voz passiva sintética, contra a generalização do singular.","palavraCritica":"invariavelmente ... singular"},"comentario":{"resolucao":"ERRADO. \"Divulgar\" é transitivo direto, de modo que o SE é apassivador e \"os resultados do concurso\" é sujeito — o verbo deve concordar: \"Divulgaram-se os resultados do concurso\". A invariabilidade no singular vale apenas quando o SE indetermina o sujeito, com verbo transitivo indireto, intransitivo ou de ligação.","fundamento":"Gramática normativa — concordância na voz passiva sintética.","macete":"VTD com 'se': concorda. VTI com 'se': fica no singular.","erroComum":"Aplicar o singular a todas as construções com 'se'.","comoBancaPensa":"Toma a regra de um caso e a estende a todos com 'invariavelmente'."}},"PT-046":{"cognitivo":{"motivo":"Contraexemplo: um 'sempre' verdadeiro, com a consequência sintática correta.","palavraCritica":"sempre ... objeto direto, e não sujeito"},"comentario":{"resolucao":"CERTO. \"Haver\" existencial não tem sujeito: a oração é sem sujeito e o verbo fica travado no singular — \"Havia denúncias\", nunca \"Haviam denúncias\". O termo que parece sujeito é objeto direto. A impessoalidade se transmite ao auxiliar em locuções: \"Pode haver denúncias\", e não \"Podem haver\".","fundamento":"Gramática normativa — impessoalidade do verbo haver no sentido existencial.","macete":"Haver de existir não tem sujeito: singular sempre, e o resto é objeto direto.","erroComum":"Marcar ERRADO por reflexo diante de 'sempre', ou flexionar o verbo pelo objeto.","comoBancaPensa":"Usa advérbio absoluto em regra que realmente não admite exceção."}},"PT-047":{"cognitivo":{"motivo":"Cobrar que apenas o haver existencial é impessoal, e não seus sinônimos.","palavraCritica":"existir, ocorrer e acontecer são impessoais"},"comentario":{"resolucao":"ERRADO. Existir, ocorrer e acontecer são verbos PESSOAIS: têm sujeito e com ele concordam. O correto é \"Ocorreram diversas irregularidades no certame\", em que \"diversas irregularidades\" é sujeito. A impessoalidade é privilégio do haver existencial — e é exatamente por isso que a banca oferece os sinônimos como armadilha.","fundamento":"Gramática normativa — haver impessoal x existir/ocorrer/acontecer pessoais.","macete":"Só o HAVER é impessoal. Trocou por existir/ocorrer/acontecer, o verbo passa a concordar.","erroComum":"Estender a impessoalidade do haver aos verbos de sentido equivalente.","comoBancaPensa":"Usa a sinonímia semântica para induzir à identidade sintática, que não existe."}},"PT-048":{"cognitivo":{"motivo":"Contraexemplo: o par haver/ocorrer analisado corretamente, com a consequência na flexão.","palavraCritica":"explica a diferença de flexão"},"comentario":{"resolucao":"CERTO. As duas frases dizem o mesmo e se analisam de modo oposto. Com \"haver\", não há sujeito e o verbo trava no singular; \"falhas\" é objeto direto. Com \"ocorrer\", há sujeito — \"falhas\" — e o verbo concorda no plural. É a demonstração de que sinonímia semântica não implica identidade sintática.","fundamento":"Gramática normativa — verbo haver impessoal e verbo ocorrer pessoal.","macete":"Houve falhas / Ocorreram falhas. Mesmo sentido, análise oposta.","erroComum":"Marcar ERRADO por desconfiar de item que contrasta duas construções.","comoBancaPensa":"Apresenta corretamente o contraste que costuma servir de armadilha, para checar compreensão real."}},"PT-049":{"cognitivo":{"motivo":"Cobrar o caso mais direto de oração sem sujeito, com a ressalva 'em regra'.","palavraCritica":"em regra"},"comentario":{"resolucao":"CERTO. Verbos de fenômeno natural não atribuem ação a ninguém: não há de quem se predicar. A ressalva \"em regra\" é o que torna o item exato, pois esses verbos deixam de ser impessoais quando empregados em sentido figurado.","fundamento":"Nomenclatura Gramatical Brasileira — orações sem sujeito.","macete":"Choveu, nevou, anoiteceu: ninguém fez. Oração sem sujeito.","erroComum":"Apontar um sujeito oculto ('ele') onde não há sujeito algum.","comoBancaPensa":"Item correto cuja ressalva 'em regra' prepara a generalização indevida do item seguinte."}},"PT-050":{"cognitivo":{"motivo":"Cobrar a perda da impessoalidade no emprego figurado.","palavraCritica":"em qualquer contexto"},"comentario":{"resolucao":"ERRADO. Em sentido figurado, esses verbos se tornam pessoais e passam a ter sujeito: em \"Choveram críticas sobre a corporação\", o sujeito é \"críticas\" — tanto que o verbo está no plural, concordando com ele. O mesmo ocorre em \"Amanheci indisposto\", com sujeito desinencial \"eu\". A impessoalidade vale para o sentido literal.","fundamento":"Gramática normativa — verbos de fenômeno natural em sentido figurado.","macete":"Choveu água: sem sujeito. Choveram críticas: sujeito é 'críticas'.","erroComum":"Aplicar a regra pelo verbo, sem olhar o sentido.","comoBancaPensa":"Converte uma regra com exceção conhecida em regra absoluta, com 'qualquer contexto'."}},"PT-051":{"cognitivo":{"motivo":"Cobrar a impessoalidade de fazer e haver em expressões temporais, item de altíssima recorrência.","palavraCritica":"e não \"Fazem cinco anos\""},"comentario":{"resolucao":"CERTO. Indicando tempo decorrido, \"fazer\" e \"haver\" não têm sujeito e ficam na 3ª pessoa do singular. A expressão de tempo é adjunto adverbial, não sujeito — daí a impossibilidade de flexionar o verbo. A impessoalidade contamina o auxiliar: \"Deve fazer cinco anos\", nunca \"Devem fazer\".","fundamento":"Gramática normativa — verbos fazer e haver impessoais na indicação de tempo.","macete":"Faz cinco anos, faz dois meses, faz séculos. Nunca 'fazem'.","erroComum":"Concordar o verbo com a expressão numérica de tempo.","comoBancaPensa":"Item 'limpo' que a banca repete em quase toda prova de nível médio."}},"PT-052":{"cognitivo":{"motivo":"Cobrar a função sintática da expressão temporal, que não é sujeito.","palavraCritica":"função de sujeito"},"comentario":{"resolucao":"ERRADO. \"Havia\", indicando tempo decorrido, é impessoal: a oração não tem sujeito e a expressão \"três meses\" é adjunto adverbial de tempo. Por isso o verbo não se flexiona — \"Haviam três meses\" contraria a norma-padrão. A posição inicial do termo é justamente o que induz a lê-lo como sujeito.","fundamento":"Gramática normativa — impessoalidade do verbo haver na indicação de tempo decorrido.","macete":"Expressão de tempo depois de faz/há é adjunto adverbial, nunca sujeito.","erroComum":"Ler como sujeito todo termo que antecede ou segue de perto o verbo.","comoBancaPensa":"Atribui função de sujeito a um adjunto adverbial, para justificar uma flexão indevida."}},"PT-053":{"cognitivo":{"motivo":"Contraexemplo: uma aparente contradição — impessoal e ainda assim flexionado — que é exatamente a regra.","palavraCritica":"impessoal, mas concorda"},"comentario":{"resolucao":"CERTO. É o caso singular em que o verbo, sem sujeito, concorda com o predicativo numérico: uma hora leva o singular; quinze horas levam o plural. O mesmo vale para datas e distâncias — \"São dois quilômetros até a delegacia\". O item parece contraditório e não é: a concordância se faz com a expressão de hora, embora não haja sujeito.","fundamento":"Gramática normativa — verbo ser na indicação de horas, datas e distâncias.","macete":"É uma hora. São duas horas. Sem sujeito, mas concordando com o número.","erroComum":"Marcar ERRADO por achar impossível verbo impessoal flexionar-se no plural.","comoBancaPensa":"Explora a aparência de contradição de uma regra que o candidato aplica sem conhecer."}},"PT-054":{"cognitivo":{"motivo":"Cobrar a classificação dos três tipos de predicado pelo critério do núcleo.","palavraCritica":"dois núcleos"},"comentario":{"resolucao":"CERTO. O critério é sempre o núcleo. Em \"O delegado indiciou o suspeito\", o núcleo é \"indiciou\": predicado verbal. Em \"O delegado está convicto\", o núcleo é \"convicto\": predicado nominal. Em \"O delegado saiu convicto\", há dois — \"saiu\" e \"convicto\": predicado verbo-nominal. Note que no verbo-nominal o verbo é transitivo ou intransitivo, nunca de ligação.","fundamento":"Nomenclatura Gramatical Brasileira — tipos de predicado.","macete":"Um núcleo verbal: verbal. Um núcleo predicativo: nominal. Dois núcleos: verbo-nominal.","erroComum":"Classificar pelo tipo de verbo, e não pelo núcleo do predicado.","comoBancaPensa":"Item 'limpo' de definição, âncora para as trocas que virão."}},"PT-055":{"cognitivo":{"motivo":"Cobrar o reconhecimento de verbo de ligação fora da lista óbvia (ser, estar).","palavraCritica":"núcleo é a forma verbal \"permaneceu\""},"comentario":{"resolucao":"ERRADO. \"Permanecer\" é verbo de ligação: não exprime ação, mas estado permanente, e liga o sujeito à característica \"atenta\". O núcleo do predicado é o predicativo \"atenta\", de modo que o predicado é NOMINAL. Integram a mesma lista ser, estar, ficar, continuar, andar, tornar-se e parecer — variáveis conforme o contexto.","fundamento":"Nomenclatura Gramatical Brasileira — predicado nominal e verbos de ligação.","macete":"Verbo que não indica ação, mas estado, é de ligação. O núcleo passa a ser o predicativo.","erroComum":"Reconhecer como verbo de ligação apenas 'ser' e 'estar'.","comoBancaPensa":"Escolhe um verbo de ligação menos evidente para que o candidato o tome por verbo de ação."}},"PT-056":{"cognitivo":{"motivo":"Contraexemplo: análise correta de uma estrutura que a banca costuma classificar como adjunto adverbial de modo.","palavraCritica":"predicativo do sujeito \"nervosa\""},"comentario":{"resolucao":"CERTO. \"Nervosa\" não modifica o verbo — atribui estado à testemunha, e por isso é predicativo do sujeito, concordando com ele em gênero e número. Como \"chegou\" mantém seu valor de ação e há também o predicativo, o predicado tem dois núcleos: verbo-nominal. O teste decisivo é a flexão: adjunto adverbial de modo seria invariável (\"chegou nervosamente\").","fundamento":"Nomenclatura Gramatical Brasileira — predicado verbo-nominal e predicativo do sujeito.","macete":"Palavra que concorda com o sujeito é predicativo. Invariável é adjunto adverbial.","erroComum":"Classificar 'nervosa' como adjunto adverbial de modo.","comoBancaPensa":"Apresenta corretamente a análise que costuma distorcer, checando se o candidato aplica o teste de flexão."}},"PT-057":{"cognitivo":{"motivo":"Cobrar o mesmo teste do item anterior, agora com a classificação errada.","palavraCritica":"adjunto adverbial de modo"},"comentario":{"resolucao":"ERRADO. \"Exaustos\" flexiona-se em gênero e número para concordar com \"Os investigadores\" — prova de que se refere ao sujeito, e não ao verbo. Trata-se de predicativo do sujeito, e o predicado é verbo-nominal. Adjunto adverbial é invariável: \"retornaram rapidamente\" não muda de forma, ainda que o sujeito seja feminino ou singular.","fundamento":"Nomenclatura Gramatical Brasileira — predicativo do sujeito x adjunto adverbial.","macete":"Varia com o sujeito? Predicativo. Não varia? Adjunto adverbial.","erroComum":"Classificar pelo sentido ('indica como') sem aplicar o teste de flexão.","comoBancaPensa":"Oferece uma justificativa semântica plausível para encobrir o critério formal correto."}},"PT-058":{"cognitivo":{"motivo":"Cobrar que a classificação verbal depende do emprego, e não de lista fixa.","palavraCritica":"conforme o contexto"},"comentario":{"resolucao":"CERTO. Não existe verbo de ligação por natureza — existe emprego como verbo de ligação. Em \"ficou apreensivo\", o verbo apenas conecta o sujeito ao estado, sem carga semântica própria: predicado nominal. Em \"ficou na viatura\", significa permanecer em um lugar, tem sentido pleno e o termo seguinte é adjunto adverbial: predicado verbal.","fundamento":"Gramática normativa — verbos de ligação e sua dependência contextual.","macete":"Ligação é função, não etiqueta fixa. Analise o emprego, não a lista.","erroComum":"Decorar a lista de verbos de ligação e aplicá-la sem análise.","comoBancaPensa":"Item correto que cobra o método, e não a memorização."}},"PT-059":{"cognitivo":{"motivo":"Cobrar a ocorrência de predicativo do sujeito também no predicado verbo-nominal.","palavraCritica":"indispensável ... verbo de ligação"},"comentario":{"resolucao":"ERRADO. O predicativo do sujeito também aparece no predicado verbo-nominal, em que o verbo é transitivo ou intransitivo — jamais de ligação. Em \"A vítima saiu ilesa do acidente\", \"ilesa\" é predicativo do sujeito e \"saiu\" é intransitivo. A presença de verbo de ligação é indispensável apenas no predicado nominal.","fundamento":"Nomenclatura Gramatical Brasileira — predicativo do sujeito nos predicados nominal e verbo-nominal.","macete":"Predicativo do sujeito cabe em dois predicados: nominal e verbo-nominal.","erroComum":"Associar predicativo exclusivamente a verbo de ligação.","comoBancaPensa":"Cria uma exigência que exclui, sem razão, metade das ocorrências do fenômeno."}},"PT-060":{"cognitivo":{"motivo":"Cobrar a variedade de classes que exercem a função de predicativo.","palavraCritica":"locução adjetiva"},"comentario":{"resolucao":"CERTO. Predicativo é função sintática, e várias classes podem preenchê-la: adjetivo (\"reincidente\"), substantivo (\"advogado\"), numeral (\"Os presos eram três\"), pronome (\"Justiça é isso\") e locução adjetiva (\"está sem defensor\"). Confundir classe gramatical com função sintática é o erro que o item cobra.","fundamento":"Nomenclatura Gramatical Brasileira — predicativo e classes que o representam.","macete":"Predicativo é função. Quem a preenche pode ser de várias classes.","erroComum":"Exigir que o predicativo seja necessariamente adjetivo.","comoBancaPensa":"Item correto que separa o plano morfológico do sintático."}},"PT-061":{"cognitivo":{"motivo":"Cobrar a mesma matéria pela restrição indevida da classe.","palavraCritica":"somente ... adjetivos"},"comentario":{"resolucao":"ERRADO. Substantivos exercem a função com frequência — em \"Meu pai foi delegado\", \"delegado\" é predicativo do sujeito e é substantivo. Também numerais, pronomes e locuções adjetivas a exercem. A restrição confunde a classe gramatical mais comum com a única possível.","fundamento":"Nomenclatura Gramatical Brasileira — classes que exercem a função de predicativo.","macete":"Substantivo também predica: 'Ele é escrivão' tem predicativo substantivo.","erroComum":"Igualar 'atribuir característica' a 'ser adjetivo'.","comoBancaPensa":"Restringe a função a uma só classe, com justificativa que parece razoável."}},"PT-062":{"cognitivo":{"motivo":"Cobrar o predicativo do objeto com verbo de valor avaliativo.","palavraCritica":"atribuindo ao objeto ... juízo de valor"},"comentario":{"resolucao":"CERTO. Verbos como considerar, julgar, achar, nomear, eleger e declarar são avaliadores: o termo que os acompanha atribui característica ao objeto, não ao sujeito. \"Improcedente\" concorda com \"a representação\" — o objeto —, e não com \"O conselho\". O predicado é verbo-nominal, com núcleos \"considerou\" e \"improcedente\".","fundamento":"Nomenclatura Gramatical Brasileira — predicativo do objeto direto.","macete":"Considerar, julgar, achar, nomear: o que vem depois qualifica o objeto.","erroComum":"Ler o predicativo do objeto como predicativo do sujeito.","comoBancaPensa":"Item correto que exige identificar a quem a característica se refere."}},"PT-063":{"cognitivo":{"motivo":"Cobrar a mesma estrutura com a atribuição invertida.","palavraCritica":"predicativo do sujeito"},"comentario":{"resolucao":"ERRADO. \"Inidôneo\" qualifica \"o fornecedor\", que é o objeto direto — não \"A comissão\". Trata-se de predicativo do objeto direto. A concordância confirma: o adjetivo está no masculino singular, acompanhando \"fornecedor\", e não o feminino \"comissão\". Quem julga não é inidôneo; quem foi julgado é.","fundamento":"Nomenclatura Gramatical Brasileira — predicativo do objeto direto.","macete":"Veja com quem o adjetivo concorda. É ele que aponta a quem se refere.","erroComum":"Presumir que todo predicativo se refere ao sujeito.","comoBancaPensa":"Inverte o alvo do predicativo, com justificativa que soa lógica se ignorada a concordância."}},"PT-064":{"cognitivo":{"motivo":"Contraexemplo: uma restrição de aparência arbitrária que a NGB efetivamente adota.","palavraCritica":"apenas com o verbo chamar"},"comentario":{"resolucao":"CERTO. A restrição é real. O verbo \"chamar\", no sentido de denominar, admite dupla regência: \"Chamaram o réu de inocente\" (objeto direto e predicativo do objeto direto) e \"Chamaram ao réu de inocente\" (objeto indireto e predicativo do objeto indireto). É o único caso reconhecido pela NGB para essa função — daí o \"apenas\", que não é exagero de banca.","fundamento":"Nomenclatura Gramatical Brasileira — predicativo do objeto indireto e a dupla regência de chamar.","macete":"Predicativo do objeto indireto: só com 'chamar' no sentido de denominar.","erroComum":"Marcar ERRADO por reflexo diante de 'apenas', ou desconhecer a dupla regência de chamar.","comoBancaPensa":"Veste de armadilha uma exclusividade que a nomenclatura oficial de fato consagra."}},"PT-065":{"cognitivo":{"motivo":"Cobrar o critério de distinção entre as duas transitividades.","palavraCritica":"sem preposição obrigatória"},"comentario":{"resolucao":"CERTO. Em \"O delegado indiciou o suspeito\", \"indiciar\" é transitivo direto e \"o suspeito\" é objeto direto, sem preposição. Em \"O delegado discordou do laudo\", \"discordar\" é transitivo indireto e exige a preposição \"de\". Note a formulação precisa: \"sem preposição OBRIGATÓRIA\" — porque o objeto direto pode vir preposicionado em casos específicos, sem que a preposição seja exigida pelo verbo.","fundamento":"Nomenclatura Gramatical Brasileira — predicação verbal.","macete":"Pergunte 'o quê/quem' (direto) ou 'de quê/a quem' (indireto).","erroComum":"Deduzir a transitividade pelo sentido, sem testar a pergunta.","comoBancaPensa":"Item correto cuja precisão ('obrigatória') prepara o item sobre objeto direto preposicionado."}},"PT-066":{"cognitivo":{"motivo":"Cobrar as duas transitividades pela inversão do critério.","palavraCritica":"transitivo direto ... regido de preposição"},"comentario":{"resolucao":"ERRADO. Está invertido: quem exige preposição é o transitivo INDIRETO; quem dispensa é o DIRETO. O nome ajuda a fixar — o complemento chega direto ao verbo, sem intermediário, ou chega indiretamente, pela preposição.","fundamento":"Nomenclatura Gramatical Brasileira — predicação verbal.","macete":"Direto = sem ponte. Indireto = pela ponte da preposição.","erroComum":"Trocar os dois por não associar o nome ao critério.","comoBancaPensa":"Permuta os critérios de duas classificações elementares, contando com a leitura automática."}},"PT-067":{"cognitivo":{"motivo":"Contraexemplo: duas transitividades distintas corretamente identificadas, uma delas com regência que a banca explora.","palavraCritica":"assistiu ao interrogatório"},"comentario":{"resolucao":"CERTO. \"Entregar\" pede dois complementos — entrega-se algo (objeto direto) a alguém (objeto indireto): transitivo direto e indireto. \"Assistir\", no sentido de presenciar, é transitivo indireto e rege a preposição \"a\" — daí \"assistiu AO interrogatório\". No sentido de prestar assistência, seria transitivo direto: \"O médico assistiu o ferido\".","fundamento":"Nomenclatura Gramatical Brasileira e regência do verbo assistir.","macete":"Assistir a algo = ver. Assistir alguém = socorrer. A preposição muda o sentido.","erroComum":"Marcar ERRADO por desconfiar de item que classifica dois verbos de uma vez.","comoBancaPensa":"Apresenta corretamente duas análises, uma delas envolvendo regência que costuma ser cobrada pelo erro."}},"PT-068":{"cognitivo":{"motivo":"Cobrar o objeto direto preposicionado, em que a preposição não decorre da regência.","palavraCritica":"transforma o termo ... em objeto indireto"},"comentario":{"resolucao":"ERRADO. \"Respeitar\" é transitivo direto — respeita-se alguém, não a alguém. A preposição aqui é facultativa, de valor expressivo, e o termo continua sendo OBJETO DIRETO PREPOSICIONADO. A transitividade é propriedade do verbo: não muda porque se acrescentou uma preposição não exigida por ele.","fundamento":"Gramática normativa — objeto direto preposicionado.","macete":"Preposição que o verbo não pede não cria objeto indireto.","erroComum":"Tomar toda preposição como sinal de objeto indireto.","comoBancaPensa":"Usa a presença da preposição como se fosse critério suficiente, ignorando a regência do verbo."}},"PT-069":{"cognitivo":{"motivo":"Contraexemplo: uma enumeração restritiva que corresponde ao que a gramática prevê.","palavraCritica":"hipóteses restritas"},"comentario":{"resolucao":"CERTO. As três hipóteses citadas são as tradicionalmente arroladas. Em \"O réu ofendeu a mim\", a preposição é exigida pelo pronome oblíquo tônico, não pelo verbo — que é transitivo direto. Em \"Bebeu do vinho\", a preposição marca o sentido partitivo: bebeu parte dele, não todo. Somam-se ainda casos de ênfase e de clareza na ordem inversa.","fundamento":"Gramática normativa — hipóteses de objeto direto preposicionado.","macete":"Preposição vinda do pronome, do partitivo ou de 'Deus': objeto direto preposicionado.","erroComum":"Marcar ERRADO por achar que a enumeração restringe demais.","comoBancaPensa":"Apresenta uma lista fechada que o candidato desconfia estar incompleta, mas que corresponde à doutrina."}},"PT-070":{"cognitivo":{"motivo":"Cobrar que a posição não determina a função, e que só há objeto indireto se o verbo o exigir.","palavraCritica":"Toda expressão preposicionada"},"comentario":{"resolucao":"ERRADO. \"Permanecer\", no sentido de ficar em um lugar, não exige complemento: \"na viatura\" é adjunto adverbial de lugar. Só há objeto indireto quando o verbo é transitivo indireto e a preposição decorre da regência. Expressões preposicionadas após o verbo podem ser adjunto adverbial, complemento nominal ou agente da passiva.","fundamento":"Nomenclatura Gramatical Brasileira — objeto indireto x adjunto adverbial.","macete":"O verbo pede? É complemento. Só informa circunstância? É adjunto adverbial.","erroComum":"Classificar pela forma (tem preposição) em vez de pela exigência do verbo.","comoBancaPensa":"Generaliza um critério formal, ignorando que a função depende da regência."}},"PT-071":{"cognitivo":{"motivo":"Cobrar a redundância sintática deliberada, recurso de ênfase.","palavraCritica":"retomar ... o termo deslocado"},"comentario":{"resolucao":"CERTO. O objeto pleonástico repete, por meio de pronome oblíquo átono, um complemento já antecipado na oração. \"O inquérito\" foi deslocado para o início e é retomado por \"o\" junto ao verbo. A redundância é intencional e legítima, não vício de linguagem. Existe também o objeto indireto pleonástico: \"A ele, nada lhe disseram\".","fundamento":"Gramática normativa — objeto direto e indireto pleonásticos.","macete":"Termo antecipado e retomado por pronome junto ao verbo: pleonástico.","erroComum":"Tomar a repetição por erro de redação.","comoBancaPensa":"Cobra uma nomenclatura pouco frequente, testando profundidade de estudo."}},"PT-072":{"cognitivo":{"motivo":"Cobrar uma nomenclatura de menor frequência, que costuma diferenciar candidatos.","palavraCritica":"repete o radical ou a ideia expressa pelo próprio verbo"},"comentario":{"resolucao":"CERTO. O objeto cognato dá complemento a um verbo normalmente intransitivo, retomando sua própria significação — \"viver uma vida\", \"sonhar um sonho\", \"chorar lágrimas amargas\". Costuma vir acompanhado de modificador, que é o que justifica a construção: sem o adjetivo, a frase seria mera redundância.","fundamento":"Gramática normativa — objeto direto cognato ou interno.","macete":"Verbo e objeto da mesma família: objeto cognato.","erroComum":"Tratar a construção como pleonasmo vicioso.","comoBancaPensa":"Cobra termo técnico raro, para separar quem estudou a nomenclatura completa."}},"PT-073":{"cognitivo":{"motivo":"Cobrar a diferença entre complemento (exigido) e adjunto (acessório).","palavraCritica":"não admite ... qualquer termo"},"comentario":{"resolucao":"ERRADO. O verbo intransitivo dispensa COMPLEMENTO, mas admite adjuntos adverbiais à vontade. Em \"A guarnição chegou rapidamente ao local\", \"chegar\" continua intransitivo: \"rapidamente\" é adjunto adverbial de modo e \"ao local\" é adjunto adverbial de lugar. Nenhum dos dois completa o sentido do verbo — apenas o circunstanciam.","fundamento":"Nomenclatura Gramatical Brasileira — verbos intransitivos e adjuntos adverbiais.","macete":"Intransitivo não pede complemento, mas aceita circunstância à vontade.","erroComum":"Concluir a transitividade pela mera presença de termos após o verbo.","comoBancaPensa":"Confunde ausência de complemento com ausência de qualquer termo posposto."}},"PT-074":{"cognitivo":{"motivo":"Cobrar a identificação da função de um complemento longo e não preposicionado.","palavraCritica":"objeto indireto"},"comentario":{"resolucao":"ERRADO. \"Ouvir\" é transitivo direto: ouve-se alguma coisa, sem preposição. O termo é OBJETO DIRETO, cujo núcleo é \"depoimentos\". A preposição que aparece dentro do sintagma — em \"das testemunhas\" — liga-se ao substantivo \"depoimentos\", não ao verbo: ali há adjunto adnominal, e não regência verbal.","fundamento":"Nomenclatura Gramatical Brasileira — objeto direto e adjunto adnominal.","macete":"Preposição interna ao termo não torna o complemento indireto. Olhe o que o verbo pede.","erroComum":"Ver preposição em qualquer ponto do sintagma e concluir objeto indireto.","comoBancaPensa":"Alonga o complemento e insere preposição interna, para embaralhar a leitura da regência."}},"PT-075":{"cognitivo":{"motivo":"Cobrar as duas definições, base da distinção mais cobrada da sintaxe.","palavraCritica":"substantivo abstrato, adjetivo ou advérbio"},"comentario":{"resolucao":"CERTO. O adjunto adnominal caracteriza ou determina um substantivo e pode vir com ou sem preposição. O complemento nominal é sempre preposicionado e integra o sentido de um nome incompleto — que pode ser substantivo abstrato, adjetivo ou advérbio. Essa última possibilidade é a menos lembrada: em \"Agiu favoravelmente ao acordo\", \"ao acordo\" completa o advérbio.","fundamento":"Nomenclatura Gramatical Brasileira — adjunto adnominal e complemento nominal.","macete":"Adjunto adnominal só se liga a substantivo. Complemento nominal também completa adjetivo e advérbio.","erroComum":"Ignorar que adjetivo e advérbio admitem complemento nominal.","comoBancaPensa":"Item 'limpo' que estabelece o critério antes das aplicações mais difíceis."}},"PT-076":{"cognitivo":{"motivo":"Cobrar as três classes que admitem complemento nominal.","palavraCritica":"somente a substantivos"},"comentario":{"resolucao":"ERRADO. Adjetivos e advérbios admitem complemento nominal com frequência. Em \"O servidor é leal à instituição\", \"à instituição\" completa o adjetivo \"leal\". Em \"Agiu lealmente à instituição\", completa o advérbio \"lealmente\". Aliás, é justamente esse o critério mais seguro: expressão preposicionada ligada a adjetivo ou advérbio é sempre complemento nominal, sem chance de ser adjunto adnominal.","fundamento":"Nomenclatura Gramatical Brasileira — complemento nominal de substantivo, adjetivo e advérbio.","macete":"Ligado a adjetivo ou advérbio? Complemento nominal, sem dúvida.","erroComum":"Restringir o complemento nominal ao complemento de substantivo.","comoBancaPensa":"Suprime duas das três classes possíveis, deixando só a mais lembrada."}},"PT-077":{"cognitivo":{"motivo":"Contraexemplo: dois absolutos ('nunca', 'sempre') em uma regra que efetivamente não admite exceção.","palavraCritica":"nunca ... sempre"},"comentario":{"resolucao":"CERTO. Substantivo concreto designa ser de existência independente e não precisa de complemento — não há sentido a completar. Assim, em \"a arma do crime\" ou \"o carro do suspeito\", as expressões preposicionadas são adjuntos adnominais. A dúvida entre as duas funções só se instala diante de substantivo ABSTRATO, e é aí que se aplicam os testes de agente e paciente.","fundamento":"Gramática normativa — complemento nominal e substantivos abstratos.","macete":"Substantivo concreto não tem complemento nominal. Só abstrato gera dúvida.","erroComum":"Marcar ERRADO por reflexo diante de 'nunca' e 'sempre'.","comoBancaPensa":"Emprega dois absolutos em regra categórica, punindo quem responde por vocabulário."}},"PT-078":{"cognitivo":{"motivo":"Cobrar a aplicação do critério do substantivo concreto.","palavraCritica":"completar o sentido do substantivo"},"comentario":{"resolucao":"ERRADO. \"Revólver\" é substantivo concreto e tem sentido completo por si — nada há a completar. \"Do acusado\" apenas o especifica, indicando posse: é adjunto adnominal. O item usa o verbo \"completar\" como se bastasse enunciá-lo para que a função existisse.","fundamento":"Gramática normativa — adjunto adnominal ligado a substantivo concreto.","macete":"Ideia de posse junto a substantivo concreto: adjunto adnominal.","erroComum":"Classificar como complemento nominal toda expressão iniciada por 'de'.","comoBancaPensa":"Afirma a função e a justifica com a própria definição, sem testar se o substantivo a comporta."}},"PT-079":{"cognitivo":{"motivo":"Contraexemplo: o critério agente/paciente aplicado corretamente aos dois lados.","palavraCritica":"quem sofre ... quem pratica"},"comentario":{"resolucao":"CERTO. Diante de substantivo abstrato, o teste decisivo é o papel semântico. O foragido não prendeu — foi preso: é paciente, logo complemento nominal. O magistrado não foi decidido — ele decidiu: é agente, logo adjunto adnominal. Note que a mesma preposição \"de\" aparece nos dois, o que mostra que a forma não resolve a questão.","fundamento":"Gramática normativa — critério de agente e paciente na distinção entre adjunto adnominal e complemento nominal.","macete":"Praticou a ação? Adjunto adnominal. Sofreu a ação? Complemento nominal.","erroComum":"Marcar ERRADO por desconfiar de item que classifica duas expressões de modo oposto.","comoBancaPensa":"Aplica corretamente o critério que costuma inverter, checando compreensão do papel semântico."}},"PT-080":{"cognitivo":{"motivo":"Cobrar o mesmo critério com os papéis semânticos invertidos.","palavraCritica":"complemento nominal designa sempre o agente"},"comentario":{"resolucao":"ERRADO. A premissa está invertida: o complemento nominal designa o PACIENTE, e o adjunto adnominal, o agente. Os peritos não convocaram — foram convocados; \"dos peritos\" é, portanto, complemento nominal. Quem convocou é a chefia, e o próprio item entrega isso ao mencioná-la.","fundamento":"Gramática normativa — complemento nominal como paciente e adjunto adnominal como agente.","macete":"Complemento nominal é sempre o alvo da ação, nunca quem a pratica.","erroComum":"Trocar os papéis e classificar o paciente como adjunto adnominal.","comoBancaPensa":"Enuncia uma regra invertida e a aplica coerentemente, o que dá aparência de consistência ao erro."}},"PT-081":{"cognitivo":{"motivo":"Contraexemplo: um absoluto verdadeiro, que fornece o atalho mais seguro da matéria.","palavraCritica":"Qualquer ... sempre"},"comentario":{"resolucao":"CERTO. A regra é categórica e vale como atalho: adjunto adnominal só modifica SUBSTANTIVO. Logo, se o termo preposicionado se liga a um adjetivo, a única função possível é complemento nominal. O mesmo raciocínio se aplica aos advérbios. É o único ponto da matéria em que não é preciso testar agente e paciente.","fundamento":"Nomenclatura Gramatical Brasileira — complemento nominal de adjetivos e advérbios.","macete":"Ligou-se a adjetivo ou advérbio? Complemento nominal, sem análise adicional.","erroComum":"Marcar ERRADO diante de 'qualquer' e 'sempre', sem notar que a regra é mesmo fechada.","comoBancaPensa":"Reúne dois absolutos em regra sem exceção, para punir a resposta por vocabulário."}},"PT-082":{"cognitivo":{"motivo":"Cobrar que o adjunto adnominal pode ou não vir preposicionado.","palavraCritica":"jamais admite preposição"},"comentario":{"resolucao":"ERRADO. O adjunto adnominal admite preposição sem dificuldade: em \"casa de madeira\", \"homem de coragem\" e \"delegacia da capital\", todas as expressões preposicionadas são adjuntos adnominais. É precisamente por ambos poderem ser preposicionados que a distinção entre adjunto adnominal e complemento nominal exige análise, e não simples inspeção da forma.","fundamento":"Nomenclatura Gramatical Brasileira — adjunto adnominal preposicionado.","macete":"Preposição não decide nada. Se decidisse, não haveria a dificuldade clássica da matéria.","erroComum":"Adotar a presença de preposição como critério suficiente.","comoBancaPensa":"Oferece um critério formal simples para uma distinção que é semântica."}},"PT-083":{"cognitivo":{"motivo":"Cobrar a definição e o alcance do adjunto adverbial.","palavraCritica":"ou a oração inteira"},"comentario":{"resolucao":"CERTO. A invariabilidade é o traço formal que o distingue do predicativo. Quanto ao alcance, o adjunto adverbial modifica verbo (\"agiu prudentemente\"), adjetivo (\"muito prudente\"), outro advérbio (\"bem prudentemente\") e até a oração toda (\"Infelizmente, o prazo venceu\"), caso em que se costuma chamá-lo de modalizador.","fundamento":"Nomenclatura Gramatical Brasileira — adjunto adverbial.","macete":"Invariável e circunstancial. Se varia, não é adjunto adverbial.","erroComum":"Restringir o adjunto adverbial à modificação do verbo.","comoBancaPensa":"Item 'limpo' que fixa o critério formal usado nas comparações seguintes."}},"PT-084":{"cognitivo":{"motivo":"Cobrar a identificação do termo modificado, que decide entre as duas funções.","palavraCritica":"acrescentar informação ao substantivo"},"comentario":{"resolucao":"ERRADO. \"Com lupa\" não caracteriza o veículo — não se trata de um veículo com lupa. A expressão indica o instrumento com que se examinou: liga-se ao verbo e é adjunto adverbial de instrumento. O teste é deslocar o termo: \"Com lupa, a perícia examinou o veículo\" continua coerente, o que confirma o vínculo com o verbo, não com o substantivo.","fundamento":"Nomenclatura Gramatical Brasileira — adjunto adverbial de instrumento.","macete":"Dá para deslocar sem quebrar o sentido? Liga-se ao verbo: adjunto adverbial.","erroComum":"Classificar pela proximidade com o substantivo, e não pelo sentido.","comoBancaPensa":"Explora a posição do termo, contando com a análise por vizinhança em vez de por função."}},"PT-085":{"cognitivo":{"motivo":"Contraexemplo: duas circunstâncias distintas corretamente identificadas no mesmo verbo.","palavraCritica":"causa ... modo"},"comentario":{"resolucao":"CERTO. O medo é o motivo que levou à confissão — circunstância de causa, verificável pela pergunta \"por que confessou?\". A ausência de hesitação descreve como a confissão se deu — circunstância de modo, verificável por \"de que maneira confessou?\". O mesmo verbo admite as duas, e a preposição isolada não define a circunstância: o contexto define.","fundamento":"Nomenclatura Gramatical Brasileira — circunstâncias do adjunto adverbial.","macete":"Por que aconteceu? Causa. Como aconteceu? Modo.","erroComum":"Marcar ERRADO por desconfiar de item que classifica duas expressões de uma vez.","comoBancaPensa":"Apresenta corretamente duas circunstâncias vizinhas, checando o uso das perguntas-teste."}},"PT-086":{"cognitivo":{"motivo":"Cobrar a distinção entre causa e modo em construção que admite as duas leituras à primeira vista.","palavraCritica":"maneira como ocorreu"},"comentario":{"resolucao":"ERRADO. A exaustão é o motivo do desmaio, não a maneira dele: trata-se de adjunto adverbial de CAUSA. A pergunta-teste resolve — \"Por que desmaiou?\", \"De exaustão\". Modo responderia a \"como desmaiou?\", e a resposta seria algo como \"subitamente\". A preposição \"de\" introduz várias circunstâncias, o que exige análise do sentido.","fundamento":"Nomenclatura Gramatical Brasileira — adjunto adverbial de causa.","macete":"Causa responde 'por quê'. Modo responde 'de que maneira'.","erroComum":"Classificar como modo toda expressão que descreve o estado em que a ação ocorreu.","comoBancaPensa":"Oferece uma paráfrase enganosa ('a maneira como') para induzir à circunstância errada."}},"PT-087":{"cognitivo":{"motivo":"Cobrar o adjunto adverbial de escopo oracional, cobrado em interpretação e em sintaxe.","palavraCritica":"revelando a avaliação de quem o profere"},"comentario":{"resolucao":"CERTO. Não se afirma que o arquivamento se deu de modo lamentável, mas que o enunciador lamenta o fato. Por isso o termo é chamado modalizador: exprime a atitude do falante diante do que enuncia. O mesmo ocorre com \"felizmente\", \"sinceramente\" e \"evidentemente\" — todos sinalizam subjetividade, o que torna o recurso relevante também em interpretação.","fundamento":"Gramática normativa e linguística textual — adjuntos adverbiais modalizadores.","macete":"Vírgula, começo de frase e opinião do falante: modalizador.","erroComum":"Ler o advérbio como circunstância de modo do verbo.","comoBancaPensa":"Cobra a diferença entre modificar o verbo e modalizar o enunciado inteiro."}},"PT-088":{"cognitivo":{"motivo":"Cobrar que o sufixo não determina a circunstância expressa.","palavraCritica":"invariavelmente ... de modo"},"comentario":{"resolucao":"ERRADO. Os três exemplos do próprio item desmentem a regra: \"provavelmente\" exprime dúvida, \"extremamente\" exprime intensidade e \"diariamente\" exprime tempo. O sufixo -mente forma advérbios de várias circunstâncias; a classificação depende do sentido no contexto, jamais da terminação.","fundamento":"Gramática normativa — classificação semântica dos advérbios.","macete":"Sufixo -mente não é sinônimo de modo. Classifique pelo sentido.","erroComum":"Associar automaticamente a terminação -mente à circunstância de modo.","comoBancaPensa":"Enuncia uma regra falsa e a ilustra com exemplos que a contradizem, apostando que não serão testados."}},"PT-089":{"cognitivo":{"motivo":"Cobrar que a classe gramatical se define no uso, e não isoladamente.","palavraCritica":"conforme o emprego"},"comentario":{"resolucao":"CERTO. No primeiro caso, \"policial\" nomeia um ser e é núcleo do sujeito: substantivo. No segundo, caracteriza \"inquérito\": adjetivo. O fenômeno chama-se derivação imprópria e é largamente cobrado — vale igualmente para \"jovem\", \"brasileiro\" e para adjetivos substantivados, como em \"Os feridos foram socorridos\".","fundamento":"Gramática normativa — derivação imprópria e mudança de classe gramatical.","macete":"Palavra solta não tem classe definida. Classe se decide na frase.","erroComum":"Decorar a classe de cada palavra em vez de analisar o emprego.","comoBancaPensa":"Item correto que cobra método de análise, e não memorização de listas."}},"PT-090":{"cognitivo":{"motivo":"Cobrar a diferença entre classe gramatical e função sintática, e entre artigo e pronome.","palavraCritica":"artigo definido, por determinar o substantivo"},"comentario":{"resolucao":"ERRADO. \"Nosso\" é pronome possessivo — os artigos definidos são apenas o, a, os, as. O item se apoia em uma verdade parcial: a palavra de fato determina o substantivo, e por isso exerce a função sintática de adjunto adnominal. Mas determinar não é ser artigo: classe gramatical é morfologia; adjunto adnominal é sintaxe.","fundamento":"Gramática normativa — classes de palavras e função de adjunto adnominal.","macete":"Artigo definido é só o, a, os, as. O resto que determina é pronome ou numeral.","erroComum":"Confundir a função (adjunto adnominal) com a classe (pronome possessivo).","comoBancaPensa":"Usa uma justificativa sintática verdadeira para sustentar uma classificação morfológica falsa."}},"PT-091":{"cognitivo":{"motivo":"Contraexemplo: dois fenômenos que a banca permuta, aqui definidos corretamente.","palavraCritica":"sem sofrer perda de fonema"},"comentario":{"resolucao":"CERTO. Em \"a + o = ao\", nada se perde: a preposição e o artigo permanecem íntegros — é combinação. Em \"de + o = do\", perde-se o \"e\"; em \"em + esta = nesta\" e \"a + aquele = àquele\", há alteração — são contrações. O critério é exclusivamente fonético, e a lista de combinações é curtíssima: ao, aos, aonde.","fundamento":"Gramática normativa — combinação e contração de preposições.","macete":"Perdeu letra ou som? Contração. Só juntou? Combinação. 'Ao' é o exemplo clássico.","erroComum":"Marcar ERRADO por desconfiar de item que define dois fenômenos de uma vez.","comoBancaPensa":"Define corretamente o par que costuma inverter, checando o domínio do critério fonético."}},"PT-092":{"cognitivo":{"motivo":"Cobrar a aplicação do critério fonético a um caso concreto.","palavraCritica":"se mantêm integralmente"},"comentario":{"resolucao":"ERRADO. \"Pelos\" é contração: a antiga preposição \"per\" perde o \"r\" ao unir-se ao artigo. Só há combinação quando nada se altera, o que ocorre em \"ao\", \"aos\" e \"aonde\". Havendo qualquer supressão ou modificação de som, o fenômeno é contração — como em do, no, dele, nesta, àquela.","fundamento":"Gramática normativa — contração de preposições.","macete":"Se sumiu alguma letra na junção, é contração. 'Pelos' perdeu o r.","erroComum":"Classificar como combinação toda união de preposição com artigo.","comoBancaPensa":"Afirma a integridade das formas justamente no caso em que houve perda fonética."}},"PT-093":{"cognitivo":{"motivo":"Cobrar a locução adjetiva e sua função sintática.","palavraCritica":"exerce ... a função de adjunto adnominal"},"comentario":{"resolucao":"CERTO. A locução adjetiva é formada por preposição mais substantivo e comporta-se como adjetivo, caracterizando um nome — daí exercer a função de adjunto adnominal. Outros exemplos: \"de mãe\" (materno), \"de crime\" (criminal), \"de juiz\" (judicial). Nem toda locução adjetiva tem adjetivo correspondente, mas a função permanece.","fundamento":"Gramática normativa — locução adjetiva e adjunto adnominal.","macete":"Preposição + substantivo com valor de adjetivo: locução adjetiva, função de adjunto adnominal.","erroComum":"Classificar a locução adjetiva como complemento nominal, por vir preposicionada.","comoBancaPensa":"Item correto que articula morfologia e sintaxe no mesmo enunciado."}},"PT-094":{"cognitivo":{"motivo":"Cobrar a separação entre os planos morfológico e sintático, que atravessa toda a matéria.","palavraCritica":"a mesma realidade linguística"},"comentario":{"resolucao":"ERRADO. Não são a mesma coisa, e os rótulos ainda estão invertidos: \"adjetivo\" é classe gramatical, matéria da MORFOLOGIA; \"adjunto adnominal\" é função, matéria da SINTAXE. Além disso, não há correspondência de um para um: um artigo, um numeral ou um pronome possessivo também exercem a função de adjunto adnominal sem serem adjetivos.","fundamento":"Gramática normativa — distinção entre classe gramatical e função sintática.","macete":"Classe é o que a palavra é. Função é o que ela faz na frase.","erroComum":"Tratar classe e função como sinônimos.","comoBancaPensa":"Funde os dois planos de análise e ainda inverte a qual disciplina cada termo pertence."}},"PT-095":{"cognitivo":{"motivo":"Contraexemplo: o par perfeito/imperfeito, que a banca permuta, aqui atribuído corretamente.","palavraCritica":"sem delimitação de término"},"comentario":{"resolucao":"CERTO. O pretérito perfeito marca o fato como concluído e pontual; o imperfeito o apresenta em desenvolvimento, como pano de fundo. É justamente por isso que a narrativa costuma alternar os dois: o imperfeito descreve a cena, o perfeito faz a ação avançar. A conjunção \"enquanto isso\" reforça a simultaneidade entre o fato acabado e o processo em curso.","fundamento":"Gramática normativa — aspecto verbal do pretérito perfeito e do imperfeito.","macete":"Perfeito fecha a ação. Imperfeito deixa ela correndo.","erroComum":"Tratar os dois como equivalentes por ambos indicarem passado.","comoBancaPensa":"Apresenta corretamente o par que costuma inverter, punindo a resposta por formato."}},"PT-096":{"cognitivo":{"motivo":"Cobrar o reconhecimento do mais-que-perfeito simples, forma que a banca confunde com o futuro do pretérito.","palavraCritica":"futuro do pretérito"},"comentario":{"resolucao":"ERRADO. \"Deixara\" é pretérito mais-que-perfeito SIMPLES do indicativo: exprime ação anterior a outra já passada — o suspeito saiu antes de a perícia chegar. O futuro do pretérito seria \"deixaria\". A confusão nasce da semelhança das terminações, mas o sentido é oposto: um marca anterioridade no passado, o outro, hipótese.","fundamento":"Gramática normativa — pretérito mais-que-perfeito simples e futuro do pretérito.","macete":"-ARA é passado do passado. -ARIA é hipótese.","erroComum":"Ler \"deixara\" como forma reduzida de \"deixaria\".","comoBancaPensa":"Troca dois tempos de terminação parecida e sentidos incompatíveis."}},"PT-097":{"cognitivo":{"motivo":"Cobrar a equivalência entre as formas simples e composta do mais-que-perfeito.","palavraCritica":"sem prejuízo do sentido"},"comentario":{"resolucao":"CERTO. O mais-que-perfeito composto forma-se com \"ter\" ou \"haver\" no imperfeito mais o particípio. Equivale à forma simples: \"havia solicitado\" = \"solicitara\". A forma composta predomina na língua falada e a simples soa mais formal, mas ambas exprimem o mesmo — ação anterior a outro fato passado.","fundamento":"Gramática normativa — formas simples e composta do mais-que-perfeito.","macete":"Havia feito = fizera. Mesmo tempo, registros diferentes.","erroComum":"Supor que a forma composta indica tempo diverso da simples.","comoBancaPensa":"Item correto que cobra a equivalência, e não apenas o reconhecimento."}},"PT-098":{"cognitivo":{"motivo":"Cobrar o valor durativo do pretérito perfeito composto, que se prolonga até o presente.","palavraCritica":"uma única vez ... inteiramente concluído"},"comentario":{"resolucao":"ERRADO. O pretérito perfeito COMPOSTO exprime justamente o contrário: ação ou processo que se repete ou se prolonga do passado até o presente, e que pode continuar. \"Têm caído\" indica queda continuada, não fato único e encerrado. Quem exprime fato único e concluído é o pretérito perfeito simples — \"caíram\".","fundamento":"Gramática normativa — aspecto do pretérito perfeito composto.","macete":"Tenho feito = venho fazendo, e continua. Fiz = acabou.","erroComum":"Igualar o perfeito composto ao perfeito simples por ambos serem 'perfeitos'.","comoBancaPensa":"Atribui ao composto o valor do simples, aproveitando a semelhança do nome."}},"PT-099":{"cognitivo":{"motivo":"Cobrar o valor modal do subjuntivo em oração concessiva.","palavraCritica":"possibilidade admitida"},"comentario":{"resolucao":"CERTO. O subjuntivo é o modo da incerteza, da hipótese e da concessão. A locução \"ainda que\" é concessiva e exige subjuntivo: o enunciador admite o fato sem afirmá-lo como certo. Se estivesse no indicativo — \"indicam\" —, o fato seria apresentado como real e a construção exigiria outro conectivo.","fundamento":"Gramática normativa — modo subjuntivo em orações concessivas.","macete":"Ainda que, embora, conquanto: puxam subjuntivo.","erroComum":"Confundir o subjuntivo com tempo verbal, e não com modo.","comoBancaPensa":"Item correto que liga modo verbal ao conectivo que o exige."}},"PT-100":{"cognitivo":{"motivo":"Contraexemplo: identificação correta do futuro do pretérito, tempo que a banca troca pelo mais-que-perfeito.","palavraCritica":"hipótese não verificada"},"comentario":{"resolucao":"CERTO. O período condicional típico combina imperfeito do subjuntivo na hipótese (\"houvesse\") com futuro do pretérito na consequência (\"sairiam\"). O futuro do pretérito exprime o que aconteceria caso a condição se realizasse — e o fato de ela não se realizar é o que caracteriza a hipótese. É também o tempo do desejo cortês e da notícia não confirmada.","fundamento":"Gramática normativa — futuro do pretérito e correlação em período condicional.","macete":"SE + imperfeito do subjuntivo, então futuro do pretérito. Houvesse/sairiam.","erroComum":"Marcar ERRADO por desconfiar da nomenclatura 'futuro do pretérito'.","comoBancaPensa":"Nomeia corretamente o tempo que costuma confundir com o mais-que-perfeito."}},"PT-101":{"cognitivo":{"motivo":"Cobrar que há mais de uma correlação condicional válida.","palavraCritica":"obrigatoriamente"},"comentario":{"resolucao":"ERRADO. A construção está correta. Há duas correlações condicionais consagradas: futuro do subjuntivo com futuro do presente — \"se cumprir, seguirá\", que expressa condição realizável; e imperfeito do subjuntivo com futuro do pretérito — \"se cumprisse, seguiria\", que expressa hipótese improvável ou irreal. O item elege uma como única e reprova a outra.","fundamento":"Gramática normativa — correlação de tempos em período condicional.","macete":"Cumprir/seguirá = possível. Cumprisse/seguiria = hipotético.","erroComum":"Supor que toda condicional é hipotética e pede imperfeito.","comoBancaPensa":"Transforma uma das correlações possíveis em exigência única."}},"PT-102":{"cognitivo":{"motivo":"Contraexemplo: análise correta do SE apassivador, com o teste de conversão.","palavraCritica":"possibilidade de conversão"},"comentario":{"resolucao":"CERTO. \"Analisar\" é transitivo direto, logo o SE é partícula apassivadora e o termo seguinte é sujeito — por isso o verbo concorda no plural. O teste decisivo é o do item: se a frase admite conversão para a passiva analítica com \"ser + particípio\", é voz passiva sintética. Se não admitisse, o SE seria índice de indeterminação do sujeito.","fundamento":"Gramática normativa — voz passiva sintética e teste de conversão.","macete":"Converteu para 'foi/foram + particípio'? É passiva sintética, e o verbo concorda.","erroComum":"Marcar ERRADO por desconfiar de item que já traz a análise pronta.","comoBancaPensa":"Apresenta corretamente a análise que costuma distorcer, com o teste explícito."}},"PT-103":{"cognitivo":{"motivo":"Cobrar a função de agente da passiva, distinta da de sujeito.","palavraCritica":"função de sujeito"},"comentario":{"resolucao":"ERRADO. \"Pelo diretor\" é AGENTE DA PASSIVA — quem pratica a ação, mas não é o sujeito. O sujeito é \"O relatório\", que sofre a ação e com quem o verbo concorda. Na voz passiva, quem pratica e quem é sujeito se separam: é exatamente essa dissociação que a define. Na conversão para a ativa, o agente da passiva vira sujeito: \"O diretor assinou o relatório\".","fundamento":"Gramática normativa — agente da passiva e sujeito paciente.","macete":"Na passiva, o sujeito sofre. Quem faz é o agente da passiva.","erroComum":"Igualar 'quem pratica a ação' a 'sujeito'.","comoBancaPensa":"Usa a noção intuitiva de sujeito como agente, que a voz passiva desmente."}},"PT-104":{"cognitivo":{"motivo":"Cobrar a formação do imperativo, que a banca cobra pela derivação.","palavraCritica":"sem o -s final"},"comentario":{"resolucao":"CERTO. É a regra de formação: \"tu cantas\" gera \"canta tu\" (afirmativo, sem o -s); e o negativo vem do subjuntivo — \"não cantes tu\". As demais pessoas do imperativo, afirmativo e negativo, vêm todas do presente do subjuntivo. Daí a assimetria que gera erro corrente: \"faça\" e \"não faça\", mas \"faz tu\" e \"não faças tu\".","fundamento":"Gramática normativa — formação do modo imperativo.","macete":"Afirmativo de tu/vós: tira o -s do indicativo. Todo o resto vem do subjuntivo.","erroComum":"Misturar as formas de tratamento e produzir 'não faz' em vez de 'não faças'.","comoBancaPensa":"Item correto sobre uma formação que quase ninguém revisa."}},"PT-105":{"cognitivo":{"motivo":"Contraexemplo: rol fechado e categórico que corresponde à gramática.","palavraCritica":"apenas três"},"comentario":{"resolucao":"CERTO. São exatamente essas três, chamadas nominais porque podem exercer funções próprias de nomes: o infinitivo aproxima-se do substantivo, o gerúndio e o particípio, do advérbio e do adjetivo. Não indicam tempo por si sós, o que as distingue das formas finitas. O rol é fechado — não há quarta forma nominal.","fundamento":"Nomenclatura Gramatical Brasileira — formas nominais do verbo.","macete":"Infinitivo, gerúndio e particípio. Só essas três.","erroComum":"Marcar ERRADO por reflexo diante de 'apenas'.","comoBancaPensa":"Numeral fechado em rol que é mesmo taxativo."}},"PT-106":{"cognitivo":{"motivo":"Cobrar os valores secundários do presente, que a restrição nega.","palavraCritica":"somente ... incorreto"},"comentario":{"resolucao":"ERRADO. O presente tem vários empregos além do momentâneo: futuro próximo (\"a prova acontece em novembro\"), verdade permanente ou atemporal (\"a água ferve a 100 °C\"), fato habitual (\"o plantão começa às sete\") e presente histórico, que narra o passado com vivacidade (\"em 1988, promulga-se a Constituição\"). Todos são legítimos na norma-padrão.","fundamento":"Gramática normativa — valores do presente do indicativo.","macete":"O presente serve para agora, sempre, de hábito, para o futuro próximo e para narrar o passado.","erroComum":"Restringir cada tempo verbal a um único valor semântico.","comoBancaPensa":"Reduz um tempo de múltiplos empregos ao seu valor mais óbvio."}},"PT-107":{"cognitivo":{"motivo":"Contraexemplo: classificação e substituição corretas de conectivo, no formato em que a banca troca a relação.","palavraCritica":"sem alteração do sentido"},"comentario":{"resolucao":"CERTO. \"No entanto\", \"contudo\", \"todavia\", \"entretanto\", \"porém\" e \"mas\" formam o grupo das adversativas: todas marcam oposição ou contraste. A substituição entre elas é livre quanto ao sentido — muda só o registro e a pontuação, já que \"mas\" costuma vir sem ponto e vírgula antes.","fundamento":"Gramática normativa — conjunções coordenativas adversativas.","macete":"Mas, porém, contudo, todavia, entretanto, no entanto: todas opõem.","erroComum":"Marcar ERRADO por desconfiar de item que autoriza substituição.","comoBancaPensa":"Classifica corretamente um conectivo cuja relação costuma distorcer."}},"PT-108":{"cognitivo":{"motivo":"Cobrar a diferença entre conclusão e oposição, com dois conectivos de forma parecida.","palavraCritica":"preservaria a relação lógica"},"comentario":{"resolucao":"ERRADO. \"Portanto\" é CONCLUSIVO: a segunda oração decorre da primeira. \"Entretanto\" é ADVERSATIVO: a segunda contraria a expectativa da primeira. As relações são opostas, e a troca inverteria o sentido do período. A semelhança sonora entre os dois é justamente o que a banca explora.","fundamento":"Gramática normativa — conjunções conclusivas e adversativas.","macete":"PorTANTO conclui. EnTREtanto opõe. Sons parecidos, sentidos contrários.","erroComum":"Trocar os dois por semelhança fonética.","comoBancaPensa":"Propõe substituição entre conectivos parecidos na forma e opostos na função."}},"PT-109":{"cognitivo":{"motivo":"Cobrar o valor da concessão, frequentemente confundido com o da condição.","palavraCritica":"não impede"},"comentario":{"resolucao":"CERTO. A concessão admite um obstáculo e afirma que ele não impede o fato principal — é a lógica do \"apesar de\". Integram o grupo embora, ainda que, conquanto, se bem que, posto que e mesmo que, todas exigindo subjuntivo. Não confundir com a condicional, que subordina a realização do principal ao cumprimento da condição.","fundamento":"Gramática normativa — orações subordinadas adverbiais concessivas.","macete":"Concessiva é obstáculo que não impede. Condicional é requisito que precisa acontecer.","erroComum":"Confundir concessiva com condicional.","comoBancaPensa":"Item correto que define a relação antes de cobrá-la nas trocas."}},"PT-110":{"cognitivo":{"motivo":"Cobrar a distinção entre concessão e condição na aplicação.","palavraCritica":"relação de condição ... dependia"},"comentario":{"resolucao":"ERRADO. \"Embora\" é concessiva: a expiração do prazo era obstáculo esperado ao conhecimento do recurso, e ainda assim ele foi conhecido. Não há dependência — há contraste com a expectativa. A relação de condição seria expressa por \"se\", \"caso\", \"contanto que\", e implicaria que um fato só ocorre se o outro ocorrer.","fundamento":"Gramática normativa — orações concessivas e condicionais.","macete":"Embora = apesar de. Se = só acontece caso.","erroComum":"Ler qualquer subordinada adverbial como condicional.","comoBancaPensa":"Atribui a uma concessiva a lógica de dependência própria da condicional."}},"PT-111":{"cognitivo":{"motivo":"Cobrar o duplo valor de 'pois', decidido pela posição.","palavraCritica":"posposta ao verbo"},"comentario":{"resolucao":"CERTO. A posição decide: \"Estude, pois a prova se aproxima\" é explicativo — a segunda oração justifica a primeira. \"A prova se aproxima; estude, pois\" é conclusivo — equivale a portanto. É um dos poucos casos em que a mesma palavra muda de classificação pela colocação na frase.","fundamento":"Gramática normativa — valores da conjunção 'pois'.","macete":"Pois antes do verbo explica; pois depois do verbo conclui.","erroComum":"Classificar 'pois' sempre como explicativo.","comoBancaPensa":"Item correto sobre um conectivo de comportamento duplo, pouco revisado."}},"PT-112":{"cognitivo":{"motivo":"Contraexemplo: classificação correta de conectivo que a banca costuma rotular como comparativo.","palavraCritica":"acordo entre o que se declara e uma norma"},"comentario":{"resolucao":"CERTO. A conformativa exprime conformidade com um padrão — regimento, lei, previsão. Integram o grupo conforme, segundo, consoante e como (neste sentido). A confusão frequente é com a comparativa, porque \"como\" serve às duas: em \"agiu como manda a lei\" há conformidade; em \"agiu como um profissional\" há comparação.","fundamento":"Gramática normativa — orações subordinadas adverbiais conformativas.","macete":"Conforme, segundo, consoante: de acordo com. É conformativa.","erroComum":"Classificar toda ocorrência de 'como' como comparativa.","comoBancaPensa":"Nomeia corretamente uma relação de menor frequência, que o candidato tende a rejeitar."}},"PT-113":{"cognitivo":{"motivo":"Cobrar a relação de proporcionalidade, que a banca reduz a tempo.","palavraCritica":"apenas a simultaneidade"},"comentario":{"resolucao":"ERRADO. \"À medida que\" é locução conjuntiva PROPORCIONAL: os fatos não apenas coincidem no tempo, mas variam juntos — quanto mais laudos chegavam, mais as diligências avançavam. Há simultaneidade, é verdade, mas o traço definidor é a proporção. Cuidado com a forma \"à medida que\": \"na medida em que\" tem valor causal, e a troca entre as duas é erro corrente.","fundamento":"Gramática normativa — orações subordinadas adverbiais proporcionais.","macete":"À medida que = proporção. Na medida em que = causa.","erroComum":"Reduzir a proporcional a temporal por haver simultaneidade.","comoBancaPensa":"Oferece a relação parcialmente presente ('tempo') e nega a definidora, com 'apenas'."}},"PT-114":{"cognitivo":{"motivo":"Cobrar a consecutiva e o intensificador que a anuncia.","palavraCritica":"intensidade"},"comentario":{"resolucao":"CERTO. A consecutiva exprime consequência de uma intensidade, e vem anunciada por um intensificador na principal — tanto, tal, tão, tamanho. Sem ele, a oração com \"que\" seria de outra natureza. A diferença para a causal é a direção: a causal dá o motivo (\"precisou de reforço porque o volume era grande\"), a consecutiva dá o efeito.","fundamento":"Gramática normativa — orações subordinadas adverbiais consecutivas.","macete":"Tão/tanto/tal/tamanho + que: consecutiva.","erroComum":"Confundir consecutiva com causal por ambas ligarem causa e efeito.","comoBancaPensa":"Item correto que exige localizar o intensificador na principal."}},"PT-115":{"cognitivo":{"motivo":"Contraexemplo: rol de cinco que corresponde à classificação tradicional.","palavraCritica":"cinco categorias"},"comentario":{"resolucao":"CERTO. São essas cinco na classificação tradicional. Aditivas somam (e, nem, mas também); adversativas opõem (mas, porém); alternativas excluem ou alternam (ou, ora... ora); conclusivas concluem (logo, portanto); explicativas justificam (pois, porque, que). Não há sexta categoria de coordenativa — condicionais, concessivas e causais são subordinativas.","fundamento":"Nomenclatura Gramatical Brasileira — conjunções coordenativas.","macete":"Coordenativas: somam, opõem, alternam, concluem, explicam. Cinco.","erroComum":"Incluir condicionais ou concessivas entre as coordenativas.","comoBancaPensa":"Rol fechado que o candidato tende a considerar incompleto."}},"PT-116":{"cognitivo":{"motivo":"Cobrar o valor adversativo que o 'e' assume em certos contextos.","palavraCritica":"exclusivamente ... nenhum contexto"},"comentario":{"resolucao":"ERRADO. O \"e\" assume valor adversativo quando liga ideias contrastantes: \"Estudou muito e não passou\" equivale a \"mas não passou\". O contexto, e não a conjunção isoladamente, determina a relação — princípio que vale para vários conectivos. É recorte clássico em prova de interpretação, porque exige ler o sentido, não a etiqueta.","fundamento":"Gramática normativa — valores contextuais das conjunções coordenativas.","macete":"'Estudou e não passou' = 'estudou MAS não passou'. O 'e' pode opor.","erroComum":"Classificar conectivos apenas pela lista, sem checar o sentido.","comoBancaPensa":"Fixa em um único valor um conectivo cujo sentido depende do contexto."}},"PT-117":{"cognitivo":{"motivo":"Cobrar a distinção restritiva/explicativa, que decide a pontuação e o sentido.","palavraCritica":"explicativa ... vírgulas"},"comentario":{"resolucao":"ERRADO. A oração é RESTRITIVA: delimita quais servidores receberão o certificado — apenas os que concluíram o curso. Restritiva não admite vírgula. Se fosse explicativa, com vírgulas, o sentido mudaria por completo: todos os servidores teriam concluído o curso e todos receberiam o certificado. A vírgula, aqui, não é detalhe de estilo — altera quem tem direito.","fundamento":"Gramática normativa — orações subordinadas adjetivas restritivas e explicativas.","macete":"Sem vírgula restringe (só alguns). Com vírgula explica (todos).","erroComum":"Tratar a vírgula na adjetiva como opcional.","comoBancaPensa":"Inverte a classificação para justificar uma pontuação que mudaria o sentido do enunciado."}},"PT-118":{"cognitivo":{"motivo":"Cobrar a obrigatoriedade do par de vírgulas na explicativa intercalada.","palavraCritica":"as duas vírgulas"},"comentario":{"resolucao":"CERTO. A explicativa acrescenta informação sobre um ser já determinado — há um só laudo pericial em questão, e a oração apenas informa quando foi concluído. Sendo intercalada, exige as DUAS vírgulas: usar só uma é erro de pontuação frequente e grave, porque separa indevidamente termos que se ligam.","fundamento":"Gramática normativa — pontuação da oração adjetiva explicativa.","macete":"Intercalou? Abre e fecha vírgula. Nunca só uma.","erroComum":"Esquecer a vírgula de fechamento da intercalada.","comoBancaPensa":"Item correto que cobra o par de vírgulas, e não apenas a classificação."}},"PT-119":{"cognitivo":{"motivo":"Cobrar a identificação da subordinada substantiva subjetiva.","palavraCritica":"objeto direto"},"comentario":{"resolucao":"ERRADO. A oração é SUBJETIVA — exerce a função de sujeito. O teste é substituir por \"isso\": \"Isso é necessário\", em que \"isso\" é claramente sujeito. A principal, aqui, é oração sem sujeito próprio: \"é necessário\" é predicado nominal cujo sujeito é a oração inteira. Objeto direto exigiria verbo transitivo direto, que não há.","fundamento":"Gramática normativa — orações subordinadas substantivas subjetivas.","macete":"Troque por ISSO. Se virar sujeito, a oração é subjetiva.","erroComum":"Classificar toda substantiva iniciada por 'que' como objetiva direta.","comoBancaPensa":"Atribui a função mais comum das substantivas a um caso que é de sujeito."}},"PT-120":{"cognitivo":{"motivo":"Contraexemplo: rol de seis, taxativo, que o candidato tende a achar incompleto.","palavraCritica":"seis classificações"},"comentario":{"resolucao":"CERTO. São essas seis, e a lógica é direta: cada uma corresponde a uma função que um substantivo exerceria na oração simples — sujeito, objeto direto, objeto indireto, complemento nominal, predicativo e aposto. Quem domina os termos da oração simples classifica as substantivas sem decorar lista.","fundamento":"Nomenclatura Gramatical Brasileira — orações subordinadas substantivas.","macete":"As substantivas repetem as funções do substantivo. Seis funções, seis orações.","erroComum":"Esquecer a apositiva ou a predicativa, as menos frequentes.","comoBancaPensa":"Rol fechado cuja extensão gera desconfiança."}},"PT-121":{"cognitivo":{"motivo":"Cobrar o conceito de oração reduzida e sua conversão em desenvolvida.","palavraCritica":"sem conectivo"},"comentario":{"resolucao":"CERTO. Reduzida é a que traz o verbo em infinitivo, gerúndio ou particípio e dispensa conjunção. Classifica-se pelo sentido, convertendo-a mentalmente em desenvolvida: aqui, \"Concluída a perícia\" equivale a \"Depois que a perícia foi concluída\", logo é reduzida de particípio com valor temporal. A ausência de conectivo é o que obriga o candidato a recuperar a relação pelo contexto.","fundamento":"Gramática normativa — orações reduzidas de infinitivo, gerúndio e particípio.","macete":"Sem conjunção e com forma nominal? Reduzida. Desenvolva para classificar.","erroComum":"Não reconhecer subordinação quando falta o conectivo.","comoBancaPensa":"Item correto que ensina o procedimento de conversão."}},"PT-122":{"cognitivo":{"motivo":"Contraexemplo: o critério que distingue os dois 'que', apresentado corretamente.","palavraCritica":"sem retomar termo algum"},"comentario":{"resolucao":"CERTO. É o critério decisivo. Em \"o laudo QUE chegou\", o \"que\" retoma \"laudo\" e pode ser substituído por \"o qual\" — é relativo, e a oração é adjetiva. Em \"Afirmo QUE o laudo chegou\", o \"que\" não retoma nada e não admite \"o qual\" — é conjunção integrante, e a oração é substantiva. O teste da substituição por \"o qual\" resolve praticamente todos os casos.","fundamento":"Gramática normativa — pronome relativo e conjunção integrante.","macete":"Cabe 'o qual'? Relativo, adjetiva. Não cabe? Integrante, substantiva.","erroComum":"Classificar a oração pelo conectivo, sem testar se há antecedente.","comoBancaPensa":"Apresenta corretamente a distinção que sustenta metade da análise do período composto."}},"PT-123":{"cognitivo":{"motivo":"Contraexemplo: nomenclatura correta, num par (sindética/assindética) que a banca troca.","palavraCritica":"sem conjunção"},"comentario":{"resolucao":"CERTO. Assindética vem de \"a-\" (sem) mais \"síndeto\" (conjunção): orações coordenadas justapostas, separadas apenas por vírgula. As sindéticas, ao contrário, vêm com conjunção e recebem a classificação dela — aditiva, adversativa, alternativa, conclusiva ou explicativa. A etimologia resolve a memorização.","fundamento":"Gramática normativa — orações coordenadas sindéticas e assindéticas.","macete":"A- de ausência: assindética é sem conjunção.","erroComum":"Trocar os dois termos por não decompor a palavra.","comoBancaPensa":"Nomeia corretamente o membro do par que costuma inverter."}},"PT-124":{"cognitivo":{"motivo":"Cobrar que a posição não define a oração principal.","palavraCritica":"sempre ... nunca"},"comentario":{"resolucao":"ERRADO. A principal define-se pela função — é a que tem a subordinada como termo dependente —, não pela posição. Em \"Quando o prazo terminar, o processo será arquivado\", a principal é a segunda. E ela pode vir interrompida: em \"O servidor que assinou o termo compareceu\", a subordinada adjetiva está encravada no meio da principal.","fundamento":"Gramática normativa — período composto por subordinação.","macete":"Principal não é a primeira: é a que manda. Pode até vir partida ao meio.","erroComum":"Identificar a principal pela ordem em que aparece.","comoBancaPensa":"Converte uma tendência de ordem em regra fixa, com dois absolutos."}},"PT-125":{"cognitivo":{"motivo":"Contraexemplo: regra categórica de crase que não comporta exceção.","palavraCritica":"não antecede formas verbais"},"comentario":{"resolucao":"CERTO. A crase é a fusão da preposição \"a\" com o artigo \"a\". Como o artigo não acompanha verbo, não há o que fundir: escreve-se \"começou a ganhar corpo\", \"disposto a colaborar\". A regra é absoluta e serve de atalho seguro — vendo verbo depois do \"a\", descarte o acento sem hesitar.","fundamento":"Gramática normativa — casos em que não ocorre crase.","macete":"Depois de 'a' veio verbo? Sem acento, sempre.","erroComum":"Marcar ERRADO por reflexo diante da negativa categórica.","comoBancaPensa":"Regra sem exceção enunciada de forma absoluta, o que gera desconfiança indevida."}},"PT-126":{"cognitivo":{"motivo":"Cobrar os dois elementos que produzem a crase: regência e artigo.","palavraCritica":"fusão"},"comentario":{"resolucao":"CERTO. A crase exige os dois componentes. \"Submeter-se\" rege a preposição \"a\"; \"regras\" admite o artigo \"as\". A + as = às. Faltando qualquer um dos dois, não há acento — é por isso que a análise de crase começa sempre pela regência do termo anterior, e não pela palavra que vem depois do \"a\".","fundamento":"Gramática normativa — formação da crase.","macete":"Crase = preposição exigida + artigo aceito. Faltou um, não tem acento.","erroComum":"Marcar ERRADO por desconfiar de item que explica a própria regra.","comoBancaPensa":"Descreve corretamente o mecanismo, num tema em que o candidato espera pegadinha."}},"PT-127":{"cognitivo":{"motivo":"Cobrar que a crase pressupõe termo feminino, ainda que haja preposição.","palavraCritica":"exige-se o emprego do acento grave"},"comentario":{"resolucao":"ERRADO. Há preposição, sim, mas \"setor\" é masculino: a fusão que ocorre é com o artigo masculino, resultando em \"ao setor\" — combinação, não crase. O acento grave marca a fusão de \"a\" preposição com \"a\" artigo feminino. Diante de palavra masculina, o correto é \"ao\", sem acento grave. A exceção conhecida é \"à moda de\" subentendido.","fundamento":"Gramática normativa — crase e gênero do termo regido.","macete":"Masculino leva AO. Crase é coisa de palavra feminina.","erroComum":"Concluir pela crase só porque o verbo exige preposição.","comoBancaPensa":"Apresenta metade do requisito (a preposição) como se bastasse."}},"PT-128":{"cognitivo":{"motivo":"Cobrar os três casos de crase facultativa, rol fechado e muito cobrado.","palavraCritica":"facultativo"},"comentario":{"resolucao":"CERTO. São exatamente esses três. A facultatividade decorre de o artigo ser opcional nesses contextos: pode-se dizer \"Refiro-me a Maria\" ou \"à Maria\"; \"Entreguei a minha chefe\" ou \"à minha chefe\"; \"Foi até a porta\" ou \"até à porta\". Sendo facultativo, nenhuma das formas pode ser apontada como erro — e é aí que a banca arma o item.","fundamento":"Gramática normativa — casos de crase facultativa.","macete":"Nome de mulher, possessivo feminino e 'até': tanto faz.","erroComum":"Apontar como erro o que a norma admite nas duas formas.","comoBancaPensa":"Item de rol fechado cuja armadilha correlata é declarar obrigatório o que é facultativo."}},"PT-129":{"cognitivo":{"motivo":"Cobrar a crase nas locuções, que independe de regência.","palavraCritica":"ainda que não haja termo regente"},"comentario":{"resolucao":"CERTO. É regra própria: nas locuções femininas o acento é obrigatório por convenção, inclusive para desfazer ambiguidade com o masculino correspondente — compare \"à noite\" (locução) com \"a noite\" (sujeito). Vale para às claras, às escondidas, à vontade, à risca, à direita. Note que \"à noite\" leva acento mesmo sem verbo que exija preposição.","fundamento":"Gramática normativa — crase em locuções adverbiais femininas.","macete":"Locução feminina leva acento por convenção, não por regência.","erroComum":"Procurar o verbo regente e concluir que não há crase.","comoBancaPensa":"Item correto sobre a regra que foge ao mecanismo geral da crase."}},"PT-130":{"cognitivo":{"motivo":"Cobrar que a maioria dos pronomes rejeita o artigo e, portanto, a crase.","palavraCritica":"qualquer pronome feminino"},"comentario":{"resolucao":"ERRADO. Pronomes pessoais e demonstrativos não admitem artigo, logo não há crase: \"a ela\", \"a esta\", \"a essa\". Há exceções pontuais — \"àquela\", \"àquele\", \"àquilo\", em que o \"a\" preposição se funde com a vogal inicial do demonstrativo; e os pronomes possessivos, de crase facultativa. Generalizar para \"qualquer pronome\" é o erro.","fundamento":"Gramática normativa — crase diante de pronomes.","macete":"A ela, a esta, a essa: sem acento. Àquela e àquilo: com.","erroComum":"Acentuar diante de pronome pessoal por ser feminino.","comoBancaPensa":"Estende a 'qualquer pronome' uma regra que vale só para alguns."}},"PT-131":{"cognitivo":{"motivo":"Cobrar a distinção entre tempo futuro e tempo passado no emprego da crase.","palavraCritica":"expressão de tempo feminina"},"comentario":{"resolucao":"ERRADO. O critério não é o gênero, e sim a direção temporal. Indicando tempo FUTURO, não há crase: \"daqui a duas semanas\", \"daqui a pouco\". Indicando tempo PASSADO, usa-se \"há\": \"há duas semanas\". O acento grave em expressões temporais aparece em outros contextos, como \"às 14 horas\" e \"à noite\", que são locuções.","fundamento":"Gramática normativa — 'a' e 'há' em expressões de tempo.","macete":"Futuro é 'a'. Passado é 'há'. Daqui a pouco / há muito tempo.","erroComum":"Acentuar por ser expressão feminina, sem checar a direção temporal.","comoBancaPensa":"Oferece critério irrelevante (o gênero) para decidir um caso que se resolve pelo tempo."}},"PT-132":{"cognitivo":{"motivo":"Cobrar a principal palavra atrativa — a conjunção subordinativa.","palavraCritica":"atrai"},"comentario":{"resolucao":"CERTO. Conjunção subordinativa é palavra atrativa e obriga a próclise: \"quando se instaurou\", nunca \"quando instaurou-se\". Somam-se às atrativas as palavras negativas, os advérbios sem pausa, os pronomes relativos, indefinidos e interrogativos, e as orações exclamativas e optativas.","fundamento":"Gramática normativa — colocação pronominal e palavras atrativas.","macete":"Oração subordinada puxa o pronome para antes do verbo.","erroComum":"Usar ênclise depois de conjunção subordinativa.","comoBancaPensa":"Item de regra fixa, muito cobrado em reescritura de trechos."}},"PT-133":{"cognitivo":{"motivo":"Cobrar a vedação da próclise em início de período na norma-padrão.","palavraCritica":"desde que o verbo esteja no presente"},"comentario":{"resolucao":"ERRADO. A norma-padrão não admite pronome oblíquo átono iniciando período: o correto é \"Parece-me que o prazo expirou\". A condição inventada — presente do indicativo — não existe em regra alguma. A construção com próclise inicial é corrente na fala e aceita na variedade coloquial, mas reprovada na escrita formal.","fundamento":"Gramática normativa — vedação da próclise em início de período.","macete":"Não comece frase com me, te, se, lhe, o, a.","erroComum":"Transpor para a escrita formal um uso corrente na fala.","comoBancaPensa":"Cria uma condição de exceção para tornar aceitável o que a norma rejeita."}},"PT-134":{"cognitivo":{"motivo":"Cobrar as duas condições da mesóclise: o tempo verbal e a ausência de atrativo.","palavraCritica":"desde que não haja palavra atrativa"},"comentario":{"resolucao":"CERTO. \"Far-se-á a perícia\" e \"far-se-ia a perícia\" exemplificam os dois tempos. Mas havendo palavra atrativa, a próclise prevalece: \"não se fará a perícia\", jamais \"não far-se-á\". A mesóclise é o único caso em que o pronome se encaixa no meio da forma verbal, entre o radical e a desinência.","fundamento":"Gramática normativa — mesóclise.","macete":"Futuro sem atrativo: mesóclise. Com atrativo: próclise vence.","erroComum":"Usar mesóclise mesmo diante de palavra negativa.","comoBancaPensa":"Item correto que cobra a ressalva, e não apenas a regra geral."}},"PT-135":{"cognitivo":{"motivo":"Contraexemplo: colocação correta com palavra atrativa negativa.","palavraCritica":"exerce atração"},"comentario":{"resolucao":"CERTO. Palavras de sentido negativo — não, nada, ninguém, nunca, jamais, nenhum — atraem o pronome. \"Nada se apurou\" está correto; \"Nada apurou-se\" contraria a norma. Vale notar que a atração cessa se houver pausa entre a palavra negativa e o verbo.","fundamento":"Gramática normativa — palavras atrativas de sentido negativo.","macete":"Negativa perto do verbo puxa o pronome para antes.","erroComum":"Marcar ERRADO por desconfiar de item que valida a construção.","comoBancaPensa":"Confirma uma colocação correta, num tema em que o candidato espera achar erro."}},"PT-136":{"cognitivo":{"motivo":"Cobrar que a posposição do sujeito não altera a concordância.","palavraCritica":"ainda que este venha posposto"},"comentario":{"resolucao":"CERTO. A ordem inversa não dispensa a concordância: o verbo continua a concordar com o sujeito, esteja ele antes ou depois. \"Chegaram os documentos\" está correto; \"Chegou os documentos\" não. O erro é frequente porque a proximidade de um termo singular antes do verbo induz à concordância errada.","fundamento":"Gramática normativa — concordância verbal com sujeito posposto.","macete":"Ache o sujeito, não o que está mais perto do verbo.","erroComum":"Concordar com o termo imediatamente anterior ao verbo.","comoBancaPensa":"Valida uma construção correta em ordem inversa, que soa estranha ao ouvido."}},"PT-137":{"cognitivo":{"motivo":"Cobrar a facultatividade da concordância com expressões partitivas.","palavraCritica":"obrigatoriamente ... incorreta"},"comentario":{"resolucao":"ERRADO. A concordância é FACULTATIVA: \"A maioria dos servidores compareceu\" e \"A maioria dos servidores compareceram\" são ambas corretas. No primeiro caso concorda-se com o núcleo partitivo; no segundo, com o especificador plural, por concordância atrativa ou ideológica. O mesmo vale para grande parte de, metade de, uma porção de.","fundamento":"Gramática normativa — concordância com expressões partitivas.","macete":"A maioria compareceu / compareceram: as duas valem.","erroComum":"Reprovar como erro a forma que a norma admite.","comoBancaPensa":"Transforma uma facultatividade em obrigação e condena a alternativa válida."}},"PT-138":{"cognitivo":{"motivo":"Cobrar a transmissão da impessoalidade ao auxiliar da locução.","palavraCritica":"auxiliar concorda"},"comentario":{"resolucao":"ERRADO. \"Haver\" existencial é impessoal e não tem sujeito; \"outras providências\" é objeto direto, não sujeito. A impessoalidade transmite-se ao auxiliar, de modo que o correto é \"DEVE haver outras providências\". Trata-se de erro muito frequente justamente por soar natural na fala.","fundamento":"Gramática normativa — impessoalidade do verbo haver em locuções verbais.","macete":"Deve haver, pode haver, vai haver. Sempre no singular.","erroComum":"Flexionar o auxiliar pelo termo que parece sujeito.","comoBancaPensa":"Explora a construção que a fala consagrou e a norma reprova."}},"PT-139":{"cognitivo":{"motivo":"Cobrar a concordância dessas palavras, de uso corrente em redação oficial.","palavraCritica":"concordar em gênero e número"},"comentario":{"resolucao":"CERTO. São adjetivos e variam: \"documento anexo\", \"certidões anexas\", \"cópia inclusa\". \"Obrigado\" segue a mesma lógica — uma mulher diz \"obrigada\". A forma invariável \"em anexo\" é locução adverbial e não varia, mas é a exceção, e não a regra. Item de aplicação direta em ofícios e memorandos.","fundamento":"Gramática normativa — concordância nominal de 'anexo', 'incluso' e 'obrigado'.","macete":"Anexo é adjetivo: varia. 'Em anexo' é locução: não varia.","erroComum":"Deixar 'anexo' invariável por analogia com 'em anexo'.","comoBancaPensa":"Item correto com aplicação imediata na rotina administrativa."}},"PT-140":{"cognitivo":{"motivo":"Cobrar a regra e detectar a incoerência entre o enunciado e o exemplo.","palavraCritica":"É proibida entrada"},"comentario":{"resolucao":"ERRADO. A regra enunciada está certa — sem determinante, o predicativo fica invariável —, mas o EXEMPLO a contraria: deveria ser \"É PROIBIDO entrada de pessoas não autorizadas\". Com artigo, haveria concordância: \"É proibida A entrada\". O item se autodesmente, e detectar isso é o que ele cobra.","fundamento":"Gramática normativa — concordância nominal em 'é proibido', 'é necessário', 'é bom'.","macete":"Sem artigo, invariável: é proibido entrada. Com artigo, concorda: é proibida a entrada.","erroComum":"Validar o item pela regra correta, sem conferir o exemplo.","comoBancaPensa":"Enuncia a regra corretamente e a ilustra com exemplo que a viola."}},"PT-141":{"cognitivo":{"motivo":"Cobrar a direção da relação hiperônimo/hipônimo.","palavraCritica":"hipônimo ... mais restrita"},"comentario":{"resolucao":"ERRADO. Está invertido nas duas pontas. \"Crime\" é HIPERÔNIMO — termo de sentido mais amplo, que engloba \"furto\". \"Furto\" é o hipônimo, de sentido mais específico. O prefixo entrega: hiper- é o que está acima, hipo- é o que está abaixo, como em hipertensão e hipotensão.","fundamento":"Semântica — relações de hiperonímia e hiponímia.","macete":"Hiper é maior e engloba. Hipo é menor e está contido.","erroComum":"Trocar os dois termos por não associar os prefixos.","comoBancaPensa":"Inverte a relação e ainda descreve erradamente a amplitude, dobrando o erro."}},"PT-142":{"cognitivo":{"motivo":"Cobrar o caráter contextual da sinonímia, princípio das questões de substituição.","palavraCritica":"qualquer contexto ... absoluta"},"comentario":{"resolucao":"ERRADO. A sinonímia perfeita praticamente não existe: os sinônimos diferem em registro, conotação, colocação e regência. \"Casa\" e \"lar\" são sinônimos, mas não se diz \"lar comercial\". Em prova, é exatamente aí que a banca opera — propõe substituição por sinônimo dicionarizado que, no contexto, altera o sentido, quebra a regência ou muda o registro.","fundamento":"Semântica — sinonímia e adequação contextual.","macete":"Sinônimo é aproximação, não igualdade. Sempre teste no contexto.","erroComum":"Aceitar substituição por confiar no dicionário, sem reler a frase.","comoBancaPensa":"Afirma como absoluta uma relação que é sempre contextual."}},"PT-143":{"cognitivo":{"motivo":"Contraexemplo: identificação correta da conotação, par que a banca inverte.","palavraCritica":"conotativo"},"comentario":{"resolucao":"CERTO. Conotação é o emprego figurado, em que a palavra se afasta do sentido literal. \"Abrir as portas\" significa aqui criar oportunidades, não movimentar uma porta. Denotação seria o sentido literal e dicionarizado. A distinção é cobrada em interpretação e também em itens de reescritura, porque a paráfrase precisa preservar o sentido figurado.","fundamento":"Semântica — denotação e conotação.","macete":"Denotação é o sentido do dicionário. Conotação é o figurado.","erroComum":"Trocar os dois termos por semelhança sonora.","comoBancaPensa":"Classifica corretamente um emprego figurado, num par que costuma permutar."}},"PT-144":{"cognitivo":{"motivo":"Cobrar a ambiguidade por possessivo de terceira pessoa e sua correção.","palavraCritica":"conforme o referente pretendido"},"comentario":{"resolucao":"CERTO. \"Seu\" pode remeter ao delegado ou ao escrivão, e nada no período resolve. O possessivo de terceira pessoa é ambíguo por natureza quando há dois referentes possíveis do mesmo gênero e número. A correção passa por explicitar: \"o prazo dele\", \"o próprio prazo\" ou reescrever nomeando o referente. É defeito de clareza, não erro gramatical — a frase está bem formada.","fundamento":"Semântica e redação oficial — ambiguidade por pronome possessivo.","macete":"Dois candidatos a dono e um 'seu' no meio: ambiguidade.","erroComum":"Não reconhecer ambiguidade em frase gramaticalmente correta.","comoBancaPensa":"Item correto que exige separar clareza de correção gramatical."}},"PT-145":{"cognitivo":{"motivo":"Testar se o candidato distingue 'não apenas X' de 'não X' — a armadilha de generalização mais frequente da banca.","palavraCritica":"dispensáveis"},"comentario":{"resolucao":"ERRADO. O texto afirma que a segurança pública 'não se constrói APENAS pela repressão'. Negar a exclusividade da repressão não é negar sua necessidade: o advérbio 'apenas' restringe a afirmação, e o item o suprime para ampliá-la indevidamente.","fundamento":"Compreensão de texto — inferência válida × extrapolação.","macete":"'Não apenas X' admite X. 'Não X' exclui X. A banca troca um pelo outro o tempo todo.","erroComum":"Ler 'não apenas pela repressão' como se fosse crítica à repressão em si.","comoBancaPensa":"Amplia o escopo da afirmação original e espera que o candidato aceite por afinidade com a tese geral do texto."}},"PT-146":{"cognitivo":{"motivo":"Cobrar leitura da concessiva 'embora se alimente de dados objetivos'.","palavraCritica":"exclusivamente"},"comentario":{"resolucao":"ERRADO. O texto diz que o medo, 'embora se alimente de dados objetivos, responde igualmente à percepção de abandono'. A oração concessiva reconhece a causa objetiva, mas o 'igualmente' acrescenta outra — logo, não há exclusividade.","fundamento":"Compreensão de texto — valor da oração concessiva.","macete":"Concessiva ('embora') sinaliza que virá uma segunda causa. Desconfie de 'exclusivamente' logo depois.","erroComum":"Parar a leitura na concessiva e ignorar a oração principal.","comoBancaPensa":"Usa um termo absoluto para transformar uma causa entre duas na única causa."}},"PT-147":{"cognitivo":{"motivo":"Cobrar equivalência entre conectivos adversativos, formato recorrente da banca.","palavraCritica":"entretanto"},"comentario":{"resolucao":"CERTO. 'Contudo' e 'entretanto' são conjunções adversativas equivalentes, e ambas admitem a mesma posição intercalada entre vírgulas. A troca preserva correção e sentido.","fundamento":"Gramática — conjunções coordenativas adversativas.","macete":"Adversativas intercambiáveis: mas, porém, contudo, todavia, entretanto, no entanto.","erroComum":"Supor que toda substituição de conectivo altera o sentido.","comoBancaPensa":"Item de reescritura em que a troca é legítima — a banca também confirma, não só arma."}},"PT-148":{"cognitivo":{"motivo":"Cobrar conversão entre voz passiva pronominal e analítica, formato clássico de reescritura.","palavraCritica":"é construída"},"comentario":{"resolucao":"ERRADO. A reescrita é gramaticalmente correta, mas troca o sentido. No original, 'apenas' incide sobre o AGENTE: a repressão não é o único meio de construir a segurança pública. Na proposta, passa a incidir sobre o OBJETO: a repressão construiria outras coisas além da segurança. A conversão fiel para a voz analítica seria 'a segurança pública não é construída apenas pela repressão'.","fundamento":"Gramática — vozes verbais (passiva sintética × analítica).","macete":"Ao inverter a voz, veja sobre qual termo o 'apenas' passa a incidir — o advérbio muda de escopo quando os papéis trocam de lugar.","erroComum":"Aceitar a troca por ela ser gramaticalmente impecável, sem checar o sentido.","comoBancaPensa":"Reescrita correta na forma e errada no sentido: a banca cobra os dois critérios, e basta um falhar."}},"PT-149":{"cognitivo":{"motivo":"Cobrar a função da vírgula em contexto de zeugma, uso que a banca explora com frequência.","palavraCritica":"vírgula"},"comentario":{"resolucao":"ERRADO. A segunda oração é 'a informalidade [pode degenerar] em seletividade': a vírgula ocupa o lugar do verbo elíptico e é a marca que permite recuperá-lo. Suprimi-la deixaria 'a informalidade em seletividade' sem verbo e sem sinal da elipse. A vírgula de zeugma é obrigatória, não facultativa.","fundamento":"Gramática — pontuação e elipse (zeugma).","macete":"Vírgula 'sozinha' entre sujeito e complemento costuma marcar verbo omitido — e, nesse caso, é obrigatória.","erroComum":"Estender a ideia de que vírgula entre termos é sempre estilística.","comoBancaPensa":"Afirma facultatividade onde há obrigatoriedade — inverter o regime da regra é padrão da banca."}},"PT-150":{"cognitivo":{"motivo":"Cobrar recuperação de referente, distinguindo retomada de termo e retomada de proposição.","palavraCritica":"exclusivamente"},"comentario":{"resolucao":"CERTO. 'Isso' é pronome demonstrativo de retomada ampla: recupera toda a proposição anterior — a de que a presença regular do agente reduz a sensação de insegurança antes de alterar os índices criminais —, e não um substantivo isolado.","fundamento":"Coesão referencial — anáfora resumitiva.","macete":"'Isso' costuma retomar oração ou período inteiro; pronomes como 'ele/ela' é que retomam substantivos.","erroComum":"Procurar um substantivo próximo e assumir que é o referente.","comoBancaPensa":"Item curto e correto: a banca também confirma leituras, e quem responde ERRADO por reflexo perde ponto."}},"PT-151":{"cognitivo":{"motivo":"Cobrar função sintática de um termo do texto, e não classificação de oração descontextualizada.","palavraCritica":"predicativo do sujeito"},"comentario":{"resolucao":"CERTO. O verbo 'ser' é de ligação e não pede complemento, mas atribui característica ao sujeito 'a informação'. O termo que exprime essa característica é o predicativo do sujeito.","fundamento":"Sintaxe — predicado nominal e predicativo do sujeito.","macete":"Verbo de ligação nunca tem objeto: o que vem depois é predicativo.","erroComum":"Classificar o trecho como objeto direto por vir depois do verbo.","comoBancaPensa":"Pergunta a função de um termo REAL do texto — é assim que a sintaxe aparece na prova."}},"PT-152":{"cognitivo":{"motivo":"Testar leitura da concessiva 'por mais eloquente que pareça'.","palavraCritica":"convalidada"},"comentario":{"resolucao":"ERRADO. O texto afirma exatamente o contrário: 'Sem autorização judicial, o material obtido é imprestável, POR MAIS ELOQUENTE QUE PAREÇA'. A concessiva antecipa e rejeita a hipótese que o item propõe.","fundamento":"Compreensão de texto — oração concessiva e escopo da negação.","macete":"'Por mais X que' antecipa a objeção e a descarta. Item que ressuscita a objeção descartada é ERRADO.","erroComum":"Associar 'eloquente' a valor probatório e concluir pela convalidação.","comoBancaPensa":"Propõe justamente a exceção que o texto já havia fechado."}},"PT-153":{"cognitivo":{"motivo":"Cobrar leitura da negação de equivalência no último parágrafo.","palavraCritica":"por si só"},"comentario":{"resolucao":"ERRADO. O texto diz que 'o excesso de dados não equivale a excesso de esclarecimento' e conclui que a tecnologia 'não dispensa de raciocinar' — negando exatamente a suficiência que o item afirma.","fundamento":"Compreensão de texto — negação de equivalência.","macete":"'Não equivale a' nega a correspondência automática; 'por si só' a reintroduz.","erroComum":"Confundir 'a tecnologia amplia o alcance' com 'a tecnologia basta'.","comoBancaPensa":"Inverte a tese central do parágrafo mantendo o vocabulário do texto."}},"PT-154":{"cognitivo":{"motivo":"Cobrar conversão de oração reduzida de particípio em desenvolvida, preservando o valor condicional.","palavraCritica":"caso sejam observadas"},"comentario":{"resolucao":"ERRADO. A reduzida de particípio desenvolve-se corretamente como 'caso SEJAM observadas' — presente do subjuntivo, em correlação com 'tem', presente do indicativo. O pretérito imperfeito 'fossem' rompe essa correlação e desloca a condição para o campo do hipotético irreal, alterando o sentido do período.","fundamento":"Gramática — orações reduzidas e seu desenvolvimento.","macete":"Condicional exige correlação de tempos: presente com presente ('tem ... sejam'); passado com passado ('teria ... fossem').","erroComum":"Conferir só o conectivo — 'caso' está certo — e não olhar o tempo verbal.","comoBancaPensa":"Acerta o conectivo para desviar a atenção do tempo verbal, que é onde mora o erro."}},"PT-155":{"cognitivo":{"motivo":"Cobrar próclise obrigatória diante de pronome relativo, uma das armadilhas favoritas da banca.","palavraCritica":"destaca-se"},"comentario":{"resolucao":"ERRADO. O pronome relativo 'as quais' é palavra atrativa e exige próclise: o correto é 'se destaca'. A ênclise proposta ('destaca-se') viola a norma-padrão nesse contexto.","fundamento":"Gramática — colocação pronominal (palavras atrativas).","macete":"Pronome relativo (que, quem, o qual, cujo) puxa o pronome para antes do verbo.","erroComum":"Aplicar a regra geral da ênclise sem notar o relativo que antecede o verbo.","comoBancaPensa":"Propõe uma troca que 'soa natural' na fala, mas quebra a regra de atração."}},"PT-156":{"cognitivo":{"motivo":"Cobrar equivalência entre sinais de intercalação, formato frequente na banca.","palavraCritica":"parênteses"},"comentario":{"resolucao":"CERTO. Os travessões isolam a enumeração explicativa 'impressões digitais, fibras, marcas de ferramenta'. Travessão duplo, parênteses e vírgulas duplas são recursos alternativos de intercalação; aqui, como o trecho já contém vírgulas internas, o parêntese é inclusive a opção mais clara.","fundamento":"Gramática — pontuação de termos intercalados.","macete":"Travessão duplo ≈ parênteses ≈ vírgulas duplas. Havendo vírgulas dentro, prefira travessão ou parêntese.","erroComum":"Supor que cada sinal tem uso exclusivo e insubstituível.","comoBancaPensa":"Confirma uma equivalência real — nem todo item de pontuação é armadilha."}},"PT-157":{"cognitivo":{"motivo":"Cobrar substituição vocabular adequada ao contexto, um dos formatos mais frequentes da banca.","palavraCritica":"fundamentalmente"},"comentario":{"resolucao":"CERTO. Em 'Investigar continua sendo, essencialmente, formular boas perguntas', o advérbio indica o traço central da atividade. 'Fundamentalmente' expressa o mesmo valor e ocupa a mesma posição intercalada, preservando sentido e correção.","fundamento":"Semântica — sinonímia contextual.","macete":"Teste o sinônimo NA FRASE, não no dicionário: precisa caber na sintaxe e no sentido.","erroComum":"Rejeitar a troca por achar que sinônimos nunca são perfeitamente intercambiáveis.","comoBancaPensa":"Modelo típico: 'o vocábulo X poderia ser substituído por Y sem prejuízo do sentido'."}},"PT-158":{"cognitivo":{"motivo":"Cobrar função sintática e referência do pronome oblíquo, unindo sintaxe e coesão como faz a banca.","palavraCritica":"objeto direto"},"comentario":{"resolucao":"CERTO. 'Dispensar' é transitivo direto ('dispensar alguém de algo'), e o pronome oblíquo átono 'o' funciona como seu objeto direto, retomando 'o investigador', mencionado na oração anterior.","fundamento":"Sintaxe — objeto direto pronominal; coesão referencial.","macete":"Os pronomes o/a/os/as são objeto DIRETO; lhe/lhes, objeto indireto.","erroComum":"Ler o 'o' como artigo definido.","comoBancaPensa":"Junta função sintática e recuperação de referente num item só."}},"PT-159":{"cognitivo":{"motivo":"Cobrar identificação do tipo textual predominante a partir da estrutura do texto.","palavraCritica":"refuta uma objeção"},"comentario":{"resolucao":"CERTO. O texto sustenta a tese de que preservar não é congelar e, no terceiro parágrafo, apresenta a objeção ('Há quem veja na preservação um obstáculo ao desenvolvimento') para refutá-la ('O argumento seduz, mas ignora...'). Defender tese e refutar contra-argumento caracteriza o dissertativo-argumentativo.","fundamento":"Tipologia textual — dissertativo-argumentativo × expositivo.","macete":"Expositivo informa; argumentativo toma partido. Presença de refutação é marca do argumentativo.","erroComum":"Classificar como expositivo por causa do tom informativo do primeiro parágrafo.","comoBancaPensa":"Pede o tipo PREDOMINANTE, e não o único presente no texto."}},"PT-160":{"cognitivo":{"motivo":"Testar a distinção entre disciplinar e proibir.","palavraCritica":"qualquer"},"comentario":{"resolucao":"ERRADO. O texto afirma que o tombamento 'não interrompe a vida do bem; disciplina as intervenções que ele pode sofrer'. Disciplinar pressupõe que as intervenções existam e sejam admissíveis — o oposto de impedi-las.","fundamento":"Compreensão de texto — leitura de termos absolutos.","macete":"'Disciplinar' regula; 'impedir' proíbe. A banca troca um verbo pelo outro.","erroComum":"Associar tombamento a intocabilidade, contrariando o que o próprio texto nega.","comoBancaPensa":"Aproveita o senso comum sobre o tema para desviar da leitura literal."}},"PT-161":{"cognitivo":{"motivo":"Cobrar a conclusão do último parágrafo, que aponta perda e não ganho.","palavraCritica":"competitivas"},"comentario":{"resolucao":"CERTO. O texto conclui que cidades que destruíram sua memória 'perderam o que as distinguia e ficaram parecidas com todas as outras' — ou seja, tornaram-se menos distinguíveis entre si. A inferência reproduz a consequência afirmada.","fundamento":"Compreensão de texto — identificação da conclusão do autor.","macete":"Os dois-pontos finais explicitam a consequência: leia o que vem depois deles.","erroComum":"Rejeitar a inferência por ela reformular o texto com outras palavras.","comoBancaPensa":"Inferência legítima e enxuta — nem todo item curto é armadilha."}},"PT-162":{"cognitivo":{"motivo":"Cobrar a troca entre 'haver' impessoal e 'existir', com a concordância que ela exige.","palavraCritica":"Existem"},"comentario":{"resolucao":"CERTO. 'Haver' no sentido de existir é impessoal e fica no singular; ao ser substituído por 'existir', o termo passa a ser SUJEITO e exige concordância — daí 'Existem pessoas'. A reescrita respeita essa mudança e mantém o sentido.","fundamento":"Gramática — verbo haver impessoal e concordância verbal.","macete":"Haver = invariável. Existir = concorda. Trocar um pelo outro obriga a ajustar o número.","erroComum":"Reescrever como 'Existe pessoas', mantendo o singular do 'há'.","comoBancaPensa":"Testa se o candidato sabe que a troca de verbo arrasta consequência de concordância."}},"PT-163":{"cognitivo":{"motivo":"Cobrar o efeito semântico das vírgulas na oração adjetiva — restritiva vira explicativa.","palavraCritica":"vírgulas"},"comentario":{"resolucao":"ERRADO. Sem vírgulas, a adjetiva é RESTRITIVA: só perde a função o bem que se torna intocável. Com vírgulas, torna-se EXPLICATIVA e passa a afirmar que todo bem cultural se torna intocável — o que altera profundamente o sentido, embora a frase continue gramaticalmente correta.","fundamento":"Sintaxe e pontuação — orações adjetivas restritivas e explicativas.","macete":"Vírgula na adjetiva generaliza: o que valia para alguns passa a valer para todos.","erroComum":"Julgar apenas a correção gramatical e ignorar a alteração de sentido.","comoBancaPensa":"A reescritura pode ser gramatical e ainda assim ERRADA por mudar o sentido — a banca cobra os dois critérios."}},"PT-164":{"cognitivo":{"motivo":"Cobrar o valor semântico do ponto e vírgula entre orações coordenadas.","palavraCritica":"mas"},"comentario":{"resolucao":"ERRADO. A relação entre as orações é ADVERSATIVA ('não interrompe' × 'disciplina'), e o conectivo capaz de explicitá-la seria 'mas'. 'Pois' é explicativo ou conclusivo: introduziria uma justificativa que não existe ali e alteraria a relação lógica sinalizada pelo ponto e vírgula.","fundamento":"Gramática — pontuação entre orações coordenadas.","macete":"Ponto e vírgula entre orações esconde um conectivo: descubra QUAL antes de aceitar o que o item propõe.","erroComum":"Aceitar qualquer conectivo por perceber, corretamente, que o ponto e vírgula admite substituição.","comoBancaPensa":"Acerta o diagnóstico ('conteúdo contrastante') e erra a solução — o item começa verdadeiro e termina falso."}},"PT-165":{"cognitivo":{"motivo":"Cobrar recuperação de referente em posição que induz ao termo mais próximo.","palavraCritica":"lhe"},"comentario":{"resolucao":"ERRADO. O 'lhe' retoma 'Um bem cultural', sujeito do período: é a função que deu origem AO BEM, e não a função que deu origem a si mesma. O termo mais próximo ('a função') é justamente o distrator.","fundamento":"Coesão referencial — pronome oblíquo átono.","macete":"Refaça a frase substituindo o pronome pelo candidato a referente: se o resultado for circular, o referente é outro.","erroComum":"Escolher o substantivo imediatamente anterior ao pronome.","comoBancaPensa":"Explora a proximidade física como falsa pista de referência."}},"PT-166":{"cognitivo":{"motivo":"Cobrar a leitura da estrutura 'não é X; é Y' que fecha o texto.","palavraCritica":"por si só"},"comentario":{"resolucao":"ERRADO. O texto encerra afirmando: 'O que corrói a confiança não é a negativa; é a negativa sem explicação'. O fator apontado não é a negativa, mas a ausência de justificativa que a acompanha.","fundamento":"Compreensão de texto — estrutura de retificação ('não é X; é Y').","macete":"Na estrutura 'não é X; é Y', o item que afirma X é ERRADO por definição.","erroComum":"Reter apenas a palavra 'negativa' e ignorar o complemento 'sem explicação'.","comoBancaPensa":"Aproveita a semelhança lexical entre a tese e a sua negação."}},"PT-167":{"cognitivo":{"motivo":"Cobrar a regência de 'implicar' no sentido de acarretar, desvio frequente na fala.","palavraCritica":"em"},"comentario":{"resolucao":"ERRADO. No sentido de 'acarretar, ter como consequência', 'implicar' é transitivo DIRETO e não admite a preposição: 'implica tratar', e não 'implica em tratar'. A reescrita introduz um desvio de regência.","fundamento":"Gramática — regência verbal.","macete":"Implicar = acarretar → VTD, sem preposição. Só há 'implicar-se em' no sentido de envolver-se.","erroComum":"Aceitar 'implicar em' por ser corrente na linguagem oral.","comoBancaPensa":"Propõe a forma coloquial e conta com a familiaridade do candidato."}},"PT-168":{"cognitivo":{"motivo":"Cobrar equivalência entre conectivos concessivos, com o subjuntivo que ambos regem.","palavraCritica":"embora"},"comentario":{"resolucao":"CERTO. 'Ainda que' e 'embora' são conjunções subordinativas concessivas equivalentes, e ambas exigem o verbo no subjuntivo — condição já satisfeita por 'tenha sido negada'. Sentido e correção se mantêm.","fundamento":"Gramática — conjunções subordinativas concessivas.","macete":"Concessivas equivalentes: embora, ainda que, conquanto, mesmo que, posto que — todas com subjuntivo.","erroComum":"Confundir concessiva com condicional e supor alteração de sentido.","comoBancaPensa":"Item de reescritura legítimo, para punir quem responde ERRADO por reflexo."}},"PT-169":{"cognitivo":{"motivo":"Cobrar o valor dos dois-pontos como introdutor de esclarecimento.","palavraCritica":"dois-pontos"},"comentario":{"resolucao":"CERTO. A segunda oração esclarece e retifica a primeira, valor compatível com os dois-pontos, que introduzem explicitação. A substituição mantém a correção gramatical do período.","fundamento":"Gramática — emprego dos dois-pontos e do ponto e vírgula.","macete":"Dois-pontos anunciam o que vem a seguir: explicação, enumeração, citação, retificação.","erroComum":"Restringir os dois-pontos a enumerações e falas.","comoBancaPensa":"Testa se o candidato conhece o valor de esclarecimento dos dois-pontos."}},"PT-170":{"cognitivo":{"motivo":"Cobrar recuperação de referente com distratores plausíveis no mesmo período.","palavraCritica":"a"},"comentario":{"resolucao":"CERTO. O pronome oblíquo 'a' retoma 'a administração', objeto direto de 'avalia' no mesmo período: é a administração que a lei rege. Os termos da enumeração anterior ('uma delegacia', 'um posto de saúde', 'uma repartição fazendária') são distratores.","fundamento":"Coesão referencial — pronome oblíquo átono como objeto direto.","macete":"Substitua o pronome pelo candidato e leia em voz alta: 'a lei que rege a administração' faz sentido; 'que rege uma repartição fazendária' não retoma o fio do período.","erroComum":"Escolher um termo da enumeração por estar mais próximo do pronome.","comoBancaPensa":"Enche o período de referentes possíveis e afirma o correto — o candidato precisa confirmar, não desconfiar por hábito."}},"PT-171":{"cognitivo":{"motivo":"Verificar leitura semântica básica antes de itens mais finos de vocabulário.","palavraCritica":"fortalece"},"comentario":{"resolucao":"CERTO. 'Corroer' e 'minar' compartilham o sentido de desgastar aos poucos, solapar. Ambos são transitivos diretos e cabem na mesma estrutura ('o que mina a confiança'), preservando sentido e correção.","fundamento":"Semântica — sinonímia e antonímia em contexto.","macete":"Teste o sinônimo na frase: se o sentido e a regência couberem, a troca vale.","erroComum":"Rejeitar sinônimos por achar que nunca são intercambiáveis.","comoBancaPensa":"Substituição vocabular legítima, no formato mais frequente da banca."}},"PT-172":{"cognitivo":{"motivo":"Cobrar identificação de sujeito num período com enumeração intercalada — formato que a banca usa para afastar sujeito e verbo.","palavraCritica":"sujeito"},"comentario":{"resolucao":"CERTO. 'Quem procura uma delegacia...' é oração subordinada substantiva que funciona como sujeito de 'não avalia'. A enumeração intercalada afasta o núcleo do verbo, mas não altera a relação sintática.","fundamento":"Sintaxe — sujeito oracional; pronome relativo indefinido 'quem'.","macete":"Pergunte ao verbo: quem não avalia? A resposta é o sujeito, ainda que esteja longe.","erroComum":"Tomar 'a administração' por sujeito, por vir logo antes do verbo seguinte.","comoBancaPensa":"Distancia sujeito e verbo com material intercalado e cobra a identificação."}},"PT-173":{"cognitivo":{"motivo":"O verbo já tem seu complemento na oração — o outro termo só pode ser adjunto.","palavraCritica":"sem motivo"},"comentario":{"resolucao":"ERRADO. O complemento de 'faz' é o pronome indefinido 'nada', que funciona como objeto direto — 'ele faz nada', na ordem direta. 'Sem motivo' é ADJUNTO ADVERBIAL de causa (ou modo), termo acessório que exprime circunstância e não integra a regência do verbo. O teste é direto: complemento completa o sentido de um verbo transitivo e não pode ser suprimido sem prejuízo sintático; adjunto pode ser retirado e a oração continua de pé — 'Ele nada faz' permanece completa. Ajuda ainda observar que a preposição 'sem' não é exigida pelo verbo fazer, mas escolhida para exprimir a circunstância.","fundamento":"Gramática normativa — termos integrantes e termos acessórios da oração.","macete":"Tire o termo: se a oração continua completa, era adjunto.","erroComum":"Chamar de complemento todo termo preposicionado que vem depois do verbo.","comoBancaPensa":"Escolhe uma oração curta em ordem indireta, para que o verdadeiro objeto passe despercebido."}},"PT-174":{"cognitivo":{"motivo":"Os dois verbos são sinônimos no sentido, mas têm regimes diferentes: um é impessoal, o outro não.","palavraCritica":"dúvidas"},"comentario":{"resolucao":"ERRADO. 'Haver' no sentido de existir é verbo IMPESSOAL: não tem sujeito, fica sempre na terceira pessoa do singular e o termo que o acompanha é objeto direto — por isso 'há dúvidas' está correto. Já 'existir' é verbo PESSOAL: tem sujeito e com ele concorda. Como 'dúvidas' está no plural, a substituição correta seria 'EXISTEM dúvidas', e não 'existe dúvidas'. A troca proposta produz erro de concordância. Vale estender a regra: o mesmo vale para 'fazer' indicando tempo decorrido, também impessoal ('faz dez anos'), e a impessoalidade se transmite ao auxiliar em locuções ('deve haver dúvidas', nunca 'devem haver').","fundamento":"Gramática normativa — verbos impessoais e concordância verbal.","macete":"Haver não concorda, existir concorda. Há dúvidas, existem dúvidas.","erroComum":"Tratar os dois como intercambiáveis por serem sinônimos.","comoBancaPensa":"Propõe uma substituição semanticamente perfeita e sintaticamente inválida."}},"PT-175":{"cognitivo":{"motivo":"Um dos três casos clássicos de crase facultativa — e o menos lembrado dos três.","palavraCritica":"sua"},"comentario":{"resolucao":"CERTO. Antes de pronome possessivo feminino singular, o uso do artigo é FACULTATIVO — pode-se dizer 'à sua volta' ou 'a sua volta' —, e como a crase depende da fusão da preposição com o artigo, ela acompanha essa facultatividade. São três os casos clássicos de crase facultativa, e vale memorizá-los juntos: antes de possessivo feminino singular, antes de nome próprio feminino de pessoa ('Refiro-me a/à Maria') e depois da preposição 'até' ('Foi até a/à porta'). Fora deles, a crase é obrigatória ou proibida, sem meio-termo.","fundamento":"Gramática normativa — emprego do acento grave indicativo de crase.","macete":"Facultativa em três casos: possessivo feminino, nome de mulher e depois de 'até'.","erroComum":"Tratar toda crase como obrigatória ou proibida, sem admitir a faixa facultativa.","comoBancaPensa":"Escolhe o caso facultativo menos conhecido dos três."}},"PT-176":{"cognitivo":{"motivo":"Aferir a leitura da tese central, enunciada já na primeira linha e retomada ao longo do texto.","palavraCritica":"isoladamente"},"comentario":{"resolucao":"CERTO. O texto abre afirmando que 'a formação do policial não termina na academia' e, em seguida, chama de suposição desmentida pela realidade a ideia de que 'o curso de ingresso bastava para toda a carreira'. O item reformula essa tese sem ampliá-la: diz que o curso não basta SOZINHO, não que seja inútil.","fundamento":"Compreensão de texto — identificação da tese.","macete":"Tese costuma estar na primeira ou na última linha do parágrafo de abertura. Leia essas duas antes de tudo.","erroComum":"Rejeitar o item por achar que ele desvaloriza a academia, quando apenas nega a suficiência dela.","comoBancaPensa":"Item curto e correto, colocado no começo do bloco para o candidato que só desconfia de afirmação categórica marcar ERRADO por reflexo."}},"PT-177":{"cognitivo":{"motivo":"Testar se o candidato percebe que o advérbio 'sobretudo' quebra a suposta equivalência entre os itens da enumeração.","palavraCritica":"sobretudo"},"comentario":{"resolucao":"ERRADO. A enumeração existe, mas não é equivalente: o autor escreve 'e mudam, SOBRETUDO, as expectativas da sociedade', e 'sobretudo' marca justamente hierarquia, destacando o terceiro elemento sobre os dois primeiros. Além disso, o texto em nenhum momento afirma que cada causa, isolada, seria insuficiente para justificar a capacitação — essa conclusão é acrescentada pelo item.","fundamento":"Compreensão de texto — valor semântico do advérbio de realce; extrapolação.","macete":"Numa enumeração, procure o advérbio: 'sobretudo', 'principalmente', 'em especial' desfazem a ideia de lista de iguais.","erroComum":"Validar o item pela parte verdadeira (a enumeração existe) e não julgar a conclusão emendada.","comoBancaPensa":"Enunciado longo, com uma descrição fiel na abertura e duas afirmações falsas diluídas no meio — o candidato cansa antes de chegar nelas."}},"PT-178":{"cognitivo":{"motivo":"Cobrar equivalência entre advérbio em -mente e locução adverbial correspondente.","palavraCritica":"indefinidamente"},"comentario":{"resolucao":"CERTO. 'Indefinidamente' e a locução 'sem fim' são equivalentes no contexto: ambas indicam ausência de termo. O deslocamento da locução para entre vírgulas é permitido e não altera a regência nem a estrutura do período, que permanece uma oração subordinada adverbial comparativa introduzida por 'como se', com verbo no pretérito imperfeito do subjuntivo.","fundamento":"Semântica e sintaxe — equivalência entre advérbio e locução adverbial.","macete":"Advérbio em -mente quase sempre tem locução equivalente. O que muda é o ritmo da frase, não o sentido.","erroComum":"Recusar a troca por achar que a vírgula acrescenta pausa e, com ela, sentido novo.","comoBancaPensa":"Reescritura legítima, para punir quem marca ERRADO em toda proposta de substituição."}},"PT-179":{"cognitivo":{"motivo":"Testar o deslocamento do advérbio 'apenas', que muda o escopo da negação.","palavraCritica":"apenas"},"comentario":{"resolucao":"ERRADO. No original, 'apenas' está dentro do escopo da negação: 'não recai APENAS sobre o servidor' significa que recai sobre ele E sobre mais alguém. Na reescritura, 'apenas' migra para o segundo termo e a negação passa a excluir o servidor — 'não recai sobre o servidor, mas apenas sobre a investigação'. O sentido se inverte: quem estava incluído passa a estar excluído.","fundamento":"Semântica — escopo da negação e posição do advérbio de exclusão.","macete":"Mexer em 'apenas', 'só' e 'somente' dentro de frase negativa quase sempre troca quem está dentro por quem está fora. Refaça a conta em voz alta.","erroComum":"Aceitar a troca por ver que os dois-pontos realmente admitem substituição por conectivo — o que é verdade, mas não neste arranjo.","comoBancaPensa":"Oferece uma justificativa gramatical correta (dois-pontos × adversativa) para encobrir a alteração de sentido, que é o que de fato se cobra."}},"PT-180":{"cognitivo":{"motivo":"Cobrar o uso do ponto e vírgula como separador de coordenadas simétricas.","palavraCritica":"coordenadas"},"comentario":{"resolucao":"CERTO. As duas orações têm desenho idêntico — sujeito com oração adjetiva restritiva ('Um agente que desconhece a cadeia de custódia' / 'um escrivão que ignora a redação técnica') seguido de verbo e objeto ('compromete a prova' / 'compromete o inquérito'). O ponto e vírgula marca essa simetria e a fronteira entre elas com pausa mais forte que a vírgula, uso previsto para coordenadas extensas ou que já contenham pontuação interna.","fundamento":"Pontuação — ponto e vírgula entre orações coordenadas.","macete":"Duas frases com o mesmo esqueleto, lado a lado? Ponto e vírgula cabe.","erroComum":"Supor que ponto e vírgula só se usa em enumeração de itens.","comoBancaPensa":"Item curto e verdadeiro sobre pontuação, área em que o candidato costuma desconfiar de tudo."}},"PT-181":{"cognitivo":{"motivo":"Verificar se o candidato rastreia corretamente dois elementos anafóricos no mesmo período.","palavraCritica":"lhe"},"comentario":{"resolucao":"ERRADO, em duas frentes. Primeira: 'lhe' retoma O POLICIAL, não a instituição — quem deixa de receber a carga horária é ele; e 'para isso' retoma ESTUDAR, não o dever institucional. Segunda: suprimir os dois termos deixaria 'sem assegurar carga horária', sem indicação de a quem nem para quê, o que rompe justamente a progressão referencial que o item diz preservada.","fundamento":"Coesão — anáfora pronominal e anáfora por expressão adverbial.","macete":"Pronome oblíquo procura o beneficiário ou o prejudicado da ação, quase sempre pessoa. 'Isso' procura o que veio antes como processo.","erroComum":"Puxar 'lhe' para o substantivo mais próximo ('instituição') em vez de para o referente semanticamente compatível.","comoBancaPensa":"Empilha dois referentes num período só e fecha com uma conclusão sobre supressão, que exige refazer a leitura inteira."}},"PT-182":{"cognitivo":{"motivo":"Cobrar o reconhecimento de sujeito posposto, arranjo frequente na prosa institucional.","palavraCritica":"mudam"},"comentario":{"resolucao":"CERTO. 'Mudar' está empregado como verbo intransitivo — as leis mudam, sofrem alteração. 'As leis' é quem pratica (ou sofre) o processo verbal e determina a flexão de número do verbo, que vai ao plural: é o sujeito, apenas posposto. A ordem inversa é escolha estilística, não muda a função sintática.","fundamento":"Sintaxe — sujeito posposto; concordância verbal.","macete":"Pergunte 'quem muda?'. Se o verbo concorda com a resposta, é sujeito, esteja ele antes ou depois.","erroComum":"Chamar 'as leis' de objeto direto por vir depois do verbo.","comoBancaPensa":"Item curto de sintaxe sobre trecho citado — formato exato dos itens 16 e 20 da prova de 2021."}},"PT-183":{"cognitivo":{"motivo":"Testar se o candidato percebe a inversão completa da atribuição de responsabilidade.","palavraCritica":"fiscalizar"},"comentario":{"resolucao":"ERRADO. O texto diz o contrário em todos os pontos. O obstáculo apontado é O TEMPO, não a falta de interesse; o servidor NÃO dispõe de carga horária, e é justamente essa ausência que o autor critica; e a conclusão é que exigir estudo sem assegurar tempo 'é transferir ao indivíduo um dever que é da instituição' — ou seja, o dever é institucional, e não se reduz a fiscalizar.","fundamento":"Compreensão de texto — atribuição de responsabilidade.","macete":"Quando o item transfere a culpa de quem o texto acusa para quem o texto defende, é inversão. Confira o sujeito da última frase.","erroComum":"Aceitar por reconhecer termos do texto ('carga horária', 'instituição') sem conferir o que se afirma sobre eles.","comoBancaPensa":"Reaproveita o vocabulário do parágrafo e inverte as relações — o candidato reconhece as palavras e supõe que reconheceu a ideia."}},"PT-184":{"cognitivo":{"motivo":"Cobrar equivalência entre oração reduzida de infinitivo com valor de finalidade-consecução e coordenada aditiva.","palavraCritica":"tornar-se"},"comentario":{"resolucao":"CERTO. No original, 'para tornar-se' não exprime finalidade deliberada, e sim a transformação que se seguiu ao abandono da condição anterior — leitura consecutiva. 'E passou a ser' explicita essa mesma sucessão sem alterar os termos comparados nem a correção do período.","fundamento":"Sintaxe do período composto — oração reduzida de infinitivo com valor consecutivo.","macete":"'Deixou de X para Y' equivale a 'deixou de X e passou a Y' quando não há intenção envolvida, só sucessão.","erroComum":"Ler todo 'para + infinitivo' como finalidade e recusar a equivalência.","comoBancaPensa":"Reescritura correta cujo teste exige distinguir finalidade de consecução — distinção que quase ninguém revisa."}},"PT-185":{"cognitivo":{"motivo":"Testar uma exigência inventada sobre o emprego dos dois-pontos.","palavraCritica":"exigiriam"},"comentario":{"resolucao":"ERRADO. A primeira metade está certa: a vírgula substitui o travessão nesse aposto especificativo. A segunda inventa uma regra — os dois-pontos introduzem enumeração, mas também esclarecimento, explicação ou aposto de um único termo. 'Há, contudo, um obstáculo menos discutido: o tempo' é construção perfeitamente correta.","fundamento":"Pontuação — travessão, vírgula e dois-pontos na introdução de aposto.","macete":"Dois-pontos anunciam o que vem depois. Não contam quantos itens virão.","erroComum":"Aceitar a exigência por ser apresentada com aparência de regra técnica.","comoBancaPensa":"Ancora o item numa afirmação verdadeira (a vírgula serve) para dar credibilidade à regra falsa que vem em seguida."}},"PT-186":{"cognitivo":{"motivo":"Cobrar a identificação da tipologia predominante, item recorrente na abertura dos blocos de Português.","palavraCritica":"predomina"},"comentario":{"resolucao":"CERTO. O texto defende uma tese ('a formação não termina na academia'), sustenta-a com argumentos (mudança das leis, das tecnologias e das expectativas; exemplos do agente e do escrivão) e conclui com uma posição sobre a responsabilidade institucional. Não narra fatos em sequência temporal nem descreve objetos: argumenta.","fundamento":"Tipologia textual — dissertação argumentativa.","macete":"Tem tese + argumento + conclusão? É dissertativo-argumentativo, ainda que haja exemplos narrados de passagem.","erroComum":"Classificar como expositivo por causa do tom impessoal, ignorando que há defesa de ponto de vista.","comoBancaPensa":"Item de baixa dificuldade que serve de âncora ao bloco — errar aqui costuma indicar leitura apressada do conjunto."}},"PT-187":{"cognitivo":{"motivo":"Aferir a leitura do paradoxo central do segundo parágrafo.","palavraCritica":"transformação"},"comentario":{"resolucao":"CERTO. O texto afirma que 'o que poderia parecer perda é, na verdade, condição de sobrevivência da narrativa' e fecha o raciocínio com 'o que não se transforma não se transmite'. O item reformula exatamente essa relação: mudar não é o oposto de permanecer, é o meio de permanecer.","fundamento":"Compreensão de texto — inferência a partir de relação causal explícita.","macete":"Quando o texto diz 'o que parece X é, na verdade, Y', a tese é Y. Sublinhe o 'na verdade'.","erroComum":"Ler a variação entre versões como defeito, contra o que o texto sustenta.","comoBancaPensa":"Item curto e correto sobre a tese menos intuitiva do texto."}},"PT-188":{"cognitivo":{"motivo":"Testar se o candidato distingue ponderação de recomendação contrária.","palavraCritica":"exclusivamente"},"comentario":{"resolucao":"ERRADO. O texto pondera, não proíbe: registrar 'é tarefa delicada', 'ajuda a protegê-las do esquecimento, MAS corre o risco de imobilizar'. Reconhecer um risco não é recomendar que se abandone a prática, e em nenhum momento se afirma que o dano do registro supere o do esquecimento nem que a preservação deva ficar 'exclusivamente' com a transmissão oral.","fundamento":"Compreensão de texto — ponderação × recomendação; extrapolação por termo absoluto.","macete":"'Ajuda, mas corre o risco' é balanço. Item que transforma balanço em veredicto está ampliando.","erroComum":"Confundir o alerta final com uma tese contrária ao registro.","comoBancaPensa":"Enunciado longo que acumula três extrapolações encadeadas, cada uma plausível se lida sozinha."}},"PT-189":{"cognitivo":{"motivo":"Cobrar o valor explicativo dos dois-pontos, distinto da enumeração.","palavraCritica":"introduzem"},"comentario":{"resolucao":"CERTO. A primeira oração nega um lugar de guarda ('não se guarda em arquivos') e a segunda, após os dois-pontos, informa o lugar efetivo ('guarda-se na boca de quem conta'). É a função explicativa clássica do sinal: o que vem depois esclarece o que veio antes.","fundamento":"Pontuação — dois-pontos de valor explicativo.","macete":"Dois-pontos = 'ou seja', 'isto é', 'a saber'. Se couber um desses no lugar, o uso está correto.","erroComum":"Restringir os dois-pontos à introdução de citação ou de lista.","comoBancaPensa":"Afirmação curta e verdadeira sobre pontuação, formato em que o candidato tende a marcar ERRADO por precaução."}},"PT-190":{"cognitivo":{"motivo":"Verificar o rastreio do antecedente mais próximo e semanticamente compatível.","palavraCritica":"ela"},"comentario":{"resolucao":"ERRADO. 'Ela' retoma 'uma história', antecedente imediato e sujeito da oração anterior — é a história recontada que se ajusta ao ouvinte a cada narração. Substituir por 'essa memória' trocaria o referente e generalizaria indevidamente: o texto trata do ajuste de CADA narrativa, não da memória como um todo.","fundamento":"Coesão — anáfora pronominal e escolha do antecedente.","macete":"Pronome pessoal reto costuma retomar o sujeito mais próximo com que concorda em gênero e número. Teste substituindo.","erroComum":"Puxar o pronome para o tema do parágrafo em vez do antecedente sintático.","comoBancaPensa":"Oferece um antecedente plausível pelo assunto e outro correto pela sintaxe, e conta com o candidato escolher pelo assunto."}},"PT-191":{"cognitivo":{"motivo":"Cobrar o reconhecimento do sujeito que resume uma enumeração anterior ao travessão.","palavraCritica":"todos"},"comentario":{"resolucao":"CERTO. A enumeração — o repentista, a rezadeira, o mestre de banda — é retomada e resumida por 'todos', que concorda com 'exercem' e responde à pergunta 'quem exerce o ofício de lembrar?'. É o sujeito do período, e o travessão marca justamente a retomada resumitiva.","fundamento":"Sintaxe — sujeito; aposto resumitivo.","macete":"Enumeração longa seguida de travessão e de 'todos/tudo/ninguém' = sujeito resumido. O verbo concorda com o resumo.","erroComum":"Apontar a enumeração como sujeito e 'todos' como aposto — é o inverso.","comoBancaPensa":"Item curto sobre função de termo citado, no formato dos itens de sintaxe da prova real."}},"PT-192":{"cognitivo":{"motivo":"Cobrar equivalência entre oração reduzida de infinitivo e desenvolvida, com mudança de voz.","palavraCritica":"protegê-las"},"comentario":{"resolucao":"CERTO. A reduzida de infinitivo 'a protegê-las' desenvolve-se em 'a que sejam protegidas', com o objeto direto do original ('-las') passando a sujeito da voz passiva. A regência de 'ajudar a' é mantida, e o sentido permanece: em ambos os casos o registro escrito favorece a proteção das manifestações.","fundamento":"Sintaxe — desenvolvimento de oração reduzida; conversão de voz.","macete":"Reduzida vira desenvolvida trocando infinitivo por 'que + verbo flexionado'. Confira só se a regência sobrevive.","erroComum":"Recusar por estranhar a construção 'ajuda a que', que é correta e registrada.","comoBancaPensa":"Testa se o candidato sabe converter reduzida em desenvolvida sem se assustar com a forma resultante."}},"PT-193":{"cognitivo":{"motivo":"Testar a substituição de relações temporal e consecutiva por concessivas.","palavraCritica":"por isso"},"comentario":{"resolucao":"ERRADO. O original encadeia tempo e consequência: 'cada vez que' é temporal-iterativo e 'por isso' introduz a consequência. A reescritura troca as duas por concessão — 'ainda que' e 'embora' —, o que inverte a lógica: o ajuste deixaria de causar a diferença entre versões e passaria a ocorrer apesar dela. A relação entre as ideias muda por inteiro.","fundamento":"Sintaxe do período composto — valor semântico dos conectivos.","macete":"Temporal e consecutivo somam; concessivo contraria. Trocar um pelo outro nunca preserva sentido.","erroComum":"Aprovar a reescritura por ela manter todas as palavras de conteúdo, mexendo só nos conectivos — que é exatamente onde mora o sentido.","comoBancaPensa":"Conserva o vocabulário inteiro e altera só as conjunções, apostando que o candidato compare palavras em vez de relações."}},"PT-194":{"cognitivo":{"motivo":"Testar a afirmação de obrigatoriedade de um sinal cuja substituição por vírgula é possível.","palavraCritica":"obrigatório"},"comentario":{"resolucao":"ERRADO. O travessão marca a retomada resumitiva, mas não é obrigatório: a vírgula cumpre a mesma função ('O repentista..., a rezadeira..., o mestre de banda..., todos exercem...'). E a enumeração não ficaria 'sem função sintática': ela continua sendo o aposto enumerativo antecipado, resumido por 'todos'. Trocar o sinal altera o ritmo, não a gramaticalidade.","fundamento":"Pontuação — travessão e vírgula no aposto resumitivo.","macete":"Quase nenhum sinal de pontuação é insubstituível. Desconfie de 'obrigatório' em item de pontuação.","erroComum":"Aceitar a obrigatoriedade por reconhecer que o travessão ali está bem empregado — estar correto não é o mesmo que ser o único possível.","comoBancaPensa":"Parte de um uso legítimo do sinal e sobe o tom para 'obrigatório', que é o degrau falso."}},"PT-195":{"cognitivo":{"motivo":"Cobrar o sentido contextual de uma locução adverbial de modo.","palavraCritica":"cerimônia"},"comentario":{"resolucao":"CERTO. 'Sem cerimônia' opõe-se a ritual formal: os personagens não se apresentam como guardiões oficiais da memória, exercem esse papel na feira, no benzimento, no ensaio da banda — dentro da rotina. O contexto sustenta a leitura de espontaneidade e informalidade que o item propõe.","fundamento":"Semântica — sentido contextual de locução adverbial.","macete":"Locução ambígua se resolve pelo entorno. Leia a frase inteira antes de escolher a acepção.","erroComum":"Ler 'sem cerimônia' como falta de respeito, acepção possível em outros contextos mas incompatível com este.","comoBancaPensa":"Explora uma expressão com duas acepções correntes e deixa o contexto decidir qual vale."}},"PT-196":{"cognitivo":{"motivo":"Testar a substituição da causa apontada pelo texto por outra, de senso comum.","palavraCritica":"decorre"},"comentario":{"resolucao":"ERRADO. A causa que o texto apresenta é o AJUSTE ao ouvinte, ao tempo e à circunstância — um movimento deliberado de adaptação, não uma falha. Tanto assim que o autor chama isso de 'condição de sobrevivência da narrativa'. Falar em falha de memória inverte o juízo do texto, e a urgência do registro escrito não é defendida: o último parágrafo justamente pondera os riscos dele.","fundamento":"Compreensão de texto — identificação da causa; extrapolação.","macete":"Quando o item explica um fenômeno do texto por uma causa que o texto não cita, confira se ele não trocou elogio por defeito.","erroComum":"Aceitar 'falha de memória' por ser a explicação intuitiva para versões divergentes.","comoBancaPensa":"Substitui a causa do texto pela causa que o candidato traz de fora e emenda uma conclusão que o texto contradiz."}},"PT-197":{"cognitivo":{"motivo":"Aferir a leitura da tese enunciada na primeira linha.","palavraCritica":"equivale"},"comentario":{"resolucao":"CERTO. É a afirmação de abertura: 'Publicar estatísticas de criminalidade não é o mesmo que prestar contas'. O texto reconhece que o painel 'cumpre função útil', mas limitada, porque informa o que ocorreu sem explicar por quê nem o que se fez — logo, publicar é condição insuficiente para prestar contas.","fundamento":"Compreensão de texto — identificação da tese.","macete":"Primeira frase de texto expositivo institucional costuma ser a tese. Volte a ela ao julgar cada item.","erroComum":"Marcar ERRADO por entender que o texto desqualifica a divulgação, quando ele apenas a considera insuficiente.","comoBancaPensa":"Item curto e correto que abre o bloco e calibra a leitura do candidato."}},"PT-198":{"cognitivo":{"motivo":"Testar se o candidato distingue 'insuficiente' de 'nocivo'.","palavraCritica":"descontinuados"},"comentario":{"resolucao":"ERRADO. O texto diz que o painel 'cumpre função útil, mas limitada' — reconhece valor e aponta limite. Em nenhum momento propõe descontinuá-lo, nem compara a divulgação parcial com a ausência de divulgação, nem afirma que a primeira seja mais nociva. O item transforma uma ressalva em condenação.","fundamento":"Compreensão de texto — insuficiência × nocividade; extrapolação.","macete":"'Útil, mas limitada' é elogio com ressalva. Item que lê isso como condenação está ampliando.","erroComum":"Deduzir a recusa a partir da crítica, sem notar o reconhecimento explícito de utilidade.","comoBancaPensa":"Enunciado longo que apresenta a extrapolação como conclusão lógica, encadeada com um 'pois' que parece justificá-la."}},"PT-199":{"cognitivo":{"motivo":"Cobrar equivalência entre locuções relativas de valor causal-consecutivo.","palavraCritica":"pela qual"},"comentario":{"resolucao":"CERTO. 'Razão pela qual' e 'motivo por que' são equivalentes: em ambas, o relativo retoma o antecedente e a preposição é exigida pelo nome ('razão por', 'motivo por'). A grafia 'por que', separada e sem acento, é a correta nesse emprego, em que 'que' equivale a 'o qual'.","fundamento":"Sintaxe — pronome relativo precedido de preposição; emprego de por que.","macete":"Se der para trocar por 'pelo qual/pela qual', escreve-se 'por que', separado e sem acento.","erroComum":"Recusar por supor que 'por que' só cabe em pergunta.","comoBancaPensa":"Reescritura correta que passa pelo ponto mais errado da escrita corrente — o emprego dos porquês."}},"PT-200":{"cognitivo":{"motivo":"Cobrar a função do travessão como introdutor de aposto enumerativo.","palavraCritica":"enumeração"},"comentario":{"resolucao":"CERTO. Depois do travessão vêm três especificações do que constitui o critério: 'como se classifica uma ocorrência, em que momento ela entra na estatística, quem revisa o registro'. É aposto enumerativo, e o travessão o anuncia — função que, nesse contexto, os dois-pontos também cumpririam.","fundamento":"Pontuação — travessão introdutor de aposto enumerativo.","macete":"Travessão simples no meio do período costuma anunciar explicação ou lista. Veja o que vem depois dele.","erroComum":"Esperar travessão sempre em par, ignorando o uso simples antes de aposto.","comoBancaPensa":"Item curto e verdadeiro sobre um sinal que o candidato associa apenas a intercalação."}},"PT-201":{"cognitivo":{"motivo":"Cobrar o rastreio de anáfora entre períodos consecutivos.","palavraCritica":"Ela"},"comentario":{"resolucao":"CERTO. O período anterior é 'A transparência que interessa ao controle social é outra'. 'Ela' retoma esse sujeito, com o qual concorda em gênero e número, e mantém a progressão temática: o texto acabara de anunciar que existe outra transparência e passa a caracterizá-la.","fundamento":"Coesão — anáfora pronominal entre períodos.","macete":"Pronome que abre período costuma retomar o sujeito do período anterior. Confira gênero, número e sentido.","erroComum":"Puxar 'Ela' para 'estatística' ou 'ocorrência', substantivos femininos próximos mas de outro período.","comoBancaPensa":"Anáfora correta e verificável, para contrastar com os itens em que o referente é trocado."}},"PT-202":{"cognitivo":{"motivo":"Testar a inversão entre condição e consequência, com alteração da conclusão.","palavraCritica":"Como"},"comentario":{"resolucao":"ERRADO. No original, a ausência dos metadados é a CONDIÇÃO ('sem esses metadados') e a degradação do número em argumento de autoridade é a CONSEQUÊNCIA. A reescritura inverte os papéis — transforma a consequência em causa — e ainda conclui que os metadados seriam dispensáveis, o oposto exato do que o texto defende, já que ele os apresenta como exigência da transparência que interessa.","fundamento":"Sintaxe do período composto — relação condicional × causal; coerência.","macete":"'Sem X, acontece Y' significa que X evita Y. Nunca que Y torna X dispensável.","erroComum":"Julgar apenas a correção gramatical da reescritura, que existe, sem checar se a relação lógica sobreviveu.","comoBancaPensa":"Constrói um período gramaticalmente impecável cuja conclusão contradiz o texto — o erro está no sentido, não na forma."}},"PT-203":{"cognitivo":{"motivo":"Testar a distinção entre subordinada substantiva subjetiva e objetiva direta.","palavraCritica":"exige"},"comentario":{"resolucao":"ERRADO. O sujeito de 'exige' é 'Ela'. A oração 'que o dado venha acompanhado do critério...' completa o sentido do verbo transitivo direto — quem exige, exige ALGUMA COISA —, sendo, portanto, subordinada substantiva OBJETIVA DIRETA. Seria subjetiva se o verbo estivesse sem sujeito expresso, em construções como 'exige-se que...' ou 'é exigido que...'.","fundamento":"Sintaxe — orações subordinadas substantivas subjetiva e objetiva direta.","macete":"Ache primeiro o sujeito do verbo principal. Se ele já existe, a oração que sobra não pode ser sujeito.","erroComum":"Classificar toda substantiva iniciada por 'que' após o verbo como subjetiva.","comoBancaPensa":"Pergunta sobre função de oração DO TEXTO, no formato dos itens de sintaxe da prova real, e explora a confusão mais comum da classificação."}},"PT-204":{"cognitivo":{"motivo":"Testar a transformação de uma cautela pontual em condição absoluta.","palavraCritica":"nenhuma"},"comentario":{"resolucao":"ERRADO. A cautela do texto é específica: são os dados GRANULARES DEMAIS que podem expor vítimas e comprometer investigações. Daí a conclusão de que a abertura 'precisa ser desenhada, e não simplesmente decretada' — isto é, calibrada em seu grau de detalhe, e não suspensa. O item generaliza a ressalva até uma proibição geral, que o texto não formula.","fundamento":"Compreensão de texto — alcance da ressalva; generalização indevida.","macete":"Cautela sobre o GRAU de uma prática não é proibição da prática. Veja se o texto qualificou o objeto ('granulares demais').","erroComum":"Ler 'desenhada' como sinônimo de 'restringida ao máximo'.","comoBancaPensa":"Toma o único parágrafo de ressalva e o converte em regra absoluta, com 'toda e qualquer' e 'nenhuma' reforçando a leitura extrema."}},"PT-205":{"cognitivo":{"motivo":"Apresentar termo absoluto em item VERDADEIRO, porque o texto de fato formula a exigência sem ressalva.","palavraCritica":"todo"},"comentario":{"resolucao":"CERTO. O texto é categórico nesse ponto: 'Ela exige que o dado venha acompanhado do critério que o produziu'. A exigência é apresentada sem exceção, e a frase seguinte reforça que, sem os metadados, o número perde a função de instrumento de verificação. O 'todo' do item reproduz o alcance do original, não o amplia.","fundamento":"Compreensão de texto — fidelidade ao alcance da afirmação.","macete":"Termo absoluto não é sinal de item errado. Aqui o próprio texto é absoluto — confira o texto, não a palavra.","erroComum":"Marcar ERRADO por reflexo ao ver 'todo', sem verificar se o texto autoriza a generalidade.","comoBancaPensa":"É a contraprova do reflexo: quem decide por 'termo absoluto = ERRADO' perde este item, e a banca sabe disso."}},"PT-206":{"cognitivo":{"motivo":"Cobrar sinonímia contextual em par opositivo construído pelo autor.","palavraCritica":"desenhada"},"comentario":{"resolucao":"CERTO. 'Desenhada' está em oposição a 'decretada': o autor contrapõe a abertura que se projeta com cuidado à que se impõe por ato. 'Planejada' preserva exatamente esse traço de elaboração prévia e mantém a oposição intacta, sem prejuízo de concordância ou regência.","fundamento":"Semântica — sinonímia contextual em estrutura opositiva.","macete":"Em par de opostos, o sinônimo bom é o que preserva a oposição. Teste a troca lendo os dois termos juntos.","erroComum":"Recusar por ler 'desenhada' no sentido gráfico, ignorando o emprego figurado que a oposição impõe.","comoBancaPensa":"Substituição legítima cujo julgamento exige perceber a estrutura opositiva, e não só consultar o dicionário."}},"PT-207":{"cognitivo":{"motivo":"Testar a atribuição ao texto de uma finalidade que ele não enuncia.","palavraCritica":"principal finalidade"},"comentario":{"resolucao":"ERRADO. O bairro aparece uma única vez, como exemplo do que um painel informa — 'quantos roubos ocorreram em determinado bairro' —, e não como finalidade da divulgação. O texto trata da diferença entre informar e prestar contas e da necessidade de metadados; comparação entre bairros, avaliação de eficiência e redistribuição de efetivo não são mencionadas nem sugeridas.","fundamento":"Compreensão de texto — exemplo × finalidade; extrapolação.","macete":"Termo citado uma vez como exemplo não vira tese. Volte ao texto e veja em que função a palavra aparece.","erroComum":"Tomar o exemplo do primeiro parágrafo como objetivo do texto por ser o único dado concreto mencionado.","comoBancaPensa":"Constrói uma finalidade plausível para políticas de dados abertos e a atribui ao texto, contando com o repertório externo do candidato."}},"PT-208":{"cognitivo":{"motivo":"Cobrar a leitura de metáfora construída por negação e contraste.","palavraCritica":"chave"},"comentario":{"resolucao":"CERTO. A estrutura 'não é X: é Y' nega o valor material do objeto e afirma outro. 'Chave' é metáfora do que dá acesso, e o texto explicita a que: 'a conta bancária, o benefício, a matrícula'. O documento vale pelo que permite fazer — valor instrumental.","fundamento":"Semântica — metáfora e estrutura de contraste.","macete":"'Não é X: é Y' sempre carrega a tese em Y. O que vem depois dos dois-pontos é o que o autor defende.","erroComum":"Ler 'chave' no sentido literal e recusar o item por não haver fechadura no texto.","comoBancaPensa":"Item curto e correto sobre figura de linguagem explicitada pelo próprio contexto."}},"PT-209":{"cognitivo":{"motivo":"Testar a construção de uma equivalência numérica que o texto não autoriza.","palavraCritica":"exatamente"},"comentario":{"resolucao":"ERRADO. O texto informa duas coisas independentes — quantas carteiras se emitiram (412) e qual a proporção de adultos sem documento (uma em cada oito) — mas nunca a população do município, sem a qual a comparação é impossível. Não há como afirmar equivalência, muito menos que a totalidade foi atendida. O próprio fecho do texto contradiz a suficiência, ao falar do que 'nenhum evento de três dias resolve'.","fundamento":"Compreensão de texto — inferência a partir de dados incompletos.","macete":"Para afirmar proporção, o texto precisa dar o total. Sem denominador, não há conta.","erroComum":"Aceitar a equivalência por ver dois números no mesmo parágrafo e supor que se relacionam.","comoBancaPensa":"Enunciado longo que veste de aritmética uma conclusão que os dados do texto não sustentam."}},"PT-210":{"cognitivo":{"motivo":"Cobrar o desenvolvimento de reduzida de particípio com valor temporal.","palavraCritica":"Encerrado"},"comentario":{"resolucao":"CERTO. A reduzida de particípio 'Encerrado o mutirão' tem valor temporal e se desenvolve em oração iniciada por conjunção temporal com verbo flexionado: 'Depois que o mutirão foi encerrado'. A anterioridade do primeiro fato em relação ao segundo é preservada, e a correção do período também.","fundamento":"Sintaxe — oração subordinada adverbial temporal reduzida de particípio.","macete":"Particípio abrindo período costuma esconder um 'depois que' ou um 'assim que'. Teste os dois.","erroComum":"Ler a reduzida como causal e recusar a temporal.","comoBancaPensa":"Reescritura legítima cujo julgamento exige identificar o valor da reduzida, e não só a forma verbal."}},"PT-211":{"cognitivo":{"motivo":"Testar a troca de conectivo adversativo por conclusivo.","palavraCritica":"portanto"},"comentario":{"resolucao":"ERRADO. 'Contudo' é adversativo: opõe o parágrafo dos números ao que eles não alcançam. 'Portanto' é conclusivo e faria do segundo parágrafo consequência do primeiro, o que inverte a articulação — o autor não conclui a partir dos números, ele os relativiza. A troca altera a relação lógica entre os parágrafos.","fundamento":"Coesão — valor semântico dos conectivos adversativo e conclusivo.","macete":"Adversativo contraria o que veio antes; conclusivo decorre dele. Nunca são intercambiáveis.","erroComum":"Aceitar por ambos ligarem parágrafos e virem entre vírgulas, sem checar a direção da relação.","comoBancaPensa":"Acrescenta uma justificativa que soa razoável ('apenas explicita a conclusão') para encobrir a inversão."}},"PT-212":{"cognitivo":{"motivo":"Cobrar o critério de emprego do ponto e vírgula em coordenadas já pontuadas.","palavraCritica":"havia"},"comentario":{"resolucao":"CERTO. As duas construções são paralelas — 'Havia quem esperasse...' e 'havia mães que traziam...' — e cada uma traz vírgula interna ('tendo atravessado a vida inteira sem ele'; 'cientes de que a próxima oportunidade poderia demorar'). É exatamente a situação em que o ponto e vírgula se prefere à vírgula: marcar a fronteira principal quando a secundária já está ocupada.","fundamento":"Pontuação — ponto e vírgula entre coordenadas com pontuação interna.","macete":"Se as partes já têm vírgula dentro, a divisão entre elas sobe para ponto e vírgula.","erroComum":"Julgar o ponto e vírgula excessivo por caber ali, gramaticalmente, também a vírgula.","comoBancaPensa":"Afirmação curta e verdadeira que descreve o critério, não apenas o resultado."}},"PT-213":{"cognitivo":{"motivo":"Testar restrição inventada sobre o que os dois-pontos podem anunciar.","palavraCritica":"nunca"},"comentario":{"resolucao":"ERRADO em duas frentes. O travessão não separa termos de mesma função: anuncia a explicitação da 'pergunta' mencionada antes, funcionando como introdutor de aposto oracional. E os dois-pontos anunciam perfeitamente orações — 'Ficou a pergunta que nenhum evento resolve: como transformar em rotina...' é construção correta. Não há a vedação que o item afirma.","fundamento":"Pontuação — travessão e dois-pontos antes de aposto oracional.","macete":"Dois-pontos anunciam explicação, citação, enumeração ou consequência. Não se importam se o que vem é termo ou oração.","erroComum":"Aceitar a regra por ela vir acompanhada de uma justificativa de aparência técnica.","comoBancaPensa":"Combina uma descrição sintática errada com uma vedação inexistente, ambas apresentadas com segurança."}},"PT-214":{"cognitivo":{"motivo":"Cobrar o rastreio de anáfora entre parágrafos.","palavraCritica":"ele"},"comentario":{"resolucao":"CERTO. O primeiro parágrafo encerra com 'não possuía documento de identidade', e é esse o antecedente masculino singular que 'ele' retoma. A leitura confirma-se pelo sentido: quem esperava por um documento aos sessenta anos atravessou a vida sem o documento.","fundamento":"Coesão — anáfora pronominal com antecedente em parágrafo anterior.","macete":"Pronome no começo do parágrafo costuma buscar o antecedente no fim do parágrafo anterior. Releia a última linha.","erroComum":"Procurar o antecedente apenas dentro do mesmo período.","comoBancaPensa":"Anáfora correta e a alguma distância, para medir se o candidato lê o texto como unidade."}},"PT-215":{"cognitivo":{"motivo":"Testar a classificação do complemento de 'haver' existencial, erro clássico de concordância.","palavraCritica":"havia"},"comentario":{"resolucao":"ERRADO. 'Haver' no sentido de existir é impessoal: não tem sujeito, e por isso permanece na 3ª pessoa do singular ainda que o complemento esteja no plural. 'Mães' é OBJETO DIRETO. É justamente por isso que se escreve 'havia mães' e nunca 'haviam mães' — se 'mães' fosse sujeito, o verbo concordaria.","fundamento":"Sintaxe — verbo haver impessoal; objeto direto.","macete":"Se trocar 'haver' por 'existir' o verbo vai ao plural, o termo é sujeito de 'existir' mas objeto de 'haver'. O teste da concordância entrega.","erroComum":"Chamar de sujeito o termo que vem depois de 'havia' por analogia com 'existiam mães'.","comoBancaPensa":"Pergunta pela função de um termo do texto e explora o ponto de concordância mais errado da língua escrita."}},"PT-216":{"cognitivo":{"motivo":"Apresentar termo absoluto em item VERDADEIRO, reproduzindo a categoria do próprio texto.","palavraCritica":"nenhum"},"comentario":{"resolucao":"CERTO. A afirmação está literalmente no texto: 'Ficou a pergunta que nenhum evento de três dias resolve'. O item não amplia nem restringe o alcance — apenas reproduz a negativa absoluta que o autor formulou.","fundamento":"Compreensão de texto — fidelidade ao alcance da afirmação.","macete":"Termo absoluto no item não é sinal de erro. Se o texto também é absoluto, o item está certo.","erroComum":"Marcar ERRADO por reflexo ao ver 'nenhum'.","comoBancaPensa":"Contraprova direta do reflexo de termo absoluto — item curto, verdadeiro e categórico."}},"PT-217":{"cognitivo":{"motivo":"Testar a transformação de uma ressalva sobre continuidade em crítica à iniciativa.","palavraCritica":"desviam recursos"},"comentario":{"resolucao":"ERRADO. O texto não critica o mutirão nem fala em desvio de recursos: registra o que ele produziu (412 carteiras, com relato do que significavam para as pessoas na fila) e conclui apontando o desafio da continuidade — 'como transformar em rotina aquilo que ainda se organiza como exceção'. Reconhecer que o evento é insuficiente para o problema não é negar seus resultados.","fundamento":"Compreensão de texto — ressalva sobre continuidade × crítica à iniciativa.","macete":"'Isto é pouco para o problema' é diferente de 'isto não deveria ter sido feito'. Veja se o texto negou o resultado.","erroComum":"Ler o fecho melancólico como condenação da iniciativa.","comoBancaPensa":"Parte de um dado verdadeiro (o texto termina com uma pergunta em aberto) e inventa a motivação e o juízo do autor."}},"PT-218":{"cognitivo":{"motivo":"Cobrar equivalência entre locução adverbial e advérbio em -mente.","palavraCritica":"de uma vez"},"comentario":{"resolucao":"CERTO. No contexto, 'de uma vez' indica que os três filhos eram trazidos na mesma ocasião, e 'simultaneamente' expressa a mesma simultaneidade. A troca mantém a função adverbial de modo/tempo e não altera a regência do verbo 'trazer'.","fundamento":"Semântica — equivalência entre locução adverbial e advérbio.","macete":"Locução adverbial quase sempre tem advérbio equivalente. Confira se o contexto admite a mesma acepção.","erroComum":"Ler 'de uma vez' com o sentido de 'definitivamente', acepção existente mas incompatível aqui.","comoBancaPensa":"Explora expressão com duas acepções e deixa o contexto resolver, formato recorrente em substituição vocabular."}},"PT-219":{"cognitivo":{"motivo":"Testar a inversão da relação entre dado numérico e relato.","palavraCritica":"acessória"},"comentario":{"resolucao":"ERRADO. O parágrafo abre com o oposto: 'Os números, contudo, dizem pouco sobre o que se via nas filas'. O relato não é ilustração do que a estatística já mostrava — ele existe justamente para dizer o que a estatística NÃO alcança. O item troca a hierarquia entre os dois tipos de informação.","fundamento":"Compreensão de texto — relação entre dado quantitativo e relato qualitativo.","macete":"'Dizem pouco sobre' é limitação, não confirmação. O que vem depois supre a falta, não a ilustra.","erroComum":"Aceitar por reconhecer que o texto de fato apresenta números e depois relatos, sem julgar a relação afirmada entre eles.","comoBancaPensa":"Descreve corretamente a sequência do parágrafo e inverte a função de cada parte."}},"PT-220":{"cognitivo":{"motivo":"Aferir a leitura da tese enunciada na primeira linha.","palavraCritica":"resultado"},"comentario":{"resolucao":"CERTO. O texto abre exatamente assim: o atendimento 'não é uma etapa protocolar do inquérito; é parte do próprio resultado que se espera da investigação'. O item reproduz a afirmação sem ampliá-la.","fundamento":"Compreensão de texto — identificação da tese.","macete":"Estrutura 'não é A; é B' entrega a tese em B.","erroComum":"Confundir 'parte do resultado' com 'etapa do procedimento', que é justamente o que o texto nega.","comoBancaPensa":"Item curto e correto de abertura, para calibrar a leitura do bloco."}},"PT-221":{"cognitivo":{"motivo":"Testar a inversão da afirmação expressa sobre a natureza dos gestos.","palavraCritica":"infrações"},"comentario":{"resolucao":"ERRADO. O texto afirma o contrário, e de forma explícita: 'Nenhum desses gestos figura como ilegalidade, e é exatamente por isso que exigem atenção deliberada'. O detalhamento serve para tornar visível o que escapa ao controle formal — não para embasar punição.","fundamento":"Compreensão de texto — leitura de afirmação expressa.","macete":"Quando o item afirma o oposto de uma frase literal do texto, procure a frase antes de raciocinar.","erroComum":"Supor punição por associação com o vocabulário institucional do texto.","comoBancaPensa":"Enunciado longo que constrói uma finalidade plausível para a enumeração e ignora a frase que a contradiz."}},"PT-222":{"cognitivo":{"motivo":"Cobrar a identificação do referente do pronome oblíquo em posição de ênclise ao infinitivo.","palavraCritica":"-la"},"comentario":{"resolucao":"CERTO. O pronome '-la' retoma 'A revitimização', sujeito do parágrafo anterior. Explicitá-lo desfaz a ênclise sem alterar sentido nem correção: 'combater a revitimização' mantém a transitividade direta do verbo. A substituição apenas troca a forma pronominal pelo sintagma que ela representa.","fundamento":"Coesão e sintaxe — anáfora pronominal; ênclise ao infinitivo.","macete":"Para achar o referente do pronome em '-lo/-la', tente substituir pelo substantivo e ver se a frase continua fazendo sentido.","erroComum":"Puxar '-la' para 'lei nova', termo mais próximo mas posterior ao pronome.","comoBancaPensa":"Reescritura correta que exige rastrear o antecedente através da fronteira de parágrafo."}},"PT-223":{"cognitivo":{"motivo":"Testar o deslocamento do advérbio de exclusão dentro da negação.","palavraCritica":"apenas"},"comentario":{"resolucao":"ERRADO. 'Não depende APENAS de lei nova' admite que a lei conta, apenas não sozinha. A reescritura exclui a lei do conjunto de fatores e restringe a dependência às três providências, o que o texto não afirma — ele as apresenta como o que ainda falta, não como substitutas da norma.","fundamento":"Semântica — escopo da negação e posição do advérbio de exclusão.","macete":"'Não só X' inclui X. 'Não X, mas só Y' exclui X. A diferença cabe numa palavra e muda tudo.","erroComum":"Aceitar por a reescritura listar corretamente as três providências do texto.","comoBancaPensa":"Mantém fiel a parte fácil de conferir (a lista) e altera a relação que ninguém volta para checar."}},"PT-224":{"cognitivo":{"motivo":"Cobrar a leitura do ponto e vírgula como marcador de contraste entre coordenadas.","palavraCritica":"coordenadas"},"comentario":{"resolucao":"CERTO. A primeira oração nega uma definição ('não é uma etapa protocolar do inquérito') e a segunda afirma outra ('é parte do próprio resultado'). São coordenadas assindéticas em relação de contraste, e o ponto e vírgula marca essa oposição com pausa mais forte que a vírgula, sem exigir conjunção.","fundamento":"Pontuação — ponto e vírgula entre coordenadas assindéticas adversativas.","macete":"Ponto e vírgula entre 'não é X' e 'é Y' funciona como um 'mas' silencioso.","erroComum":"Exigir conjunção adversativa para reconhecer a oposição.","comoBancaPensa":"Item curto e verdadeiro sobre função de pontuação, área de desconfiança do candidato."}},"PT-225":{"cognitivo":{"motivo":"Testar a afirmação de facultatividade de vírgulas obrigatórias em enumeração.","palavraCritica":"suprimidas"},"comentario":{"resolucao":"ERRADO. Em enumeração de termos de mesma função sintática sem conectivo, a vírgula é obrigatória: é ela que marca a separação entre os itens. Suprimi-la produziria uma sequência ilegível e agramatical. Que a aditiva esteja subentendida é justamente o motivo da vírgula, não da sua dispensa.","fundamento":"Pontuação — vírgula em enumeração assindética.","macete":"Sem 'e' entre os itens, a vírgula não é escolha: é o que separa um item do outro.","erroComum":"Confundir 'facultativa' com 'não obrigatória em toda posição' — a última vírgula, antes do 'e', é que costuma ser facultativa.","comoBancaPensa":"Usa uma observação verdadeira (a aditiva está subentendida) para justificar uma conclusão falsa sobre a pontuação."}},"PT-226":{"cognitivo":{"motivo":"Testar o rastreio de ordinal dentro de uma dupla anunciada no parágrafo anterior.","palavraCritica":"segunda"},"comentario":{"resolucao":"ERRADO. O texto anuncia 'uma expectativa dupla' e a desdobra na ordem: primeiro, 'a de que o fato seja apurado'; segundo, 'a de que sua narrativa seja recebida sem que ela precise justificar-se'. A SEGUNDA é o acolhimento da narrativa, não a apuração — que é justamente a primeira. O item troca as duas.","fundamento":"Coesão — anáfora com numeral ordinal; ordem de menção.","macete":"Quando o texto anuncia 'dupla' e lista, conte na ordem em que aparecem. O ordinal é literal.","erroComum":"Associar 'segunda' à ideia mais desenvolvida no texto, e não à ordem de menção.","comoBancaPensa":"Aposta em que o candidato lembre do conteúdo do parágrafo sem conferir a ordem das duas expectativas."}},"PT-227":{"cognitivo":{"motivo":"Cobrar a distinção entre substantiva completiva nominal e objetiva direta.","palavraCritica":"a de que"},"comentario":{"resolucao":"CERTO. O 'a' é pronome demonstrativo que retoma 'expectativa', e a oração 'que o fato seja apurado' completa o sentido desse nome — expectativa DE algo. Trata-se de oração subordinada substantiva completiva nominal, cuja função é a de complemento nominal, exigida pela regência do substantivo abstrato.","fundamento":"Sintaxe — oração subordinada substantiva completiva nominal.","macete":"Nome abstrato + preposição + 'que' = completiva nominal. Verbo + 'que' = objetiva direta.","erroComum":"Classificar como objetiva direta por haver 'que' introduzindo a oração.","comoBancaPensa":"Pergunta pela função de uma oração DO TEXTO, no formato dos itens de sintaxe da prova real."}},"PT-228":{"cognitivo":{"motivo":"Cobrar a distinção entre presença de exemplo e predominância tipológica.","palavraCritica":"predominantemente"},"comentario":{"resolucao":"CERTO. Os exemplos ('a pergunta repetida pela quinta vez', 'o balcão', 'o olhar') não constituem narrativa: não há personagens, sucessão de eventos nem progressão temporal. Servem de ilustração a uma tese defendida ao longo do texto, que se organiza como dissertação — problema, caracterização e encaminhamento.","fundamento":"Tipologia textual — dissertação com sequências ilustrativas.","macete":"Exemplo não faz narrativa. Narrativa pede tempo, personagem e mudança de estado.","erroComum":"Classificar como narrativo por causa das cenas descritas.","comoBancaPensa":"Constrói a dúvida ('embora apresente exemplos') e testa se o candidato sabe o que define predominância."}},"PT-229":{"cognitivo":{"motivo":"Cobrar equivalência entre conectivos conclusivos.","palavraCritica":"portanto"},"comentario":{"resolucao":"CERTO. 'Portanto' e 'por conseguinte' são conclusivos equivalentes: ambos apresentam o que segue como decorrência do que veio antes. A posição intercalada entre vírgulas é a mesma para os dois, e a correção do período se mantém.","fundamento":"Coesão — conectivos conclusivos.","macete":"Família dos conclusivos: portanto, logo, pois (posposto), por conseguinte, por isso. São permutáveis, com ajuste de registro.","erroComum":"Recusar por 'por conseguinte' soar mais formal, confundindo registro com sentido.","comoBancaPensa":"Substituição legítima entre conectivos da mesma classe, para punir a recusa automática."}},"PT-230":{"cognitivo":{"motivo":"Testar a inversão da afirmação sobre a autonomia das unidades.","palavraCritica":"iniciativa própria"},"comentario":{"resolucao":"ERRADO. O texto encerra dizendo o oposto: as três providências 'estão ao alcance de qualquer unidade que decida adotá-las'. São apresentadas justamente como o que não depende de lei nova. O item inverte a conclusão e ainda distorce o argumento, transformando 'não depende apenas de lei' em 'a lei é insuficiente e precisa ser alterada antes'.","fundamento":"Compreensão de texto — leitura da conclusão.","macete":"A última frase de texto dissertativo costuma trazer o encaminhamento. Leia-a antes de julgar qualquer item sobre a conclusão.","erroComum":"Aceitar por reconhecer a menção à insuficiência da lei, sem conferir o que o texto propõe em seguida.","comoBancaPensa":"Enunciado longo cuja falsidade está exatamente na frase final do texto — a que o candidato cansado já não relê."}},"PT-231":{"cognitivo":{"motivo":"Cobrar o sentido contextual de adjetivo em posição-chave do argumento.","palavraCritica":"deliberada"},"comentario":{"resolucao":"CERTO. O adjetivo qualifica a atenção necessária justamente porque os gestos descritos não são ilegalidades — não sendo capturados pelo controle formal, exigem esforço consciente e planejado para serem percebidos e corrigidos. 'Deliberada' opõe-se a automática ou casual.","fundamento":"Semântica — sentido contextual do adjetivo.","macete":"Adjetivo em frase de fecho de parágrafo costuma condensar o argumento. Pergunte a que ele se opõe.","erroComum":"Ler 'deliberada' como 'demorada' ou 'minuciosa', que não é a acepção.","comoBancaPensa":"Testa vocabulário de registro formal em posição argumentativamente decisiva."}},"PT-232":{"cognitivo":{"motivo":"Cobrar a leitura da metáfora que estrutura o texto inteiro.","palavraCritica":"relógio"},"comentario":{"resolucao":"CERTO. A metáfora é explicitada logo em seguida: 'É por ele que se sabe quando plantar, quando a balsa atravessa, quando convém recolher a rede'. Os três 'quando' mostram o rio funcionando como marcador temporal, e o fecho do texto retoma a imagem ao falar do 'modo como as pessoas medem o tempo'.","fundamento":"Semântica — metáfora estruturante e sua retomada.","macete":"Metáfora repetida no fim do texto é estruturante. Ela costuma conter a tese.","erroComum":"Tratar 'relógio' como comparação decorativa e não como chave do argumento.","comoBancaPensa":"Item curto e correto sobre a imagem central, que o texto explica logo depois de propor."}},"PT-233":{"cognitivo":{"motivo":"Testar a conversão de uma ponderação explícita em condenação.","palavraCritica":"superam"},"comentario":{"resolucao":"ERRADO. O texto antecipa e afasta essa leitura: 'Não se trata de recusar a barragem, que trouxe energia e emprego'. Ele reconhece os benefícios e pede reconhecimento do custo — 'toda obra que altera um rio altera também o modo como as pessoas medem o tempo'. Em nenhum momento compara magnitudes nem propõe desativação.","fundamento":"Compreensão de texto — ponderação × condenação; extrapolação.","macete":"Quando o texto diz 'não se trata de recusar X', qualquer item que o faça recusar X está errado.","erroComum":"Ler o tom nostálgico do segundo parágrafo como posição contrária à obra.","comoBancaPensa":"Enunciado longo que ignora a frase em que o autor já se defendeu exatamente dessa leitura."}},"PT-234":{"cognitivo":{"motivo":"Cobrar o reconhecimento da construção clivada e sua desmontagem.","palavraCritica":"É por ele que"},"comentario":{"resolucao":"CERTO. 'É... que' é construção clivada, de realce: destaca o termo entre os dois elementos sem alterar o conteúdo proposicional. Desfeita a clivagem, resta 'Sabe-se por ele quando plantar', com a mesma informação. Perde-se a ênfase, que é recurso estilístico, não sentido — e o item pede manutenção de sentido, não de expressividade.","fundamento":"Sintaxe — construção clivada de realce.","macete":"Se dá para apagar 'é' e 'que' e a frase continua completa, era realce.","erroComum":"Recusar por perceber a perda de ênfase e tratá-la como mudança de sentido.","comoBancaPensa":"Distingue quem entende realce sintático de quem decora que 'toda alteração muda algo'."}},"PT-235":{"cognitivo":{"motivo":"Testar a conversão de adjetiva explicativa em causal.","palavraCritica":"explicativa"},"comentario":{"resolucao":"ERRADO. A adjetiva explicativa acrescenta informação sobre a barragem sem estabelecer relação de causa com a oração principal. Ao transformá-la em causal, a reescritura passa a afirmar que os benefícios são A RAZÃO de não se recusar a obra — argumento que o texto não constrói: ele reconhece os benefícios ao mesmo tempo em que sustenta a existência de um custo. Explicar não é justificar.","fundamento":"Sintaxe do período composto — oração adjetiva explicativa × subordinada adverbial causal.","macete":"Adjetiva explicativa descreve o antecedente. Causal explica o fato da principal. São camadas diferentes.","erroComum":"Aceitar por ambas virem após vírgula e acrescentarem informação.","comoBancaPensa":"Oferece uma justificativa gramatical de aparência sofisticada para uma equivalência que não existe."}},"PT-236":{"cognitivo":{"motivo":"Cobrar o papel da vírgula na distinção entre adjetiva restritiva e explicativa.","palavraCritica":"vírgula"},"comentario":{"resolucao":"CERTO. A vírgula é o sinal que distingue as duas: sem ela, a oração restringiria o antecedente, sugerindo que haveria barragens que não trouxeram energia e emprego. Com ela, a oração apenas acrescenta informação sobre a barragem já identificada — leitura coerente com o texto, que trata de uma obra determinada.","fundamento":"Pontuação e sintaxe — oração adjetiva restritiva × explicativa.","macete":"Vírgula antes de 'que' abre parêntese: o que vem é acréscimo, não filtro.","erroComum":"Tratar a vírgula como pausa de leitura, sem função sintática.","comoBancaPensa":"Item curto e verdadeiro sobre a distinção que a banca mais cobra em adjetivas."}},"PT-237":{"cognitivo":{"motivo":"Cobrar a vírgula como marca de zeugma.","palavraCritica":"vírgula"},"comentario":{"resolucao":"CERTO. O período completo seria 'os mais novos contam o ano pelo contracheque'. A locução verbal foi omitida por já ter aparecido na oração anterior ('Os mais velhos ainda contam o ano pelas águas'), e a vírgula marca essa elipse — recurso conhecido como zeugma.","fundamento":"Pontuação — vírgula em elipse verbal (zeugma).","macete":"Vírgula sozinha no meio de estrutura paralela quase sempre esconde um verbo repetido.","erroComum":"Considerar a construção incompleta ou incorreta por faltar verbo explícito.","comoBancaPensa":"Testa se o candidato reconhece a elipse em vez de tratar a frase como fragmento."}},"PT-238":{"cognitivo":{"motivo":"Cobrar o rastreio da anáfora que sustenta a metáfora do texto.","palavraCritica":"ele"},"comentario":{"resolucao":"CERTO. O período anterior afirma que 'o rio não é paisagem: é relógio', e 'ele' retoma esse mesmo referente. A leitura confirma-se pelo conteúdo: é pelo rio que se sabe quando plantar, quando a balsa atravessa e quando recolher a rede.","fundamento":"Coesão — anáfora pronominal.","macete":"Pronome logo após definição enfática retoma o termo definido.","erroComum":"Puxar 'ele' para 'relógio', que é predicativo e não referente autônomo.","comoBancaPensa":"Anáfora simples que serve de contraponto aos itens em que o referente é trocado."}},"PT-239":{"cognitivo":{"motivo":"Testar a classificação de agente da passiva em oração reduzida encaixada.","palavraCritica":"regulada"},"comentario":{"resolucao":"ERRADO. 'Por barragens' não se liga a 'desfez': liga-se ao particípio 'regulada', dentro do sintagma que forma o sujeito ('A vazão regulada por barragens'). É agente da passiva da forma participial, e não objeto indireto — até porque 'desfazer' é transitivo direto, tendo por objeto 'a cheia previsível'.","fundamento":"Sintaxe — agente da passiva; transitividade verbal.","macete":"Ache primeiro o núcleo do sujeito. O que está preso a ele não pode ser complemento do verbo principal.","erroComum":"Ligar todo termo preposicionado ao verbo mais próximo, sem verificar a que núcleo ele pertence.","comoBancaPensa":"Pergunta pela função de um termo do texto, explorando a sobreposição de estruturas dentro do mesmo período."}},"PT-240":{"cognitivo":{"motivo":"Testar a troca dos sujeitos numa oposição construída por elipse.","palavraCritica":"ao passo que"},"comentario":{"resolucao":"ERRADO. O texto diz o inverso: 'Os mais velhos ainda contam o ano pelas águas; os mais novos, pelo contracheque'. São os VELHOS que mantêm a referência do rio e os NOVOS que se orientam pelo salário. O item troca os dois grupos e ainda inventa a explicação da adaptação econômica.","fundamento":"Compreensão de texto — atribuição de característica ao sujeito correto.","macete":"Em oposição entre dois grupos, marque quem é quem antes de julgar. A troca é a armadilha mais barata que existe.","erroComum":"Ler rápido e reter apenas que há contraste entre gerações, sem fixar a direção dele.","comoBancaPensa":"Preserva a estrutura de contraste do texto e inverte os termos — o candidato reconhece a forma e supõe o conteúdo."}},"PT-241":{"cognitivo":{"motivo":"Cobrar equivalência entre verbos de ligação de mudança de estado.","palavraCritica":"virou"},"comentario":{"resolucao":"CERTO. 'Virar' e 'tornar-se' funcionam como verbos de ligação que indicam mudança de estado, e ambos admitem predicativo do sujeito sem preposição. A troca eleva o registro, mas mantém a estrutura sintática e o sentido de transformação.","fundamento":"Sintaxe — verbos de ligação de mudança de estado; predicativo do sujeito.","macete":"Ser, estar, ficar, permanecer, parecer, tornar-se, virar: todos ligam sujeito a predicativo.","erroComum":"Recusar por 'virar' ser coloquial, confundindo registro com correção.","comoBancaPensa":"Substituição correta que testa se o candidato distingue nível de linguagem de erro gramatical."}},"PT-242":{"cognitivo":{"motivo":"Apresentar termo absoluto em item VERDADEIRO, por reprodução literal da generalização do autor.","palavraCritica":"toda"},"comentario":{"resolucao":"CERTO. É a frase final do texto, reproduzida sem alteração de alcance: 'toda obra que altera um rio altera também o modo como as pessoas medem o tempo'. A generalização é do autor, e o item apenas a repete.","fundamento":"Compreensão de texto — fidelidade ao alcance da afirmação.","macete":"Antes de reagir ao 'toda', procure a frase no texto. Se o autor generalizou, o item pode generalizar.","erroComum":"Marcar ERRADO por reflexo diante do quantificador universal.","comoBancaPensa":"Terceira contraprova do reflexo neste conjunto de lotes — a banca cobra literalidade, e literalidade às vezes é absoluta."}},"PT-243":{"cognitivo":{"motivo":"Testar a substituição da causa apontada pelo texto por outra, plausível mas ausente.","palavraCritica":"assoreamento"},"comentario":{"resolucao":"ERRADO. A causa que o texto indica é uma só e está explícita: 'A vazão regulada por barragens desfez a cheia previsível'. Assoreamento, ocupação de margens e crescimento urbano não aparecem no texto — são acrescentados pelo item, que aproveita o repertório do candidato sobre problemas de rios.","fundamento":"Compreensão de texto — identificação da causa; informação externa ao texto.","macete":"Se a causa do item não está escrita no texto, ela não é do texto — por mais verdadeira que seja no mundo.","erroComum":"Aceitar por conhecer o fenômeno do assoreamento e considerá-lo compatível com o que se lê.","comoBancaPensa":"Traz uma explicação correta na realidade e ausente no texto, medindo se o candidato responde ao que leu."}},"PT-244":{"cognitivo":{"motivo":"Aferir a leitura da premissa enunciada na primeira frase.","palavraCritica":"isoladamente"},"comentario":{"resolucao":"CERTO. O texto abre afirmando que 'pessoas, telefones, veículos e endereços não existem isoladamente, e é a ligação entre eles que revela a estrutura de um grupo criminoso'. O item reformula essa premissa sem alterá-la.","fundamento":"Compreensão de texto — identificação da premissa.","macete":"Construção 'é X que' destaca o termo. O que está entre 'é' e 'que' costuma ser a chave da frase.","erroComum":"Marcar ERRADO por considerar que os elementos isolados também têm valor probatório — o que é verdade no mundo, mas não é o que o texto afirma.","comoBancaPensa":"Item curto e correto de abertura, com estrutura clivada que o candidato precisa desmontar."}},"PT-245":{"cognitivo":{"motivo":"Testar a emenda de conclusão falsa a uma premissa verdadeira do texto.","palavraCritica":"dispensando"},"comentario":{"resolucao":"ERRADO. A primeira parte é fiel ao texto: o grafo é mesmo apresentado como 'objeto verificável, que outro analista pode reproduzir'. Mas a conclusão contraria a regra que o próprio texto enuncia como orientadora do trabalho sério: 'o desenho não substitui a prova'. O grafo organiza indícios e sugere onde procurar — não dispensa prova.","fundamento":"Compreensão de texto — verdade parcial com conclusão emendada.","macete":"Item que começa parafraseando bem o texto merece leitura mais atenta do fim, não menos.","erroComum":"Validar o item pela premissa correta e não conferir a conclusão.","comoBancaPensa":"Padrão verdade + falso emendado, com a falsidade colocada depois de duas orações fiéis ao texto."}},"PT-246":{"cognitivo":{"motivo":"Cobrar equivalência entre locuções de valor condicional negativo.","palavraCritica":"do contrário"},"comentario":{"resolucao":"CERTO. 'Do contrário' e 'caso contrário' são equivalentes e exprimem a mesma condição negativa: se o analista NÃO qualificar a aresta, o grafo apenas confirma a hipótese inicial. Ambas as formas são registradas e mantêm a pontuação e a estrutura do período.","fundamento":"Coesão — locuções de valor condicional.","macete":"'Do contrário', 'caso contrário' e 'senão' cumprem a mesma função: retomam a hipótese negada.","erroComum":"Supor que uma das formas é incorreta por menos frequente na escrita informal.","comoBancaPensa":"Substituição legítima entre locuções sinônimas, para punir a recusa automática."}},"PT-247":{"cognitivo":{"motivo":"Testar acréscimo de orientação prática que o texto não formula.","palavraCritica":"descartá-lo"},"comentario":{"resolucao":"ERRADO. O deslocamento de 'necessariamente' é inofensivo, mas a reescritura acrescenta uma instrução ausente: o texto não manda descartar vínculos, e sim QUALIFICAR a aresta — 'Cabe ao analista qualificar a aresta, e não apenas contá-la'. Sugerir descarte inverte a orientação, que é de análise, não de exclusão.","fundamento":"Compreensão e sintaxe — acréscimo de conteúdo em proposta de reescritura.","macete":"Reescritura que fica MAIOR que o original quase sempre acrescentou algo. Compare o que sobrou de novo.","erroComum":"Concentrar-se na posição de 'necessariamente' e não notar a oração acrescentada no fim.","comoBancaPensa":"Coloca a alteração real depois de uma mudança inofensiva, contando com o candidato parar de ler na primeira."}},"PT-248":{"cognitivo":{"motivo":"Cobrar a função dos dois-pontos como anunciador de conteúdo.","palavraCritica":"explicitação"},"comentario":{"resolucao":"CERTO. A oração anterior anuncia que existe 'uma ideia simples' sem dizer qual; o que vem depois dos dois-pontos é justamente o enunciado dessa ideia — que os elementos não existem isoladamente e que a ligação entre eles revela a estrutura do grupo. É o uso explicativo do sinal.","fundamento":"Pontuação — dois-pontos de valor explicativo.","macete":"Quando a frase promete algo ('uma ideia', 'um problema', 'uma regra'), os dois-pontos entregam.","erroComum":"Restringir os dois-pontos a citação e enumeração.","comoBancaPensa":"Item curto e verdadeiro sobre pontuação, no formato que a banca usa para abrir blocos."}},"PT-249":{"cognitivo":{"motivo":"Cobrar o rastreio de anáfora por sintagma demonstrativo.","palavraCritica":"essa"},"comentario":{"resolucao":"CERTO. O período anterior estabelece que 'é a ligação entre eles que revela a estrutura', sendo 'eles' os quatro tipos de elemento listados. 'Essa ligação' retoma exatamente esse referente, e o demonstrativo 'essa' marca a anáfora — remete ao que já foi dito, não ao que virá.","fundamento":"Coesão — anáfora por sintagma demonstrativo.","macete":"'Esse/essa' olha para trás; 'este/esta' costuma olhar para a frente. O demonstrativo indica a direção.","erroComum":"Restringir o referente a apenas um dos elementos listados.","comoBancaPensa":"Anáfora correta que exige recuperar uma enumeração inteira, e não um substantivo isolado."}},"PT-250":{"cognitivo":{"motivo":"Testar a classificação do valor semântico de um conectivo conclusivo.","palavraCritica":"Daí"},"comentario":{"resolucao":"ERRADO. 'Daí' é conclusivo, equivalente a 'por isso' ou 'em razão disso': a regra do último parágrafo DECORRE das limitações expostas antes, não se opõe a elas. Justamente porque um vínculo frequente pode não ser relevante é que se enuncia a regra de que o desenho não substitui a prova.","fundamento":"Coesão — valor semântico do conectivo conclusivo.","macete":"Troque o conectivo por 'por isso' e veja se a frase continua fazendo sentido. Se continuar, é conclusivo.","erroComum":"Ler 'daí' como marcador de contraste por iniciar parágrafo depois de uma ressalva.","comoBancaPensa":"Explora um conectivo de uso corrente cuja classificação formal raramente é revisada."}},"PT-251":{"cognitivo":{"motivo":"Cobrar o valor semântico de reduzida de particípio anteposta.","palavraCritica":"Representada"},"comentario":{"resolucao":"CERTO. A reduzida equivale a 'Se for representada em grafo' ou 'Quando representada em grafo': é a representação gráfica que faz a ligação deixar de ser intuição. O valor é condicional-temporal, e a leitura condicional é a que o argumento do texto sustenta, já que o parágrafo trata do que a representação acrescenta ao método.","fundamento":"Sintaxe — oração subordinada adverbial reduzida de particípio; valor condicional.","macete":"Reduzida de particípio anteposta: teste 'se', 'quando' e 'depois que'. A que fizer sentido no argumento é o valor.","erroComum":"Classificar como causal, valor que a reduzida também admite mas que aqui inverte a lógica do parágrafo.","comoBancaPensa":"Pergunta pelo valor de uma oração DO TEXTO, no formato dos itens de sintaxe da prova real."}},"PT-252":{"cognitivo":{"motivo":"Testar a conversão de uma advertência do texto em finalidade do método.","palavraCritica":"respaldo científico"},"comentario":{"resolucao":"ERRADO. O texto apresenta exatamente isso como o RISCO a evitar, não como utilidade: sem qualificar a aresta, 'o grafo apenas confirma, com aparência científica, a hipótese com que se começou'. A utilidade declarada é outra — organizar indícios, sugerir onde procurar e mostrar o que ainda falta.","fundamento":"Compreensão de texto — advertência × finalidade.","macete":"Quando o item descreve algo que o texto apresenta com ironia ou ressalva ('aparência científica'), desconfie: costuma ser o defeito, não a virtude.","erroComum":"Reconhecer a frase do texto e não notar que ela vem precedida de 'do contrário'.","comoBancaPensa":"Reaproveita quase literalmente uma frase do texto, suprimindo o conectivo que a marca como hipótese negativa."}},"PT-253":{"cognitivo":{"motivo":"Cobrar sinonímia contextual entre verbos de mesma regência.","palavraCritica":"enunciar"},"comentario":{"resolucao":"CERTO. No contexto, 'enunciar' significa declarar, tornar expresso — sentido que 'explicitar' recobre integralmente. Ambos são transitivos diretos e mantêm a mesma relação com 'limites', preservando a estrutura da oração e a correção do período.","fundamento":"Semântica e regência — sinonímia contextual entre verbos transitivos diretos.","macete":"Antes de aprovar troca de verbo, confira dois pontos: sentido no contexto e regência. Se os dois batem, a troca vale.","erroComum":"Recusar por associar 'enunciar' apenas ao ato de formular teoria ou lei.","comoBancaPensa":"Substituição legítima que exige avaliar sentido e regência juntos."}},"PT-254":{"cognitivo":{"motivo":"Cobrar a função argumentativa do exemplo.","palavraCritica":"exemplo"},"comentario":{"resolucao":"CERTO. O exemplo é introduzido logo após a afirmação de que 'um vínculo frequente não é necessariamente um vínculo relevante' e a ilustra: compartilhar endereço é vínculo verificável e frequente, mas pode não ter propósito comum. A função do exemplo é sustentar exatamente essa distinção.","fundamento":"Compreensão de texto — função argumentativa do exemplo.","macete":"Exemplo colado a uma afirmação existe para prová-la. Leia a frase imediatamente anterior.","erroComum":"Ler o exemplo como observação isolada sobre vizinhança.","comoBancaPensa":"Item curto e correto sobre a articulação entre tese e exemplo."}},"PT-255":{"cognitivo":{"motivo":"Testar a ampliação de 'mostrar o que falta' para 'revelar o que falta'.","palavraCritica":"incluindo os vínculos ainda não documentados"},"comentario":{"resolucao":"ERRADO. Mostrar o que ainda falta é apontar a LACUNA — indicar que há informação a buscar —, não revelar o conteúdo dessa informação. Um grafo bem feito evidencia onde os dados são insuficientes; ele não documenta vínculos que ninguém levantou. A extrapolação está em transformar diagnóstico de ausência em revelação de conteúdo.","fundamento":"Compreensão de texto — distinção entre apontar lacuna e suprir lacuna.","macete":"'Mostra o que falta' é diferente de 'mostra o que está faltando'. Um indica o buraco; o outro preencheria.","erroComum":"Aceitar por o item terminar citando corretamente a frase final do texto.","comoBancaPensa":"Ancora a extrapolação numa citação fiel, colocada no fim para dar a impressão de que o texto autoriza tudo o que veio antes."}}});
